import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary } from "../types";

/**
 * تحليل أداء الموظف بأسلوب احترافي وفاخر
 */
export const auditEmployeeFullPerformanceAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const faultyShifts = employee.shifts.filter(s => s.status === 'ناقصة');
  if (faultyShifts.length === 0) return "تحليل الذكاء الاصطناعي: السجل مثالي تماماً، التزام الموظف يعكس انضباطاً مؤسسياً عالياً.";

  const prompt = `
    حلل سجل الموظف "${employee.name}" الذي لديه ${faultyShifts.length} ورديات ناقصة.
    البيانات: ${JSON.stringify(faultyShifts.map(s => ({تاريخ: s.shift_date, بصمات: s.punches_count})))}

    المطلوب: كتابة تحليل إداري فاخر ومختصر جداً (فقرة واحدة) يوضح طبيعة الخلل وتوصية سريعة. لغة عربية فصحى احترافية.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.3, maxOutputTokens: 150 }
    });
    return response.text?.trim() || "تم التدقيق بنجاح.";
  } catch (error) {
    return "نظام AI غير متاح حالياً.";
  }
};

/**
 * الدردشة الذكية مع قاعدة البيانات
 */
export const askAiAboutData = async (employees: EmployeeSummary[], query: string): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const dataSummary = employees.map(e => ({
    name: e.name,
    score: e.performanceScore,
    isEligible: e.isEligible,
    shifts: e.shifts.length
  })).slice(0, 30); // Limit context size

  const prompt = `
    أنت مستشار إداري ذكي. لديك بيانات الموظفين التالية:
    ${JSON.stringify(dataSummary)}

    سؤال المستخدم: ${query}

    أجب بذكاء ولباقة وباختصار شديد. ركز على الأرقام والأسماء إذا طلب ذلك.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.2 }
    });
    return response.text?.trim() || "لم أستطع تحليل الطلب.";
  } catch (error) {
    return "حدث خطأ في الاتصال بالذكاء الاصطناعي.";
  }
};

export const generateBulkAuditSummaryAI = async (employees: EmployeeSummary[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const faulty = employees.filter(e => !e.isEligible).slice(0, 10);

  const prompt = `
    أنت مدير تدقيق. قم بصياغة تقرير "الرؤية الاستراتيجية" حول انضباط الموظفين.
    الموظفون المتعثرون: ${JSON.stringify(faulty.map(e => ({الاسم: e.name, الكفاءة: e.performanceScore})))}

    اكتب تقريراً بليغاً ومختصراً (حوالي 80 كلمة) يسلط الضوء على الوضع العام مع لمسة من الفخامة الإدارية.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.2 }
    });
    return response.text?.trim() || "التقرير جاهز.";
  } catch (error) {
    return "عذراً، تعذر توليد التقرير الاستراتيجي.";
  }
};

export const generateDetailedAuditSummaryAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const faultyData = employee.shifts
    .filter(s => s.status === 'ناقصة')
    .map(s => ({
      date: s.shift_date,
      missing: ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
        .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate))
    }));

  if (faultyData.length === 0) return "السجل خالي من أي ثغرات زمنية.";

  const prompt = `
    حلل نقص البصمات للموظف "${employee.name}":
    ${JSON.stringify(faultyData)}
    اكتب قائمة بالنواقص (تاريخ ونوع البصمة) بأسلوب نقطي أنيق.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text?.trim() || "لا يوجد تحليل.";
  } catch (error) {
    return "خطأ في التحليل.";
  }
};

import React, { useState, useMemo, useEffect } from 'react';
