             </div>
          </div>
        </header>

        {/* Dynamic Content */}
        <div className="flex-1 overflow-y-auto p-10 custom-scrollbar relative">

          {currentView === 'dashboard' && (
            <div className="max-w-7xl mx-auto space-y-12 animate-luxury-in">
              {stats ? (
                <>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
                    <DashboardStat title="القوة البشرية" value={stats.totalEmployees} subtitle="موظف مسجل" icon={<Users size={24}/>} color="indigo" />
                    <DashboardStat title="مؤشر الانضباط" value={`${stats.completionRate}%`} subtitle="كفاءة الحضور" icon={<TrendingUp size={24}/>} color="emerald" />
                    <DashboardStat title="سجل البصمات" value={stats.totalPunches.toLocaleString()} subtitle="عملية تم رصدها" icon={<Activity size={24}/>} color="amber" />
                    <DashboardStat title="حالات النقص" value={stats.deficientEmployees} subtitle="تتطلب تدقيقاً" icon={<AlertCircle size={24}/>} color="rose" />
