                                 </div>

                                 <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
                                    {["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"].map(periodName => {
                                      const punch = shift.punches_details.find(p => p.period === periodName && !p.is_duplicate);
                                      return (
                                        <div key={periodName} className={`p-6 rounded-[2.2rem] border-2 flex flex-col gap-4 transition-all relative overflow-hidden ${punch ? 'bg-white border-slate-100 shadow-md scale-100' : 'bg-slate-50/50 border-dashed border-slate-200 opacity-60'}`}>
                                           {punch && <div className="absolute top-0 right-0 w-1 h-full bg-indigo-500"></div>}
                                           <div className="flex items-center justify-between">
                                              <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-all ${punch ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'bg-slate-100 text-slate-400'}`}>
                                                 {getPeriodIcon(periodName)}
                                              </div>
                                              {punch ? <Check size={18} className="text-emerald-500" /> : <X size={18} className="text-rose-300" />}
                                           </div>
                                           <div className="text-right">
                                              <p className="text-[10px] font-black text-slate-400 uppercase leading-none mb-2 tracking-widest">{periodName}</p>
                                              <p className={`text-xl font-black ${punch ? 'text-slate-900' : 'text-slate-300 italic'}`}>
                                                {punch ? punch.time : 'مفقودة'}
                                              </p>
                                           </div>
                                        </div>
                                      );
                                    })}
                                 </div>
                              </div>
                           ))}
                        </div>
                    </div>
                 </div>
              </div>
           </div>
        </div>
      )}
    </>
  );
};

const ProMiniStat = ({ label, value, icon, color }: any) => {
  const themes: any = {
    indigo: "text-indigo-600 bg-indigo-50 border-indigo-100",
