const getPeriodIcon = (period: string) => {
  switch (period) {
    case 'دخول صباحي': return <Sunrise size={22} />;
    case 'بصمة وسطية': return <Sun size={22} />;
    case 'بصمة مسائية': return <Sunset size={22} />;
    case 'بصمة ليلية': return <Moon size={22} />;
    case 'بصمة خروج': return <LogOutIcon size={22} />;
    default: return <Clock size={22} />;
  }
};

