import React, { useState, useMemo, useEffect } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, Check,
  Fingerprint, Target, RefreshCcw, Clock,
  Cpu, Zap, ClipboardList, Copy, Bell, 
  X, Activity, PieChart, TrendingUp, BarChart3,
  UserCheck, AlertCircle, Briefcase, ChevronLeft,
  Sunrise, Sun, Sunset, Moon, LogOut as LogOutIcon,
  Layers, Globe, ShieldCheck, ArrowUpRight
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'intelligence';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
      deficientEmployees: employees.filter(e => !e.isEligible).length
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setBulkReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleBulkAudit = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    setCurrentView('intelligence');
    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result);
    } catch (e) { console.error(e); } finally { setIsAnalyzing(false); }
  };

  return (
    <div className="flex h-screen text-slate-900 rtl overflow-hidden select-none bg-[#f1f5f9]">

      {/* Sidebar - Modern High-Contrast */}
      <aside className={`fixed lg:static inset-y-0 right-0 z-50 w-72 xl:w-80 sidebar-gradient flex flex-col transition-all duration-700 ease-[cubic-bezier(0.16,1,0.3,1)] transform ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'}`}>
        <div className="p-8 pb-12">
           <div className="flex items-center gap-4 group cursor-pointer">
              <div className="w-14 h-14 bg-indigo-500 rounded-[1.2rem] flex items-center justify-center shadow-2xl shadow-indigo-500/40 rotate-3 group-hover:rotate-0 transition-all duration-500">
                 <ShieldCheck className="text-white" size={28} />
              </div>
              <div className="flex flex-col">
                <span className="font-black text-2xl text-white tracking-tighter leading-none">بصمتي <span className="text-indigo-400">برو</span></span>
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.3em] mt-1.5 opacity-60">Strategic Command</span>
              </div>
           </div>
        </div>

        <nav className="flex-1 px-6 space-y-3 overflow-y-auto custom-scrollbar">
          <SidebarLink icon={<LayoutDashboard size={20}/>} label="المركز الرئيسي" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <SidebarLink icon={<Users size={20}/>} label="أرشيف الكفاءات" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
          <SidebarLink icon={<BrainCircuit size={20}/>} label="الذكاء الاصطناعي" active={currentView === 'intelligence'} onClick={() => { setCurrentView('intelligence'); setIsSidebarOpen(false); }} />
        </nav>

        <div className="p-8 mt-auto">
           <label className="group relative flex items-center justify-center gap-3 w-full py-5 bg-white/5 border border-white/10 text-white rounded-[1.5rem] cursor-pointer hover:bg-white hover:text-slate-900 transition-all duration-500 text-sm font-black shadow-lg overflow-hidden active:scale-95">
              <FileUp size={18} className="group-hover:-translate-y-1 transition-transform" />
              <span>تغذية البيانات</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
           </label>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">

        {/* Floating Glass Header */}
        <header className="h-24 px-10 flex items-center justify-between shrink-0 z-20">
           <div className="flex items-center gap-8 flex-1">
             <button className="lg:hidden p-4 bg-white rounded-2xl shadow-lg text-slate-500" onClick={() => setIsSidebarOpen(true)}>
               <Menu size={22} />
             </button>
             <div className="relative max-w-2xl w-full group">
                <Search className="absolute right-6 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-500 transition-colors" size={20} />
                <input 
                  type="text" 
                  placeholder="ابحث عن الموظف أو الرقم الوظيفي..." 
                  className="w-full glass-panel rounded-3xl pr-16 pl-8 py-4 text-sm font-bold outline-none focus:ring-4 focus:ring-indigo-100 placeholder:text-slate-400"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
             </div>
          </div>

          <div className="flex items-center gap-6">
             <button 
                onClick={handleBulkAudit}
                disabled={employees.length === 0 || isAnalyzing}
                className="flex items-center gap-3 px-8 py-4 bg-slate-900 text-white rounded-3xl text-sm font-black hover:bg-indigo-600 transition-all shadow-2xl shadow-slate-900/20 active:scale-95 disabled:opacity-20"
             >
               {isAnalyzing ? <RefreshCcw size={18} className="animate-spin" /> : <Sparkles size={18} />}
               <span className="hidden xl:inline">التحليل الاستراتيجي</span>
             </button>
             <div className="h-14 w-14 glass-panel rounded-2xl flex items-center justify-center text-slate-400 relative hover:text-indigo-600 cursor-pointer group">
               <Bell size={22} className="group-hover:rotate-12 transition-transform" />
               <span className="absolute top-4 left-4 w-3 h-3 bg-rose-500 rounded-full border-2 border-white shadow-lg"></span>
             </div>
          </div>
        </header>

        {/* Dynamic Canvas */}
        <div className="flex-1 overflow-y-auto px-10 pb-16 custom-scrollbar">

          {currentView === 'dashboard' && (
            <div className="max-w-7xl mx-auto space-y-12 animate-reveal">
              {stats ? (
                <>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
