import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, Check,
  Fingerprint, RefreshCcw, Bell, 
  X, Activity, TrendingUp,
  AlertCircle, Briefcase, ChevronLeft,
  Sunrise, Sun, Sunset, Moon, LogOut as LogOutIcon,
  ShieldCheck, MoreHorizontal, UserCheck, Clock
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'ai';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
      deficientEmployees: employees.filter(e => !e.isEligible).length
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setBulkReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleAiAudit = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    setCurrentView('ai');
    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result);
    } catch (e) { console.error(e); } finally { setIsAnalyzing(false); }
  };

  return (
    <div className="flex h-screen bg-[#f0f4f8] text-[#0f172a] rtl overflow-hidden select-none">

      {/* Sidebar - Bold & Dark */}
      <aside className={`fixed lg:static inset-y-0 right-0 z-50 w-72 bg-[#0f172a] flex flex-col transition-all duration-300 transform ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'}`}>
        <div className="p-8 mb-6">
           <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-lg shadow-blue-500/20">
                 <ShieldCheck size={28} />
              </div>
              <h1 className="text-white text-2xl font-black">بصمتي <span className="text-blue-500">برو</span></h1>
           </div>
        </div>

        <nav className="flex-1 px-4 space-y-2">
          <NavItem icon={<LayoutDashboard size={20}/>} label="الرئيسية" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <NavItem icon={<Users size={20}/>} label="الموظفون" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
          <NavItem icon={<BrainCircuit size={20}/>} label="تحليل AI" active={currentView === 'ai'} onClick={() => { setCurrentView('ai'); setIsSidebarOpen(false); }} />
        </nav>

        <div className="p-6">
           <label className="flex items-center justify-center gap-3 w-full py-5 bg-blue-600 text-white rounded-2xl cursor-pointer hover:bg-blue-500 transition-all font-black text-sm shadow-xl shadow-blue-600/20">
              <FileUp size={20} />
              <span>استيراد البيانات</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
           </label>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden">
        {/* Superior Navbar */}
        <header className="h-24 bg-white/80 backdrop-blur-md border-b border-slate-200 px-10 flex items-center justify-between shrink-0 z-10">
          <div className="flex items-center gap-6 flex-1">
             <button className="lg:hidden p-3 bg-slate-100 rounded-xl text-slate-600" onClick={() => setIsSidebarOpen(true)}>
               <Menu size={24} />
             </button>
             <div className="relative max-w-xl w-full">
                <Search className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                <input 
                  type="text" 
                  placeholder="ابحث عن الموظف بالاسم أو الرقم..." 
                  className="w-full bg-slate-100/50 border border-slate-200 rounded-2xl pr-14 pl-6 py-4 text-sm font-black focus:outline-none focus:border-blue-600 focus:bg-white transition-all shadow-sm"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
             </div>
          </div>

          <div className="flex items-center gap-6">
             <button 
                onClick={handleAiAudit}
                disabled={employees.length === 0 || isAnalyzing}
                className="hidden md:flex items-center gap-3 px-8 py-4 bg-[#0f172a] text-white rounded-2xl text-sm font-black hover:bg-blue-600 transition-all shadow-lg disabled:opacity-20"
             >
               <Sparkles size={18} />
               التدقيق الذكي الشامل
             </button>
             <div className="w-12 h-12 bg-white border border-slate-200 rounded-2xl flex items-center justify-center text-slate-400 relative cursor-pointer hover:border-blue-600">
               <Bell size={22} />
               <span className="absolute top-3 left-3 w-3 h-3 bg-rose-500 rounded-full border-2 border-white"></span>
             </div>
          </div>
        </header>

        {/* Workspace */}
        <div className="flex-1 overflow-y-auto p-10 custom-scrollbar">

          {currentView === 'dashboard' && (
            <div className="max-w-7xl mx-auto space-y-12 animate-fade-in">
              {stats ? (
                <>
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
                    <StatCard title="الموظفون" value={stats.totalEmployees} icon={<Users size={24} className="text-blue-600"/>} bg="bg-blue-50" />
                    <StatCard title="كفاءة الانضباط" value={`${stats.completionRate}%`} icon={<UserCheck size={24} className="text-emerald-600"/>} bg="bg-emerald-50" />
                    <StatCard title="إجمالي البصمات" value={stats.totalPunches.toLocaleString()} icon={<Activity size={24} className="text-amber-600"/>} bg="bg-amber-50" />
                    <StatCard title="حالات الخلل" value={stats.deficientEmployees} icon={<AlertCircle size={24} className="text-rose-600"/>} bg="bg-rose-50" />
