import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, Check,
  Fingerprint, RefreshCcw, Bell, 
  X, Activity, TrendingUp,
  AlertCircle, Briefcase, ChevronLeft,
  Sunrise, Sun, Sunset, Moon, LogOut as LogOutIcon,
  ShieldCheck, MoreHorizontal, UserCheck, Clock,
  Target, Zap, ArrowUpRight
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'ai';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
      deficientEmployees: employees.filter(e => !e.isEligible).length
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setBulkReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleAiAudit = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    setCurrentView('ai');
    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result);
    } catch (e) { console.error(e); } finally { setIsAnalyzing(false); }
  };

  return (
    <div className="flex h-screen bg-[#f8fafc] text-[#0f172a] rtl overflow-hidden">

      {/* Dynamic Sidebar - Compact Design */}
      <aside className={`fixed lg:static inset-y-0 right-0 z-50 w-64 bg-white border-l border-slate-200 flex flex-col transition-all duration-300 transform ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'}`}>
        <div className="p-6">
           <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-500/10">
                 <ShieldCheck size={24} />
              </div>
              <h1 className="text-xl font-black tracking-tight">بصمتي <span className="text-blue-600">برو</span></h1>
           </div>
        </div>

        <nav className="flex-1 px-3 space-y-1 mt-4">
          <NavItem icon={<LayoutDashboard size={18}/>} label="الرئيسية" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <NavItem icon={<Users size={18}/>} label="الموظفون" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
          <NavItem icon={<BrainCircuit size={18}/>} label="تحليل AI" active={currentView === 'ai'} onClick={() => { setCurrentView('ai'); setIsSidebarOpen(false); }} />
        </nav>

        <div className="p-4">
           <label className="flex items-center justify-center gap-2 w-full py-4 bg-slate-900 text-white rounded-xl cursor-pointer hover:bg-slate-800 transition-all font-black text-xs shadow-lg">
              <FileUp size={16} />
              <span>رفع البيانات</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
           </label>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0">
        {/* Dynamic Header */}
        <header className="h-16 bg-white border-b border-slate-200 px-6 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4 flex-1">
             <button className="lg:hidden p-2 text-slate-500" onClick={() => setIsSidebarOpen(true)}>
               <Menu size={20} />
             </button>
             <div className="relative max-w-md w-full">
                <Search className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
                <input 
                  type="text" 
                  placeholder="ابحث..." 
                  className="w-full bg-slate-100 border-none rounded-lg pr-10 pl-4 py-2 text-xs font-black focus:outline-none focus:ring-2 focus:ring-blue-500/20"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
             </div>
          </div>

          <div className="flex items-center gap-3">
             <button 
                onClick={handleAiAudit}
                disabled={employees.length === 0 || isAnalyzing}
                className="hidden sm:flex items-center gap-2 px-4 py-2 bg-blue-50 text-blue-600 rounded-lg text-xs font-black hover:bg-blue-100 disabled:opacity-30"
             >
               <Sparkles size={14} />
               تدقيق AI
             </button>
             <div className="w-9 h-9 bg-slate-100 rounded-lg flex items-center justify-center text-slate-400 cursor-pointer hover:bg-slate-200">
               <Bell size={18} />
             </div>
          </div>
        </header>

        {/* Bento Workspace */}
        <div className="flex-1 overflow-y-auto p-6 bento-scroll">

          {currentView === 'dashboard' && (
            <div className="max-w-screen-2xl mx-auto h-full flex flex-col gap-6 animate-bento">
              {stats ? (
                <>
                  {/* Stats Bento Grid Row */}
                  <div className="grid grid-cols-1 md:grid-cols-4 gap-4 shrink-0">
                    <BentoStat title="إجمالي الموظفين" value={stats.totalEmployees} icon={<Users className="text-blue-500"/>} subtitle="نشط" />
                    <BentoStat title="معدل الانضباط" value={`${stats.completionRate}%`} icon={<Zap className="text-amber-500"/>} subtitle="أداء عام" />
                    <BentoStat title="إجمالي البصمات" value={stats.totalPunches} icon={<Fingerprint className="text-emerald-500"/>} subtitle="عملية مسجلة" />
                    <BentoStat title="حالات النقص" value={stats.deficientEmployees} icon={<AlertCircle className="text-rose-500"/>} subtitle="تنبيه إداري" />
                  </div>

                  {/* Main Bento Area */}
                  <div className="flex-1 min-h-0 grid grid-cols-1 lg:grid-cols-12 gap-6">
                    {/* Left: Employee Grid (Bento Style) */}
                    <div className="lg:col-span-8 flex flex-col gap-4 overflow-hidden">
                       <div className="flex items-center justify-between px-2">
                          <h2 className="text-lg font-black text-slate-800">سجل الموظفين الأخير</h2>
