const getPeriodIcon = (period: string) => {
  switch (period) {
    case 'دخول صباحي': return <Sunrise size={14} />;
    case 'بصمة وسطية': return <Sun size={14} />;
    case 'بصمة مسائية': return <Sunset size={14} />;
    case 'بصمة ليلية': return <Moon size={14} />;
    case 'بصمة خروج': return <LogOutIcon size={14} />;
    default: return <Clock size={14} />;
  }
};

