import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, Check,
  Fingerprint, RefreshCcw, Bell, 
  X, Activity, TrendingUp,
  AlertCircle, Briefcase, ChevronLeft,
  Sunrise, Sun, Sunset, Moon, LogOut as LogOutIcon,
  ShieldCheck, MoreHorizontal, UserCheck, Clock,
  Target, Zap, ArrowUpRight, Info
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'ai';

const BENTO_COLORS = [
  'bg-bento-lavender',
  'bg-bento-pink',
  'bg-bento-yellow',
  'bg-bento-peach',
  'bg-bento-mint',
  'bg-bento-sky'
];

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
      deficientEmployees: employees.filter(e => !e.isEligible).length
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setBulkReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleAiAudit = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    setCurrentView('ai');
    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result);
    } catch (e) { console.error(e); } finally { setIsAnalyzing(false); }
  };

  return (
    <div className="flex h-screen bg-[#ffffff] text-[#1e293b] rtl overflow-hidden">

      {/* Navbar Minimalist */}
      <aside className={`fixed lg:static inset-y-0 right-0 z-50 w-72 bg-slate-50 border-l border-slate-100 flex flex-col transition-all duration-300 transform ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'}`}>
        <div className="p-10">
           <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-blue-500/20">
                 <ShieldCheck size={28} />
              </div>
              <h1 className="text-2xl font-black tracking-tight">بصمتي <span className="text-blue-600">برو</span></h1>
           </div>
        </div>

        <nav className="flex-1 px-6 space-y-2 mt-4">
          <NavItem icon={<LayoutDashboard size={20}/>} label="لوحة التحكم" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <NavItem icon={<Users size={20}/>} label="سجل الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
          <NavItem icon={<BrainCircuit size={20}/>} label="الذكاء الاصطناعي" active={currentView === 'ai'} onClick={() => { setCurrentView('ai'); setIsSidebarOpen(false); }} />
        </nav>

        <div className="p-8">
           <label className="flex items-center justify-center gap-3 w-full py-5 bg-blue-600 text-white rounded-[1.5rem] cursor-pointer hover:bg-blue-700 transition-all font-black text-sm shadow-xl shadow-blue-600/10">
              <FileUp size={20} />
              <span>استيراد Excel</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
           </label>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-white">
        {/* Superior Header */}
        <header className="h-24 px-10 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-8 flex-1">
             <button className="lg:hidden p-3 bg-slate-100 rounded-2xl" onClick={() => setIsSidebarOpen(true)}>
               <Menu size={24} />
             </button>
             <div className="relative max-w-xl w-full">
                <Search className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
                <input 
                  type="text" 
                  placeholder="ابحث عن أي موظف أو سجل..." 
                  className="w-full bg-slate-50 border-none rounded-[1.5rem] pr-14 pl-6 py-4 text-sm font-black focus:outline-none focus:ring-2 focus:ring-blue-500/10 transition-all"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
             </div>
          </div>

          <div className="flex items-center gap-6">
             <button 
                onClick={handleAiAudit}
                disabled={employees.length === 0 || isAnalyzing}
                className="hidden md:flex items-center gap-3 px-8 py-4 bg-slate-900 text-white rounded-[1.5rem] text-sm font-black hover:bg-blue-600 transition-all disabled:opacity-30"
             >
               <Sparkles size={18} />
               التدقيق الذكي
             </button>
             <div className="w-14 h-14 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-400 cursor-pointer hover:bg-slate-100 transition-colors">
               <Bell size={24} />
             </div>
          </div>
        </header>

        {/* Bento Space */}
        <div className="flex-1 overflow-y-auto px-10 pb-10 bento-scroll">

          {currentView === 'dashboard' && (
            <div className="max-w-screen-2xl mx-auto h-full flex flex-col gap-8 animate-bento">
              {stats ? (
                <>
                  {/* Summary Bento Grid */}
                  <div className="grid grid-cols-1 md:grid-cols-4 gap-6 shrink-0">
                    <BentoStatBlock title="إجمالي الموظفين" value={stats.totalEmployees} icon={<Users size={28}/>} color="bg-bento-sky" />
                    <BentoStatBlock title="معدل الانضباط" value={`${stats.completionRate}%`} icon={<UserCheck size={28}/>} color="bg-bento-mint" />
                    <BentoStatBlock title="عمليات البصمة" value={stats.totalPunches} icon={<Fingerprint size={28}/>} color="bg-bento-lavender" />
                    <BentoStatBlock title="حالات النقص" value={stats.deficientEmployees} icon={<AlertCircle size={28}/>} color="bg-bento-pink" />
                  </div>

                  {/* Dynamic Bento Content Area */}
                  <div className="flex-1 min-h-0 grid grid-cols-1 lg:grid-cols-12 gap-8">

                    {/* Employee Grid - Dynamic sizes */}
                    <div className="lg:col-span-9 flex flex-col gap-6 overflow-hidden">
                       <div className="flex items-center justify-between">
                          <h2 className="text-2xl font-black text-slate-900">سجل النشاط الرقمي</h2>
                          <div className="flex items-center gap-2 text-blue-600 font-black text-sm cursor-pointer hover:underline" onClick={() => setCurrentView('employees')}>
                             شاهد الجميع <ArrowUpRight size={18} />
                          </div>
                       </div>
                       <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-6 overflow-y-auto bento-scroll pr-2 pb-6">
                          {filteredEmployees.slice(0, 15).map((emp, idx) => (
                            <BentoEmployeeCard 
                              key={emp.id} 
                              employee={emp} 
                              colorClass={BENTO_COLORS[idx % BENTO_COLORS.length]} 
                            />
                          ))}
                       </div>
                    </div>

                    {/* Side Bento Feature */}
                    <div className="lg:col-span-3 flex flex-col gap-6">
                       <div className="bento-card bg-slate-900 text-white flex-1 p-10 flex flex-col justify-between">
                          <div>
                             <h3 className="text-2xl font-black mb-4 flex items-center gap-3">
                                <BrainCircuit className="text-blue-400" size={32} />
                                الرؤية الذكية
                             </h3>
                             <p className="text-sm font-bold text-slate-400 leading-loose">
