const getPeriodIcon = (period: string) => {
  switch (period) {
    case 'دخول صباحي': return <Sunrise size={18} />;
    case 'بصمة وسطية': return <Sun size={18} />;
    case 'بصمة مسائية': return <Sunset size={18} />;
    case 'بصمة ليلية': return <Moon size={18} />;
    case 'بصمة خروج': return <LogOutIcon size={18} />;
    default: return <Clock size={18} />;
  }
};

