import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary } from "../types";

/**
 * التدقيق التقني السريع (سجل سليم/خلل مزامنة)
 */
export const auditEmployeeFullPerformanceAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const complexitySample = employee.shifts
    .filter(s => s.status === 'ناقصة')
    .slice(0, 5); 

  if (complexitySample.length === 0) return "✅ السجل التقني سليم.";

  const prompt = `
    دقق بيانات الموظف تقنياً: ${employee.name}
    النواقص المكتشفة: ${JSON.stringify(complexitySample.map(s => ({d: s.shift_date, p: s.punches_count})))}
    أجب بكلمتين فقط لوصف الحالة التقنية: "سجل سليم" أو "خلل مزامنة".
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.1, maxOutputTokens: 20 }
    });
    return response.text?.trim() || "تم التدقيق.";
  } catch (error) {
    return "⚠️ خطأ.";
  }
};

/**
 * ملخص التدقيق الفردي للموظف (كشف فني للنواقص فقط)
 */
export const generateDetailedAuditSummaryAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const faultyData = employee.shifts
    .filter(s => s.status === 'ناقصة')
    .map(s => ({
      date: s.shift_date,
      missing: ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
        .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate))
    }));

  if (faultyData.length === 0) return "✨ السجل الرقمي لهذا الموظف كامل بنسبة 100%.";

  const prompt = `
    أنت نظام تدقيق تقني. حلل النواقص في سجل بصمة الموظف "${employee.name}":
    ${JSON.stringify(faultyData)}

    المطلوب رد مباشر على شكل قائمة نقطية تقنية:
    - [التاريخ]: مفقود [الفترات]

    ملاحظة: لا تقدم أي نصائح أو توصيات، فقط اسرد النواقص التقنية.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.1 }
    });
    return response.text?.trim() || "لا توجد ملاحظات تقنية.";
  } catch (error) {
    return "⚠️ تعذر رصد النواقص.";
  }
};

/**
 * تدقيق البصمات الجماعي (تحليل شامل للنواقص لكامل الدفعة)
 */
export const generateBulkAuditSummaryAI = async (employees: EmployeeSummary[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const faultyEmployees = employees
    .filter(e => !e.isEligible)
    .slice(0, 30)
    .map(e => ({
      name: e.name,
      missingPunchesCount: e.shifts.filter(s => s.status === 'ناقصة').length
    }));

  if (faultyEmployees.length === 0) return "✅ تم فحص الدفعة بالكامل: جميع السجلات مطابقة للمعايير التقنية.";

  const prompt = `
    أنت محرك تدقيق بيانات. إليك قائمة بالموظفين الذين لديهم "نواقص تقنية" في البصمات:
    ${JSON.stringify(faultyEmployees)}

    المطلوب:
    قدم تقريراً تقنياً إحصائياً يوضح حجم النواقص في هذه الدفعة، واذكر أسماء الموظفين الأكثر تأثراً بالفقدان الرقمي للبصمات. 
    اجعل التقرير موضوعياً ومختصراً جداً.
    تنبيه: لا تذكر أي توصيات إدارية أو نصائح سلوكية، فقط الحقائق التقنية للنواقص.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.2 }
    });
    return response.text?.trim() || "فشل توليد التدقيق الجماعي.";
  } catch (error) {
    console.error(error);
    return "⚠️ حدث خطأ أثناء التدقيق الجماعي.";
  }
};

import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, Check,
  Fingerprint, RefreshCcw, Bell, 
  X, Activity, TrendingUp,
  AlertCircle, Briefcase, ChevronLeft,
  Sunrise, Sun, Sunset, Moon, LogOut as LogOutIcon,
  ShieldCheck, MoreHorizontal, UserCheck, Clock,
  Target, Zap, ArrowUpRight, Info
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'ai';

const BENTO_COLORS = [
  'bg-bento-lavender',
  'bg-bento-pink',
  'bg-bento-yellow',
  'bg-bento-peach',
  'bg-bento-mint',
  'bg-bento-sky'
];

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
      deficientEmployees: employees.filter(e => !e.isEligible).length
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setBulkReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleAiAudit = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    setCurrentView('ai');
    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result);
    } catch (e) { console.error(e); } finally { setIsAnalyzing(false); }
  };

  return (
    <div className="flex h-screen bg-white text-[#1e293b] rtl overflow-hidden">

      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 right-0 z-50 w-64 bg-slate-50 border-l border-slate-100 flex flex-col transition-all duration-300 transform ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'}`}>
        <div className="p-8">
           <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-500/20">
                 <ShieldCheck size={24} />
              </div>
              <h1 className="text-xl font-black tracking-tight">بصمتي <span className="text-blue-600">برو</span></h1>
           </div>
        </div>

        <nav className="flex-1 px-4 space-y-1 mt-2">
