import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary } from "../types";

/**
 * ملخص التدقيق الفني الفردي (كشف تقني للنواقص فقط)
 */
export const generateDetailedAuditSummaryAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const faultyData = employee.shifts
    .filter(s => s.status === 'ناقصة')
    .map(s => ({
      date: s.shift_date,
      missing: ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
        .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate))
    }));

  if (faultyData.length === 0) return "✨ السجل التقني لهذا الموظف سليم ومكتمل بنسبة 100%.";

  const prompt = `
    أنت محرك تدقيق تقني متخصص في أنظمة البصمة. المطلوب تحليل النواقص في سجل الموظف "${employee.name}":
    البيانات الخام للنواقص: ${JSON.stringify(faultyData)}

    التعليمات الصارمة:
    1. قدم سرداً تقنياً للنواقص فقط.
    2. استخدم صيغة: [التاريخ]: مفقود ([أسماء البصمات المفقودة]).
    3. ممنوع تماماً تقديم أي نصائح إدارية، سلوكية، أو توصيات للتعامل مع الموظف.
    4. اجعل الرد جافاً وتقنياً.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.1 }
    });
    return response.text?.trim() || "تعذر استخراج البيانات التقنية.";
  } catch (error) {
    return "⚠️ خطأ في معالجة السجل الرقمي.";
  }
};

/**
 * تدقيق البصمات الجماعي (تحليل إحصائي للنواقص لكامل الدفعة)
 */
export const generateBulkAuditSummaryAI = async (employees: EmployeeSummary[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const faultyEmployees = employees
    .filter(e => !e.isEligible)
    .slice(0, 40)
    .map(e => ({
      name: e.name,
      id: e.id,
      missingDays: e.shifts.filter(s => s.status === 'ناقصة').length
    }));

  if (faultyEmployees.length === 0) return "✅ تم فحص الدفعة بالكامل: لا توجد فجوات تقنية في البيانات المرفوعة.";

  const prompt = `
    أنت محرك فحص بيانات رقمي. إليك قائمة بالموظفين الذين يعانون من فجوات تقنية في سجلات البصمة:
    ${JSON.stringify(faultyEmployees)}

    المطلوب:
    1. تحليل إحصائي تقني لحجم البيانات المفقودة في هذه الدفعة.
    2. ذكر أسماء الموظفين الذين يعانون من أعلى معدل فقدان رقمي للبصمات.
    3. لا تذكر أي توصيات إدارية أو حلول للمشكلة، فقط صف الحالة التقنية للبيانات.
    4. التقرير يجب أن يكون مختصراً ومباشراً.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.2 }
    });
    return response.text?.trim() || "فشل توليد التقرير الجماعي.";
  } catch (error) {
    console.error(error);
    return "⚠️ حدث خطأ تقني أثناء الفحص الجماعي.";
  }
};

