import { generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'ai';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
      deficientEmployees: employees.filter(e => !e.isEligible).length
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setBulkReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleAiAudit = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    setCurrentView('ai');
    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result);
    } catch (e) { console.error(e); } finally { setIsAnalyzing(false); }
  };

  return (
    <div className="flex h-screen bg-[#ffffff] text-[#1e293b] rtl overflow-hidden">

      {/* Sidebar - Compact and Logical */}
      <aside className={`fixed lg:static inset-y-0 right-0 z-50 w-64 bg-slate-50 border-l border-slate-100 flex flex-col transition-all duration-300 transform ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'}`}>
        <div className="p-8">
           <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg">
                 <ShieldCheck size={24} />
              </div>
              <h1 className="text-xl font-black tracking-tight">بصمتي <span className="text-blue-600">برو</span></h1>
           </div>
        </div>

        <nav className="flex-1 px-4 space-y-1 mt-2">
          <NavItem icon={<LayoutDashboard size={18}/>} label="لوحة المعلومات" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <NavItem icon={<Users size={18}/>} label="سجل الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
          <NavItem icon={<BrainCircuit size={18}/>} label="التدقيق الجماعي" active={currentView === 'ai'} onClick={() => { setCurrentView('ai'); setIsSidebarOpen(false); }} />
        </nav>

        <div className="p-6">
           <label className="flex items-center justify-center gap-2 w-full py-4 bg-blue-600 text-white rounded-2xl cursor-pointer hover:bg-blue-700 transition-all font-black text-xs shadow-lg">
              <FileUp size={16} />
              <span>رفع ملف جديد</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
           </label>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        {/* Superior Header */}
        <header className="h-20 px-6 lg:px-10 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4 flex-1">
             <button className="lg:hidden p-2 bg-slate-100 rounded-xl" onClick={() => setIsSidebarOpen(true)}>
               <Menu size={20} />
             </button>
             <div className="relative max-w-lg w-full">
                <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  type="text" 
                  placeholder="بحث سريع..." 
                  className="w-full bg-slate-50 border-none rounded-2xl pr-12 pl-4 py-3 text-xs font-black focus:outline-none focus:ring-2 focus:ring-blue-500/10 transition-all"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
             </div>
          </div>

          <div className="flex items-center gap-4">
             <button 
                onClick={handleAiAudit}
                disabled={employees.length === 0 || isAnalyzing}
                className="hidden sm:flex items-center gap-2 px-6 py-3 bg-slate-900 text-white rounded-2xl text-[10px] font-black hover:bg-blue-600 transition-all disabled:opacity-30"
             >
               <Sparkles size={14} />
               تحليل نواقص الدفعة
             </button>
             <div className="w-10 h-10 bg-slate-50 rounded-xl flex items-center justify-center text-slate-400">
               <Bell size={20} />
             </div>
          </div>
        </header>

        {/* Bento Space */}
        <div className="flex-1 overflow-y-auto px-6 lg:px-10 pb-10 bento-scroll">

          {currentView === 'dashboard' && (
            <div className="max-w-screen-2xl mx-auto h-full flex flex-col gap-6 animate-bento">
              {stats ? (
                <>
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4 shrink-0">
                    <BentoStat title="إجمالي الموظفين" value={stats.totalEmployees} icon={<Users size={20}/>} color="bg-[#E0F2FE]" />
                    <BentoStat title="نسبة الانضباط" value={`${stats.completionRate}%`} icon={<UserCheck size={20}/>} color="bg-[#DCFCE7]" />
                    <BentoStat title="بصمات مسجلة" value={stats.totalPunches} icon={<Fingerprint size={20}/>} color="bg-[#F3E8FF]" />
                    <BentoStat title="سجلات ناقصة" value={stats.deficientEmployees} icon={<AlertCircle size={20}/>} color="bg-[#FCE7F3]" />
                  </div>

                  <div className="flex-1 min-h-0 grid grid-cols-1 lg:grid-cols-12 gap-6">
                    <div className="lg:col-span-9 flex flex-col gap-4 overflow-hidden">
                       <h2 className="text-xl font-black text-slate-900 px-2">مراقبة السجلات الرقمية</h2>
                       <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-4 overflow-y-auto bento-scroll pr-2 pb-6">
                          {filteredEmployees.slice(0, 24).map((emp) => (
                            <BentoEmployeeCard 
                              key={emp.id} 
                              employee={emp} 
                            />
                          ))}
                       </div>
                    </div>

                    <div className="lg:col-span-3 flex flex-col gap-6">
                       <div className="bento-card bg-slate-900 text-white flex-1 p-8 flex flex-col justify-between border-none">
                          <div>
                             <h3 className="text-xl font-black mb-4 flex items-center gap-3">
                                <BrainCircuit className="text-blue-400" size={28} />
                                المدقق الرقمي الجماعي
                             </h3>
                             <p className="text-[11px] font-bold text-slate-400 leading-relaxed italic">
                                يقوم النظام بمسح شامل لجميع الموظفين المرفوعين لاكتشاف النواقص التقنية فورياً دون أي تدخل بشري.
                             </p>
                          </div>
                          <button onClick={handleAiAudit} className="w-full py-4 bg-blue-600 rounded-2xl font-black text-xs hover:bg-blue-500 transition-all flex items-center justify-center gap-2">
                             ابدأ التدقيق الجماعي <Sparkles size={14} />
                          </button>
                       </div>
                    </div>
                  </div>
                </>
              ) : <BentoEmptyState handleFileUpload={handleFileUpload} />}
            </div>
          )}

          {currentView === 'employees' && (
            <div className="max-w-screen-2xl mx-auto animate-bento">
              <h2 className="text-3xl font-black text-slate-900 mb-8 px-2">جميع سجلات الحضور</h2>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-4">
                {filteredEmployees.map((emp) => (
                  <BentoEmployeeCard 
                    key={emp.id} 
                    employee={emp} 
                  />
                ))}
              </div>
            </div>
          )}

          {currentView === 'ai' && (
            <div className="max-w-3xl mx-auto h-full flex flex-col py-6 animate-bento">
               <div className="bento-card bg-white border border-slate-100 flex-1 flex flex-col p-10 relative">
                  <div className="flex items-center gap-4 mb-8">
                    <div className="w-12 h-12 bg-slate-900 text-blue-400 rounded-2xl flex items-center justify-center shadow-lg">
                       <BrainCircuit size={24} />
                    </div>
                    <h2 className="text-xl font-black text-slate-900">تقرير النواقص التقنية (الجماعي)</h2>
                  </div>
                  <div className="flex-1 bg-slate-50 p-8 rounded-[2rem] overflow-y-auto bento-scroll border border-slate-100 text-slate-800 text-sm font-bold leading-relaxed shadow-inner">
                    {isAnalyzing ? (
                      <div className="h-full flex flex-col items-center justify-center gap-4 opacity-40">
                         <RefreshCcw className="animate-spin text-blue-600" size={32} />
                         <span className="text-[10px] font-black">جاري جرد النواقص الرقمية...</span>
                      </div>
                    ) : (
                      <div className="whitespace-pre-line">{bulkReport || "ارفع الملف واطلب التدقيق الجماعي لعرض الإحصائيات هنا."}</div>
                    )}
                  </div>
               </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

/* --- Dynamic Bento Components --- */

const NavItem = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-3 px-5 py-4 rounded-2xl text-[11px] font-black transition-all ${active ? 'nav-active' : 'text-slate-500 hover:bg-white'}`}>
    {icon}
    <span>{label}</span>
  </button>
);

const BentoStat = ({ title, value, icon, color }: any) => (
  <div className={`bento-card ${color} border-none p-6 flex flex-col justify-center`}>
     <div className="flex items-center justify-between mb-2">
        <div className="p-2 bg-white/40 rounded-xl text-slate-800">{icon}</div>
        <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest">{title}</span>
     </div>
     <h4 className="text-2xl font-black text-slate-900 leading-none">{value}</h4>
  </div>
);

const BentoEmployeeCard = ({ employee }: { employee: EmployeeSummary }) => {
  const [showModal, setShowModal] = useState(false);
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const isComplete = employee.isEligible;

  const handleAiAudit = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoadingAi(true);
    const report = await generateDetailedAuditSummaryAI(employee);
    setAiReport(report);
    setLoadingAi(false);
  };

  return (
    <>
      <div 
        onClick={() => setShowModal(true)} 
        className={`bento-card ${isComplete ? 'bg-[#DCFCE7]' : 'bg-[#FCE7F3]'} border-none group cursor-pointer p-6 flex flex-col gap-4 h-auto min-h-[180px] hover:scale-[1.03] shadow-sm`}
      >
        <div className="flex items-center justify-between gap-2 overflow-hidden">
           <div className="flex items-center gap-3 min-w-0">
              <div className="w-10 h-10 shrink-0 bg-white rounded-xl flex items-center justify-center font-black text-slate-900 text-lg group-hover:bg-slate-900 group-hover:text-white transition-all shadow-sm">
                {employee.name.charAt(0)}
              </div>
              <div className="min-w-0">
                 <h3 className="text-[12px] font-black text-slate-900 truncate leading-tight mb-1">{employee.name}</h3>
                 <span className="text-[9px] font-black text-slate-500 opacity-60">ID: #{employee.id}</span>
              </div>
           </div>
           <div className={`shrink-0 px-3 py-1 rounded-lg text-[9px] font-black uppercase ${isComplete ? 'bg-emerald-200 text-emerald-800' : 'bg-rose-200 text-rose-800'}`}>
              {isComplete ? 'مكتمل' : 'ناقص'}
           </div>
        </div>

        <div className="flex items-end justify-between mt-auto border-t border-black/5 pt-4">
           <div className="flex flex-col">
              <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1">عدد البصمات</span>
              <div className="flex items-center gap-2">
                 <div className="w-7 h-7 bg-white rounded-lg flex items-center justify-center text-blue-600 shadow-sm">
                    <Fingerprint size={14} />
                 </div>
                 <span className="text-lg font-black text-slate-900 leading-none">{employee.totalPunches}</span>
              </div>
           </div>
           <button 
             onClick={handleAiAudit}
             disabled={loadingAi}
             title="تدقيق تقني فوري"
             className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-slate-800 hover:bg-slate-900 hover:text-white transition-all shadow-sm active:scale-95"
           >
              {loadingAi ? <RefreshCcw size={16} className="animate-spin" /> : <BrainCircuit size={16} />}
           </button>
        </div>

        {aiReport && (
          <div className="absolute inset-0 bg-slate-900/95 p-6 text-white flex flex-col justify-center animate-bento z-20 rounded-[2.5rem]">
             <button onClick={(e) => { e.stopPropagation(); setAiReport(null); }} className="absolute top-4 left-4 text-slate-500 hover:text-white"><X size={18}/></button>
             <h4 className="text-blue-400 text-[9px] font-black mb-3 uppercase tracking-widest border-b border-white/10 pb-2 flex items-center gap-2">
               <Sparkles size={14}/> التدقيق التقني
             </h4>
             <div className="text-[10px] font-bold leading-relaxed overflow-y-auto bento-scroll max-h-[100px]">
                {aiReport}
             </div>
          </div>
        )}
      </div>

      {showModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 lg:p-10 bg-slate-900/40 backdrop-blur-md overflow-hidden">
           <div className="bg-white w-full max-w-5xl h-full max-h-[90vh] rounded-[2.5rem] overflow-hidden flex flex-col shadow-3xl animate-bento">
              <div className="p-6 lg:p-10 border-b border-slate-100 flex items-center justify-between shrink-0 bg-slate-50/50">
                 <div className="flex items-center gap-6">
                    <div className="w-16 h-16 lg:w-20 lg:h-20 bg-slate-900 text-white rounded-3xl flex items-center justify-center font-black text-2xl lg:text-3xl shadow-xl">
                       {employee.name.charAt(0)}
                    </div>
                    <div>
                       <h2 className="text-xl lg:text-3xl font-black text-slate-900 leading-none mb-2">{employee.name}</h2>
                       <div className="flex flex-wrap items-center gap-4 text-[10px] lg:text-xs font-black text-slate-400">
                          <p className="flex items-center gap-2"><Target size={16} className="text-blue-600" /> الرقم الوظيفي: #{employee.id}</p>
                          <p className="flex items-center gap-2"><Calendar size={16} className="text-blue-600" /> إجمالي النوبات: {employee.shifts.length}</p>
                       </div>
                    </div>
                 </div>
                 <button onClick={() => setShowModal(false)} className="w-12 h-12 lg:w-16 lg:h-16 bg-white border border-slate-100 text-slate-500 rounded-2xl hover:bg-rose-50 hover:text-rose-600 transition-all flex items-center justify-center">
                    <X size={24} />
                 </button>
              </div>

              <div className="flex-1 overflow-y-auto p-6 lg:p-10 bento-scroll bg-white">
                 <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
                    <div className="lg:col-span-4 space-y-4">
                       <BentoDetailBox title="معدل الاكتمال" value={`%${employee.performanceScore}`} label="الدقة التقنية" color="bg-[#F3E8FF]" />
                       <BentoDetailBox title="إجمالي البصمات" value={employee.totalPunches} label="مسجلة في السجل" color="bg-[#E0F2FE]" />
                       <div className="bento-card bg-slate-100 p-6 flex items-center justify-center border-none">
                          <Fingerprint size={40} className="text-slate-300" />
                       </div>
                    </div>

                    <div className="lg:col-span-8 space-y-6">
                       <h3 className="text-lg font-black text-slate-900 flex items-center gap-3">
                          <div className="w-1.5 h-6 bg-blue-600 rounded-full"></div>
                          كشف الورديات الرقمي
                       </h3>
                       <div className="space-y-4 pb-10">
                          {employee.shifts.map((shift, i) => (
                             <div key={i} className={`p-6 rounded-3xl border ${shift.status === 'مكتملة' ? 'border-emerald-100 bg-emerald-50/20' : 'border-rose-100 bg-rose-50/20'} hover:shadow-lg transition-all`}>
                                <div className="flex justify-between items-center mb-6">
                                   <div className="flex items-center gap-3">
                                      <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-white ${shift.status === 'مكتملة' ? 'bg-emerald-500' : 'bg-rose-500 shadow-rose-200 shadow-lg'}`}>
                                         <Clock size={18} />
                                      </div>
                                      <div>
                                         <span className="font-black text-sm text-slate-900 block leading-none mb-1">{shift.shift_date}</span>
                                         <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">الحالة: {shift.status}</span>
                                      </div>
                                   </div>
                                </div>
                                <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-5 gap-3">
                                   {["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"].map(period => {
                                     const punch = shift.punches_details.find(p => p.period === period && !p.is_duplicate);
                                     return (
                                       <div key={period} className={`p-4 rounded-2xl border flex flex-col gap-2 transition-all ${punch ? 'border-blue-100 bg-blue-50/40 shadow-sm' : 'border-slate-100 bg-white opacity-40'}`}>
                                          <div className="flex items-center justify-between">
                                             <div className={`p-1.5 rounded-lg ${punch ? 'bg-blue-600 text-white' : 'bg-slate-200 text-slate-400'}`}>
                                                {getPeriodIcon(period)}
                                             </div>
                                             {punch && <Check size={12} className="text-emerald-500" />}
                                          </div>
                                          <div className="min-w-0">
                                             <p className="text-[8px] font-black text-slate-400 uppercase truncate mb-0.5">{period}</p>
                                             <p className={`text-[11px] font-black ${punch ? 'text-slate-900' : 'text-slate-200 italic'}`}>
                                               {punch ? punch.time : 'مفقود'}
                                             </p>
                                          </div>
                                       </div>
                                     );
                                   })}
                                </div>
                             </div>
                          ))}
                       </div>
                    </div>
                 </div>
              </div>
           </div>
        </div>
      )}
    </>
  );
};

const BentoDetailBox = ({ title, value, label, color }: any) => (
  <div className={`p-6 rounded-[2rem] ${color} text-center flex flex-col justify-center min-h-[120px]`}>
     <p className="text-[9px] font-black text-slate-500 uppercase mb-1 tracking-widest">{title}</p>
     <p className="text-3xl font-black text-slate-900 leading-none">{value}</p>
     <p className="text-[9px] font-black text-slate-400 uppercase mt-2">{label}</p>
  </div>
);

const BentoEmptyState = ({ handleFileUpload }: any) => (
  <div className="h-full flex flex-col items-center justify-center text-center animate-bento p-6">
     <div className="w-24 h-24 lg:w-32 lg:h-32 bg-slate-50 text-blue-600 rounded-[2.5rem] flex items-center justify-center shadow-xl mb-8 -rotate-3 hover:rotate-0 transition-all cursor-pointer">
        <Fingerprint size={50} />
     </div>
     <h3 className="text-3xl lg:text-5xl font-black text-slate-900 mb-4 tracking-tighter">بصمتي برو | التدقيق الرقمي</h3>
     <p className="text-sm lg:text-xl text-slate-400 font-bold max-w-lg mx-auto leading-relaxed mb-8 opacity-70">
        نظام ذكي متخصص في رصد الفجوات التقنية في سجلات البصمة باستخدام تقنيات Bento Grid.
     </p>
     <label className="px-10 py-4 bg-blue-600 text-white rounded-2xl font-black cursor-pointer hover:bg-blue-700 transition-all shadow-xl shadow-blue-500/20 text-sm">
        تحميل سجلات Excel
        <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
     </label>
  </div>
);

const getPeriodIcon = (period: string) => {
  const size = 14;
  switch (period) {
    case 'دخول صباحي': return <Sunrise size={size} />;
    case 'بصمة وسطية': return <Sun size={size} />;
    case 'بصمة مسائية': return <Sunset size={size} />;
    case 'بصمة ليلية': return <Moon size={size} />;
    case 'بصمة خروج': return <LogOutIcon size={size} />;
    default: return <Clock size={size} />;
  }
};

export default App;

import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, Check,
  Fingerprint, RefreshCcw, Bell, 
  X, Activity, TrendingUp,
  AlertCircle, Briefcase, ChevronLeft,
  Sunrise, Sun, Sunset, Moon, LogOut as LogOutIcon,
  ShieldCheck, MoreHorizontal, UserCheck, Clock,
  Target, Zap, ArrowUpRight, Info,
  ClipboardCheck, FileWarning
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'ai';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
      deficientEmployees: employees.filter(e => !e.isEligible).length
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setBulkReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleAiAudit = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    setCurrentView('ai');
    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result);
    } catch (e) { console.error(e); } finally { setIsAnalyzing(false); }
  };

  return (
    <div className="flex h-screen bg-[#ffffff] text-[#1e293b] rtl overflow-hidden">

      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 right-0 z-50 w-64 bg-slate-50 border-l border-slate-100 flex flex-col transition-all duration-300 transform ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'}`}>
