} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'ai';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
      deficientEmployees: employees.filter(e => !e.isEligible).length
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setBulkReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleAiAudit = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    setCurrentView('ai');
    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result);
    } catch (e) { console.error(e); } finally { setIsAnalyzing(false); }
  };

  const exportAuditToExcel = () => {
    if (employees.length === 0) return;

    const exportData = employees.map(emp => {
      const missingDaysDetails = emp.shifts
        .filter(s => s.status === 'ناقصة')
        .map(s => {
          const missingPeriods = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
            .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate));
          return `${s.shift_date}: (${missingPeriods.join(' - ')})`;
        }).join(' | ');

      return {
        "الرقم الوظيفي": emp.id,
        "اسم الموظف": emp.name,
        "حالة السجل": emp.isEligible ? "مكتمل" : "ناقص",
        "درجة الأداء الرقمي %": emp.performanceScore,
        "إجمالي البصمات": emp.totalPunches,
        "عدد الورديات الناقصة": emp.shifts.filter(s => s.status === 'ناقصة').length,
        "تفاصيل البصمات الناقصة": missingDaysDetails || "لا يوجد نواقص"
      };
    });

    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "تقرير التدقيق");

    // Auto-size columns (rough approximation)
    const wscols = [
      { wch: 15 }, { wch: 30 }, { wch: 15 }, { wch: 20 }, { wch: 15 }, { wch: 20 }, { wch: 80 }
    ];
    worksheet['!cols'] = wscols;

    XLSX.writeFile(workbook, `Basmati_Pro_Audit_${new Date().toISOString().slice(0, 10)}.xlsx`);
  };

  return (
    <div className="flex h-screen bg-[#ffffff] text-[#1e293b] rtl overflow-hidden">

      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 right-0 z-50 w-64 bg-slate-50 border-l border-slate-100 flex flex-col transition-all duration-300 transform ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'}`}>
        <div className="p-8">
           <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg">
                 <ShieldCheck size={24} />
              </div>
              <h1 className="text-xl font-black tracking-tight">بصمتي <span className="text-blue-600">برو</span></h1>
           </div>
        </div>

        <nav className="flex-1 px-4 space-y-1 mt-2">
          <NavItem icon={<LayoutDashboard size={18}/>} label="الرئيسية" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <NavItem icon={<Users size={18}/>} label="سجل الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
          <NavItem icon={<BrainCircuit size={18}/>} label="التدقيق الجماعي" active={currentView === 'ai'} onClick={() => { setCurrentView('ai'); setIsSidebarOpen(false); }} />
        </nav>

        <div className="p-6 space-y-3">
           <label className="flex items-center justify-center gap-2 w-full py-4 bg-blue-600 text-white rounded-2xl cursor-pointer hover:bg-blue-700 transition-all font-black text-xs shadow-lg">
              <FileUp size={16} />
              <span>رفع ملف جديد</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
           </label>

           {employees.length > 0 && (
             <button 
              onClick={exportAuditToExcel}
              className="flex items-center justify-center gap-2 w-full py-4 bg-emerald-600 text-white rounded-2xl cursor-pointer hover:bg-emerald-700 transition-all font-black text-xs shadow-lg"
             >
                <Download size={16} />
                <span>تصدير تقرير XLSX</span>
             </button>
           )}
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        {/* Superior Header */}
        <header className="h-20 px-6 lg:px-10 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4 flex-1">
             <button className="lg:hidden p-2 bg-slate-100 rounded-xl" onClick={() => setIsSidebarOpen(true)}>
               <Menu size={20} />
             </button>
             <div className="relative max-w-lg w-full">
                <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  type="text" 
                  placeholder="بحث سريع..." 
                  className="w-full bg-slate-50 border-none rounded-2xl pr-12 pl-4 py-3 text-xs font-black focus:outline-none focus:ring-2 focus:ring-blue-500/10 transition-all"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
             </div>
          </div>

          <div className="flex items-center gap-4">
             <button 
                onClick={handleAiAudit}
                disabled={employees.length === 0 || isAnalyzing}
                className="hidden sm:flex items-center gap-2 px-6 py-3 bg-slate-900 text-white rounded-2xl text-[10px] font-black hover:bg-blue-600 transition-all disabled:opacity-30"
             >
               <Sparkles size={14} />
               تحليل نواقص الدفعة
             </button>
             <div className="w-10 h-10 bg-slate-50 rounded-xl flex items-center justify-center text-slate-400">
               <Bell size={20} />
             </div>
          </div>
        </header>

        {/* Bento Space */}
        <div className="flex-1 overflow-y-auto px-6 lg:px-10 pb-10 bento-scroll">

          {currentView === 'dashboard' && (
            <div className="max-w-screen-2xl mx-auto h-full flex flex-col gap-6 animate-bento">
              {stats ? (
                <>
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4 shrink-0">
                    <BentoStat title="إجمالي الموظفين" value={stats.totalEmployees} icon={<Users size={20}/>} color="bg-[#E0F2FE]" />
                    <BentoStat title="نسبة الانضباط" value={`${stats.completionRate}%`} icon={<UserCheck size={20}/>} color="bg-[#DCFCE7]" />
                    <BentoStat title="بصمات مسجلة" value={stats.totalPunches} icon={<Fingerprint size={20}/>} color="bg-[#F3E8FF]" />
                    <BentoStat title="سجلات ناقصة" value={stats.deficientEmployees} icon={<AlertCircle size={20}/>} color="bg-[#FCE7F3]" />
                  </div>

                  <div className="flex-1 min-h-0 grid grid-cols-1 lg:grid-cols-12 gap-6">
                    <div className="lg:col-span-9 flex flex-col gap-4 overflow-hidden">
                       <div className="flex items-center justify-between px-2 mb-2">
                          <h2 className="text-xl font-black text-slate-900">مراقبة السجلات الرقمية</h2>
                          <button onClick={exportAuditToExcel} className="text-[10px] font-black text-blue-600 flex items-center gap-1 hover:underline">
                             <Download size={14} /> تصدير النتائج
                          </button>
                       </div>
                       <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-4 overflow-y-auto bento-scroll pr-2 pb-6">
                          {filteredEmployees.slice(0, 24).map((emp) => (
                            <BentoEmployeeCard 
                              key={emp.id} 
                              employee={emp} 
                            />
                          ))}
                       </div>
                    </div>

                    <div className="lg:col-span-3 flex flex-col gap-6">
                       <div className="bento-card bg-slate-900 text-white flex-1 p-8 flex flex-col justify-between border-none">
                          <div>
                             <h3 className="text-xl font-black mb-4 flex items-center gap-3">
                                <BrainCircuit className="text-blue-400" size={28} />
                                التدقيق الجماعي
                             </h3>
                             <p className="text-[11px] font-bold text-slate-400 leading-relaxed italic">
                                نظام Gemini Flash يقوم بمسح شامل لجميع الموظفين المرفوعين لاكتشاف النواقص التقنية فورياً.
                             </p>
                          </div>
                          <button onClick={handleAiAudit} className="w-full py-4 bg-blue-600 rounded-2xl font-black text-xs hover:bg-blue-500 transition-all flex items-center justify-center gap-2">
                             ابدأ التدقيق الجماعي <Sparkles size={14} />
                          </button>
                       </div>
                    </div>
                  </div>
                </>
              ) : <BentoEmptyState handleFileUpload={handleFileUpload} />}
            </div>
          )}

          {currentView === 'employees' && (
            <div className="max-w-screen-2xl mx-auto animate-bento">
              <div className="flex items-center justify-between mb-8 px-2">
                 <h2 className="text-3xl font-black text-slate-900">جميع السجلات</h2>
                 <button onClick={exportAuditToExcel} className="flex items-center gap-2 px-6 py-3 bg-emerald-600 text-white rounded-2xl text-[10px] font-black shadow-lg">
                    <Download size={16} /> تصدير Excel
                 </button>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5 gap-4">
                {filteredEmployees.map((emp) => (
                  <BentoEmployeeCard 
                    key={emp.id} 
                    employee={emp} 
                  />
                ))}
              </div>
            </div>
          )}

          {currentView === 'ai' && (
            <div className="max-w-3xl mx-auto h-full flex flex-col py-6 animate-bento">
               <div className="bento-card bg-white border border-slate-100 flex-1 flex flex-col p-10 relative shadow-xl rounded-[3rem]">
                  <div className="flex items-center gap-4 mb-8">
                    <div className="w-12 h-12 bg-slate-900 text-blue-400 rounded-2xl flex items-center justify-center shadow-lg">
                       <BrainCircuit size={24} />
                    </div>
                    <h2 className="text-xl font-black text-slate-900">تقرير النواقص التقنية الجماعي</h2>
                  </div>
                  <div className="flex-1 bg-slate-50 p-8 rounded-[2rem] overflow-y-auto bento-scroll border border-slate-100 text-slate-800 text-sm font-bold leading-relaxed shadow-inner">
                    {isAnalyzing ? (
                      <div className="h-full flex flex-col items-center justify-center gap-4 opacity-40">
                         <RefreshCcw className="animate-spin text-blue-600" size={32} />
                         <span className="text-[10px] font-black uppercase">جاري تحليل البيانات...</span>
                      </div>
                    ) : (
                      <div className="whitespace-pre-line">{bulkReport || "ارفع الملف واضغط على زر التدقيق الشامل للبدء."}</div>
                    )}
                  </div>
               </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

/* --- Refined Bento Components --- */

const NavItem = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-3 px-5 py-4 rounded-2xl text-[11px] font-black transition-all ${active ? 'nav-active' : 'text-slate-500 hover:bg-white'}`}>
    {icon}
    <span>{label}</span>
  </button>
);

const BentoStat = ({ title, value, icon, color }: any) => (
  <div className={`bento-card ${color} border-none p-6 flex flex-col justify-center`}>
     <div className="flex items-center justify-between mb-2">
        <div className="p-2 bg-white/40 rounded-xl text-slate-800">{icon}</div>
        <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest">{title}</span>
     </div>
     <h4 className="text-2xl font-black text-slate-900 leading-none">{value}</h4>
  </div>
);

const BentoEmployeeCard = ({ employee }: { employee: EmployeeSummary }) => {
  const [showModal, setShowModal] = useState(false);
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const isComplete = employee.isEligible;

  const handleAiAudit = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoadingAi(true);
    const report = await generateDetailedAuditSummaryAI(employee);
    setAiReport(report);
    setLoadingAi(false);
  };

  return (
    <>
      <div 
        onClick={() => setShowModal(true)} 
        className={`bento-card ${isComplete ? 'bg-[#DCFCE7]' : 'bg-[#FCE7F3]'} border-none group cursor-pointer p-6 flex flex-col gap-4 h-auto min-h-[180px] hover:shadow-lg shadow-sm active:scale-95 transition-transform`}
      >
        <div className="flex items-center justify-between gap-2 overflow-hidden">
           <div className="flex items-center gap-3 min-w-0">
              <div className="w-10 h-10 shrink-0 bg-white rounded-xl flex items-center justify-center font-black text-slate-900 text-lg group-hover:bg-slate-900 group-hover:text-white transition-all shadow-sm">
                {employee.name.charAt(0)}
              </div>
              <div className="min-w-0">
                 <h3 className="text-[12px] font-black text-slate-900 truncate leading-tight mb-1">{employee.name}</h3>
                 <span className="text-[9px] font-black text-slate-500 opacity-60">#{employee.id}</span>
              </div>
           </div>
           <div className={`shrink-0 px-3 py-1 rounded-lg text-[9px] font-black uppercase ${isComplete ? 'bg-emerald-200 text-emerald-800' : 'bg-rose-200 text-rose-800'}`}>
              {isComplete ? 'مكتمل' : 'ناقص'}
           </div>
        </div>

        <div className="flex items-end justify-between mt-auto border-t border-black/5 pt-4">
           <div className="flex flex-col">
              <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest mb-1">إجمالي البصمات</span>
              <div className="flex items-center gap-2">
                 <div className="w-7 h-7 bg-white rounded-lg flex items-center justify-center text-blue-600 shadow-sm">
                    <Fingerprint size={14} />
                 </div>
                 <span className="text-lg font-black text-slate-900 leading-none">{employee.totalPunches}</span>
              </div>
           </div>
           <button 
             onClick={handleAiAudit}
             disabled={loadingAi}
             title="التدقيق الرقمي"
             className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-slate-800 hover:bg-slate-900 hover:text-white transition-all shadow-sm"
           >
              {loadingAi ? <RefreshCcw size={16} className="animate-spin" /> : <BrainCircuit size={16} />}
           </button>
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 lg:p-12 bg-slate-900/60 backdrop-blur-xl overflow-hidden">
           <div className="bg-white w-full max-w-6xl h-full max-h-[92vh] rounded-[3rem] overflow-hidden flex flex-col shadow-2xl animate-bento border border-white/20">

              {/* Modal Header */}
              <div className="p-8 lg:p-10 border-b border-slate-100 flex items-center justify-between shrink-0 bg-slate-50/50">
                 <div className="flex items-center gap-6">
                    <div className="w-16 h-16 lg:w-20 lg:h-20 bg-slate-900 text-white rounded-[1.8rem] flex items-center justify-center font-black text-2xl lg:text-3xl shadow-xl">
                       {employee.name.charAt(0)}
                    </div>
                    <div>
                       <h2 className="text-xl lg:text-3xl font-black text-slate-900 leading-none mb-3">{employee.name}</h2>
                       <div className="flex flex-wrap items-center gap-4 text-[10px] lg:text-xs font-black text-slate-400">
                          <p className="flex items-center gap-2 py-1 px-3 bg-white rounded-lg border border-slate-100 shadow-sm"><Target size={14} className="text-blue-600" /> الرقم الوظيفي: #{employee.id}</p>
                          <p className={`flex items-center gap-2 py-1 px-3 rounded-lg border shadow-sm ${isComplete ? 'bg-emerald-50 border-emerald-100 text-emerald-600' : 'bg-rose-50 border-rose-100 text-rose-600'}`}>
                             {isComplete ? <ClipboardCheck size={14} /> : <FileWarning size={14} />}
                             حالة السجل: {isComplete ? 'مكتمل' : 'ناقص'}
                          </p>
                       </div>
                    </div>
                 </div>
                 <button onClick={() => setShowModal(false)} className="w-14 h-14 bg-white border border-slate-100 text-slate-400 rounded-2xl hover:bg-rose-50 hover:text-rose-500 transition-all flex items-center justify-center shadow-sm">
                    <X size={24} />
                 </button>
              </div>

              {/* Two Column Layout */}
              <div className="flex-1 overflow-hidden flex flex-col lg:flex-row bg-white">

                 {/* Left Column: Stats & AI (Sticky/Sidebar) */}
                 <div className="w-full lg:w-1/3 p-8 lg:p-10 bg-slate-50/30 border-l border-slate-100 overflow-y-auto bento-scroll flex flex-col gap-6">
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-1 gap-4">
                       <BentoDetailBox title="معدل الانضباط الرقمي" value={`%${employee.performanceScore}`} label="درجة الدقة" color="bg-[#F3E8FF]" />
                       <BentoDetailBox title="إجمالي البصمات" value={employee.totalPunches} label="مسجلة فعلياً" color="bg-[#E0F2FE]" />
                    </div>

                    {/* AI Audit Section within the modal sidebar */}
                    <div className="bg-white rounded-[2rem] border border-slate-100 p-8 flex flex-col gap-6 shadow-sm">
                       <div className="flex items-center justify-between">
                          <h3 className="text-sm font-black text-slate-900 flex items-center gap-2">
                             <BrainCircuit size={18} className="text-blue-600" />
                             التدقيق الرقمي الذكي
                          </h3>
                          <button 
                            onClick={handleAiAudit}
                            disabled={loadingAi}
                            className="p-2 bg-slate-900 text-white rounded-xl hover:bg-blue-600 transition-colors disabled:opacity-30"
                          >
                             {loadingAi ? <RefreshCcw size={16} className="animate-spin" /> : <Sparkles size={16} />}
                          </button>
                       </div>

                       <div className="flex-1 min-h-[120px] bg-slate-50/50 rounded-2xl p-5 text-[11px] font-bold leading-relaxed text-slate-600 border border-slate-50 italic">
                          {loadingAi ? (
                             <div className="flex flex-col items-center justify-center gap-3 h-full opacity-40">
                                <RefreshCcw className="animate-spin" size={24} />
                                <span>جاري فحص النواقص...</span>
                             </div>
                          ) : (
                             aiReport || "اضغط على زر الدماغ لإجراء فحص تقني شامل للسجل الرقمي للموظف."
                          )}
                       </div>
                    </div>
                 </div>

                 {/* Right Column: Shift Details (Scrollable Content) */}
                 <div className="flex-1 p-8 lg:p-12 overflow-y-auto bento-scroll">
                    <h3 className="text-lg font-black text-slate-900 mb-8 flex items-center gap-3">
                       <div className="w-1.5 h-6 bg-blue-600 rounded-full"></div>
                       تفاصيل الحركات اليومية
                    </h3>
                    <div className="space-y-6 pb-12">
                       {employee.shifts.map((shift, i) => (
                          <div key={i} className={`p-8 rounded-[2.5rem] border ${shift.status === 'مكتملة' ? 'border-emerald-100 bg-emerald-50/10' : 'border-rose-100 bg-rose-50/10'} hover:shadow-xl transition-all`}>
                             <div className="flex justify-between items-center mb-8 border-b border-slate-100 pb-5">
                                <div className="flex items-center gap-4">
                                   <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-white ${shift.status === 'مكتملة' ? 'bg-emerald-500 shadow-lg shadow-emerald-200' : 'bg-rose-500 shadow-lg shadow-rose-200'}`}>
                                      <Clock size={20} />
                                   </div>
                                   <div>
                                      <span className="font-black text-base text-slate-900 block leading-none mb-1">{shift.shift_date}</span>
                                      <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">تاريخ الوردية</span>
                                   </div>
                                </div>
                                <div className={`px-5 py-2 rounded-xl text-[10px] font-black uppercase ${shift.status === 'مكتملة' ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>
                                   الحالة: {shift.status}
                                </div>
                             </div>

                             <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-5 gap-4">
                                {["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"].map(period => {
                                  const punch = shift.punches_details.find(p => p.period === period && !p.is_duplicate);
                                  return (
                                    <div key={period} className={`p-5 rounded-3xl border flex flex-col gap-3 transition-all ${punch ? 'border-blue-100 bg-blue-50/40 shadow-sm' : 'border-slate-100 bg-white opacity-40'}`}>
                                       <div className="flex items-center justify-between">
                                          <div className={`p-2 rounded-xl ${punch ? 'bg-blue-600 text-white' : 'bg-slate-200 text-slate-400'}`}>
                                             {getPeriodIcon(period)}
                                          </div>
                                          {punch && <Check size={14} className="text-emerald-500" />}
                                       </div>
                                       <div className="min-w-0">
                                          <p className="text-[9px] font-black text-slate-400 uppercase truncate mb-1">{period}</p>
                                          <p className={`text-xs font-black ${punch ? 'text-slate-900' : 'text-slate-300 italic'}`}>
                                            {punch ? punch.time : 'مفقود'}
                                          </p>
                                       </div>
                                    </div>
                                  );
                                })}
                             </div>
                          </div>
                       ))}
                    </div>
                 </div>
              </div>
           </div>
        </div>
      )}
    </>
  );
};

