import { ATTENDANCE_RULES } from '../constants';
import { ShiftReport, PunchDetail, EmployeeSummary } from '../types';

const getTimeInMinutes = (date: Date) => date.getHours() * 60 + date.getMinutes();

const getRuleMinutes = (timeStr: string) => {
  const [h, m] = timeStr.split(':').map(Number);
  return h * 60 + m;
};

export const classifyPunch = (
  punchDate: Date,
  isFirst: boolean,
  isLast: boolean,
  shiftStartDate: Date
): string | null => {
  const t = getTimeInMinutes(punchDate);
  const periods = ATTENDANCE_RULES.TIME_PERIODS;
  const isNextDay = punchDate.getDate() !== shiftStartDate.getDate();

  const exitStart = getRuleMinutes(periods["بصمة خروج"].start);
  const exitEnd = getRuleMinutes(periods["بصمة خروج"].end);
  if (isLast && (isNextDay || t >= exitStart) && t <= exitEnd) {
    return "بصمة خروج";
  }

  const mornStart = getRuleMinutes(periods["دخول صباحي"].start);
  const mornEnd = getRuleMinutes(periods["دخول صباحي"].end);
  if (isFirst && !isNextDay && t >= mornStart && t <= mornEnd) {
    return "دخول صباحي";
  }

  const nightStart = getRuleMinutes(periods["بصمة ليلية"].start);
  const nightEnd = getRuleMinutes(periods["بصمة ليلية"].end);
  if (t >= nightStart || t <= nightEnd) {
    if (t > mornEnd || t < 240) {
      return "بصمة ليلية";
    }
  }

  const midStart = getRuleMinutes(periods["بصمة وسطية"].start);
  const midEnd = getRuleMinutes(periods["بصمة وسطية"].end);
  if (t >= midStart && t <= midEnd) return "بصمة وسطية";

  const eveStart = getRuleMinutes(periods["بصمة مسائية"].start);
  const eveEnd = getRuleMinutes(periods["بصمة مسائية"].end);
  if (t >= eveStart && t <= eveEnd) return "بصمة مسائية";

  return null;
};

const getVal = (row: any, keys: string[]) => {
  const rowKeys = Object.keys(row);
  for (const k of keys) {
    const foundKey = rowKeys.find(rk => 
      rk.toLowerCase().includes(k.toLowerCase()) || 
      k.toLowerCase().includes(rk.toLowerCase())
    );
    if (foundKey) return row[foundKey];
  }
  return null;
};

export const processExcelData = (rawData: any[]): EmployeeSummary[] => {
  if (!rawData || rawData.length === 0) return [];

  // التجميع حسب الاسم لضمان بطاقة واحدة لكل موظف
  const employeesMap: Map<string, { id: string, punches: Date[] }> = new Map();

  rawData.forEach(row => {
    const nameVal = getVal(row, ['Name', 'الاسم', 'اسم']);
    if (!nameVal) return;
    const name = String(nameVal).trim();

    const idVal = getVal(row, ['AC-No', 'No', 'رقم', 'معرف', 'ID']);
    const id = idVal ? String(idVal).trim() : "0";

    const dateVal = getVal(row, ['Date', 'التاريخ', 'تاريخ']);
    const timePart = String(getVal(row, ['Time', 'الوقت', 'وقت']) || "");

    if (!timePart || !timePart.trim()) return;

    let dt: Date;
    if (typeof dateVal === 'number') {
      dt = new Date((dateVal - 25569) * 86400 * 1000);
    } else {
      dt = new Date(dateVal);
    }

    if (isNaN(dt.getTime())) return;

    const times = timePart.split(/[\s,]+/).filter(t => t.includes(':'));

    if (!employeesMap.has(name)) {
      employeesMap.set(name, { id, punches: [] });
    }

    const empData = employeesMap.get(name)!;
    times.forEach(tStr => {
      const d = new Date(dt);
      const parts = tStr.split(':').map(Number);
      if (parts.length >= 2) {
        d.setHours(parts[0] || 0, parts[1] || 0, 0, 0);
        empData.punches.push(d);
      }
    });
  });

  const allSummaries: EmployeeSummary[] = [];

  employeesMap.forEach((data, name) => {
    const sortedPunches = data.punches.sort((a, b) => a.getTime() - b.getTime());
    const shiftsData: Date[][] = [];

    if (sortedPunches.length > 0) {
      let currentShift: Date[] = [sortedPunches[0]];
      for (let i = 1; i < sortedPunches.length; i++) {
        // إذا كان الفرق أكثر من 16 ساعة نعتبرها نوبة جديدة (أو يوم جديد)
        const diffHours = (sortedPunches[i].getTime() - sortedPunches[i-1].getTime()) / (1000 * 3600);
        if (diffHours > 16) {
          shiftsData.push(currentShift);
          currentShift = [];
        }
        currentShift.push(sortedPunches[i]);
      }
      if (currentShift.length > 0) shiftsData.push(currentShift);
    }

    const shiftsReports: ShiftReport[] = shiftsData.map(punchDates => {
      const shiftStart = punchDates[0];
      const startDateStr = shiftStart.toLocaleDateString('en-CA');
      const details: PunchDetail[] = [];
      const processedPeriods = new Set<string>();

      punchDates.forEach((p, idx) => {
        const isFirst = idx === 0;
        const isLast = idx === punchDates.length - 1;
        const periodType = classifyPunch(p, isFirst, isLast, shiftStart) || "غير مصنفة";

        let isDuplicate = processedPeriods.has(periodType) && periodType !== "غير مصنفة";
        if (periodType === "بصمة خروج") isDuplicate = false;

        details.push({
          time: p.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' }),
          period: periodType,
          is_duplicate: isDuplicate,
          raw_datetime: p
        });

        if (!isDuplicate && periodType !== "غير مصنفة") {
          processedPeriods.add(periodType);
        }
      });

      const uniqueValidPeriods = new Set(details.filter(d => !d.is_duplicate && d.period !== "غير مصنفة").map(d => d.period));

      return {
        employee_id: data.id,
        employee_name: name,
        shift_date: startDateStr,
        punches_details: details,
        punches_count: uniqueValidPeriods.size,
        status: uniqueValidPeriods.size >= ATTENDANCE_RULES.REQUIRED_PUNCHES_PER_SHIFT ? 'مكتملة' : 'ناقصة'
      };
    });

    const activeShifts = shiftsReports.filter(s => s.punches_count > 0);
    if (activeShifts.length === 0) return;

    const totalValidUniquePunches = activeShifts.reduce((sum, s) => sum + s.punches_count, 0);
    const completedShiftsCount = activeShifts.filter(s => s.status === 'مكتملة').length;
    const performanceScore = Math.round((totalValidUniquePunches / (activeShifts.length * 5)) * 100);

    allSummaries.push({
      id: data.id,
      name,
      shifts: activeShifts,
      totalPunches: totalValidUniquePunches,
      completionRate: Math.round((completedShiftsCount / activeShifts.length) * 100),
      performanceScore,
      isEligible: completedShiftsCount === activeShifts.length
    });
  });

  return allSummaries.sort((a, b) => a.name.localeCompare(b.name, 'ar'));
};

import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, Check,
  Fingerprint, RefreshCcw, Bell, 
  X, Activity, TrendingUp,
  AlertCircle, Briefcase, ChevronLeft,
  Sunrise, Sun, Sunset, Moon, LogOut as LogOutIcon,
  ShieldCheck, MoreHorizontal, UserCheck, Clock,
  Target, Zap, ArrowUpRight, Info,
  ClipboardCheck, FileWarning, Download
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'ai';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
      deficientEmployees: employees.filter(e => !e.isEligible).length
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
        const json = XLSX.utils.sheet_to_json(firstSheet);

        if (json.length === 0) {
          alert("الملف المرفوع فارغ.");
          setIsAnalyzing(false);
          return;
        }

        const processed = processExcelData(json);
        setEmployees(processed);
        setBulkReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
        event.target.value = '';
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleAiAudit = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    setCurrentView('ai');
    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result);
    } catch (e) { console.error(e); } finally { setIsAnalyzing(false); }
  };

  const exportAuditToExcel = () => {
    if (employees.length === 0) return;
    const exportData = employees.map(emp => {
      const missingDaysDetails = emp.shifts
        .filter(s => s.status === 'ناقصة')
        .map(s => {
          const missingPeriods = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
            .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate));
          return `${s.shift_date}: (${missingPeriods.join(' - ')})`;
        }).join(' | ');
      return {
        "الاسم": emp.name,
        "الرقم الوظيفي": emp.id,
        "الحالة العامة": emp.isEligible ? "مكتمل" : "ناقص",
        "عدد البصمات": emp.totalPunches,
        "التفاصيل": missingDaysDetails || "كامل"
      };
    });
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "تدقيق");
    XLSX.writeFile(workbook, `Audit_${new Date().toLocaleDateString()}.xlsx`);
  };

  return (
    <div className="flex h-screen bg-[#ffffff] text-[#1e293b] rtl overflow-hidden">
      <aside className={`fixed lg:static inset-y-0 right-0 z-50 w-64 bg-slate-50 border-l border-slate-100 flex flex-col transition-all duration-300 transform ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'}`}>
        <div className="p-8">
           <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg">
                 <ShieldCheck size={24} />
              </div>
              <h1 className="text-xl font-black tracking-tight">بصمتي <span className="text-blue-600">برو</span></h1>
           </div>
        </div>
        <nav className="flex-1 px-4 space-y-1 mt-2">
          <NavItem icon={<LayoutDashboard size={18}/>} label="الرئيسية" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <NavItem icon={<Users size={18}/>} label="سجل الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
          <NavItem icon={<BrainCircuit size={18}/>} label="التدقيق الجماعي" active={currentView === 'ai'} onClick={() => { setCurrentView('ai'); setIsSidebarOpen(false); }} />
        </nav>
        <div className="p-6 space-y-3">
           <label className="flex items-center justify-center gap-2 w-full py-4 bg-blue-600 text-white rounded-2xl cursor-pointer hover:bg-blue-700 transition-all font-black text-xs shadow-lg">
              <FileUp size={16} />
              <span>رفع ملف جديد</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
           </label>
           {employees.length > 0 && (
             <button onClick={exportAuditToExcel} className="flex items-center justify-center gap-2 w-full py-4 bg-emerald-600 text-white rounded-2xl font-black text-xs shadow-lg">
                <Download size={16} /> تصدير XLSX
             </button>
           )}
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        <header className="h-20 px-6 lg:px-10 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4 flex-1">
             <button className="lg:hidden p-2 bg-slate-100 rounded-xl" onClick={() => setIsSidebarOpen(true)}>
               <Menu size={20} />
             </button>
             <div className="relative max-w-lg w-full">
                <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  type="text" 
                  placeholder="بحث سريع باسم الموظف..." 
                  className="w-full bg-slate-50 border-none rounded-2xl pr-12 pl-4 py-3 text-xs font-black focus:outline-none focus:ring-2 focus:ring-blue-500/10"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
             </div>
          </div>
          <div className="flex items-center gap-4">
             <button onClick={handleAiAudit} disabled={employees.length === 0 || isAnalyzing} className="hidden sm:flex items-center gap-2 px-6 py-3 bg-slate-900 text-white rounded-2xl text-[10px] font-black hover:bg-blue-600 transition-all">
               <Sparkles size={14} /> تحليل النواقص
             </button>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto px-6 lg:px-10 pb-10 bento-scroll">
          {currentView === 'dashboard' && (
            <div className="max-w-screen-2xl mx-auto h-full flex flex-col gap-6 animate-bento">
              {stats ? (
                <>
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4 shrink-0">
                    <BentoStat title="إجمالي الموظفين" value={stats.totalEmployees} icon={<Users size={20}/>} color="bg-[#E0F2FE]" />
                    <BentoStat title="نسبة الانضباط" value={`${stats.completionRate}%`} icon={<UserCheck size={20}/>} color="bg-[#DCFCE7]" />
                    <BentoStat title="بصمات مسجلة" value={stats.totalPunches} icon={<Fingerprint size={20}/>} color="bg-[#F3E8FF]" />
                    <BentoStat title="سجلات ناقصة" value={stats.deficientEmployees} icon={<AlertCircle size={20}/>} color="bg-[#FCE7F3]" />
                  </div>
                  <div className="flex-1 min-h-0 grid grid-cols-1 lg:grid-cols-12 gap-6">
                    <div className="lg:col-span-12 flex flex-col gap-4 overflow-hidden">
                       <h2 className="text-xl font-black text-slate-900 px-2">بطاقات الموظفين الذكية</h2>
                       <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 overflow-y-auto bento-scroll pr-2 pb-6">
                          {filteredEmployees.map((emp, idx) => (
                            <BentoEmployeeCard key={emp.name} employee={emp} index={idx} />
                          ))}
                       </div>
                    </div>
                  </div>
                </>
              ) : <BentoEmptyState handleFileUpload={handleFileUpload} isAnalyzing={isAnalyzing} />}
            </div>
          )}
          {/* views employees and ai follow same pattern */}
          {currentView === 'employees' && (
             <div className="max-w-screen-2xl mx-auto animate-bento">
                <h2 className="text-3xl font-black text-slate-900 mb-8 px-2">سجل الموظفين الكامل</h2>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                   {filteredEmployees.map((emp, idx) => (
                      <BentoEmployeeCard key={emp.name} employee={emp} index={idx} />
                   ))}
                </div>
             </div>
          )}
          {currentView === 'ai' && (
             <div className="max-w-3xl mx-auto h-full flex flex-col py-6 animate-bento">
                <div className="bento-card bg-white border border-slate-100 p-10 shadow-xl rounded-[3rem]">
                   <h2 className="text-xl font-black mb-6">تقرير التدقيق الشامل</h2>
                   <div className="bg-slate-50 p-6 rounded-2xl whitespace-pre-line text-sm font-bold leading-relaxed">
                      {isAnalyzing ? "جاري التحليل..." : bulkReport || "لا يوجد تقرير حالياً."}
                   </div>
                </div>
             </div>
          )}
        </div>
      </main>
    </div>
  );
};

