import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary } from "../types";

/**
 * المدقق الذكي الفردي (زر الدماغ على البطاقة)
 */
export const generateDetailedAuditSummaryAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const faultyData = employee.shifts
    .filter(s => s.status === 'ناقصة')
    .map(s => ({
      date: s.shift_date,
      missing: ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
        .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate))
    }));

  if (faultyData.length === 0) return "✅ السجل التقني مكتمل: لا توجد أي بصمات مفقودة لهذا الموظف.";

  const prompt = `
    أنت مدقق أنظمة حضور وانصراف (System Auditor). 
    حلل سجل الموظف: ${employee.name} (ACNo: ${employee.id}).
    البيانات المكتشفة كـ "ناقصة": ${JSON.stringify(faultyData)}

    المطلوب:
    تقرير فني مباشر يوضح:
    - تاريخ اليوم.
    - نوع البصمة المفقودة بدقة.
    - تقييم حالة الانضباط التقني.
    اجعل الرد باللغة العربية، بصيغة تقرير فني، بدون مقدمات إنشائية.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.1 }
    });
    return response.text?.trim() || "تعذر استخراج تقرير التدقيق.";
  } catch (error) {
    return "⚠️ خطأ في معالجة التدقيق الذكي.";
  }
};

/**
 * المدقق الذكي الجماعي (الزر الرئيسي في الهيدر)
 */
export const generateBulkAuditSummaryAI = async (employees: EmployeeSummary[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // نرسل فقط الموظفين الذين لديهم مشاكل تقنية للتحليل
  const problematicEmployees = employees
    .filter(e => !e.isEligible)
    .slice(0, 30) // نكتفي بأول 30 لتجنب تجاوز حدود التوكينز
    .map(e => ({
      name: e.name,
      id: e.id,
      faultyShifts: e.shifts.filter(s => s.status === 'ناقصة').map(s => ({
        date: s.shift_date,
        missing: ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
          .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate))
      }))
    }));

  if (problematicEmployees.length === 0) return "✅ تقرير التدقيق الجماعي: كافة البصمات في هذا الملف مكتملة ولا توجد أي مخالفات تقنية.";

  const prompt = `
    بصفتك "المدقق الفني الذكي"، قم بإعداد تقرير تدقيق شامل (Bulk Audit Report) للدفعة الحالية.
    البيانات التي تم رصد نواقص فيها: ${JSON.stringify(problematicEmployees)}

    هيكل التقرير المطلوب (بالعربية):
    1. ملخص إحصائي سريع للنواقص المرصودة.
    2. قائمة تفصيلية بالموظفين (الاسم والرقم الوظيفي) مع توضيح اليوم والبصمة المفقودة لكل واحد.
    3. استنتاج تقني حول أكثر أنواع البصمات تكراراً في السقوط (مثلاً: بصمة الخروج هي الأكثر فقداً).

    قواعد:
    - لا تستخدم لغة "اقتراحات"، استخدم لغة "تدقيق فني ورصد أخطاء".
    - كن مباشراً واحترافياً جداً.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.1 }
    });
    return response.text?.trim() || "لا توجد بيانات كافية للتدقيق الجماعي.";
  } catch (error) {
    return "⚠️ حدث خطأ أثناء تشغيل المدقق الجماعي.";
  }
};

import React, { useState, useMemo } from 'react';
