                      ) : bulkReport || "يرجى تشغيل المدقق من الزر العلوي."}
                   </div>
                   <div className="mt-8 flex justify-end">
                      <button onClick={exportAuditToExcel} className="px-8 py-3 bg-blue-600 text-white rounded-xl font-black text-xs hover:bg-blue-700 transition-all flex items-center gap-2">
