import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary } from "../types";

/**
 * المدقق الذكي الفردي (زر الدماغ)
 * تم تحسين السرعة القصوى وتقليل التوكنز عبر الاختصار الشديد
 */
export const generateDetailedAuditSummaryAI = async (employee: EmployeeSummary): Promise<string> => {
  // إنشاء المثيل مباشرة قبل الاستخدام لضمان أحدث مفتاح
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // تقليص البيانات المرسلة لأصغر حجم ممكن لتوفير التوكنز والوقت
  const data = employee.shifts
    .filter(s => s.status === 'ناقصة')
    .map(s => `${s.shift_date}: ${["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
        .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate))
        .join(',')}`);

  if (data.length === 0) return "✅ السجل مكتمل.";

  const prompt = `مدقق بصمة: لخص النواقص التالية باختصار شديد جداً (التاريخ: البصمات المفقودة):
${data.join('\n')}
(رد بالعربية، نقاط سريعة فقط)`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        temperature: 0, 
        maxOutputTokens: 150, // تقليل سقف المخرجات لتسريع التوليد
        thinkingConfig: { thinkingBudget: 0 } 
      }
    });
    return response.text?.trim() || "لا توجد نواقص فنية.";
  } catch (error) {
    console.error("AI Audit Error:", error);
    return "⚠️ خطأ فني في المدقق.";
  }
};

/**
 * المدقق الذكي الجماعي
 */
export const generateBulkAuditSummaryAI = async (employees: EmployeeSummary[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // نرسل فقط أول 15 موظفاً يعانون من مشاكل لضمان السرعة وعدم تجاوز الحدود
  const problematic = employees
    .filter(e => !e.isEligible)
    .slice(0, 15)
    .map(e => ({
      id: e.id,
      n: e.name,
      m: e.shifts.filter(s => s.status === 'ناقصة').map(s => ({
        d: s.shift_date,
        p: ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
          .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate))
      }))
    }));

  if (problematic.length === 0) return "✅ كافة السجلات في هذه الدفعة سليمة تقنياً.";

  const prompt = `تقرير تدقيق فني سريع (بالعربية):
${JSON.stringify(problematic)}
أذكر فقط الأسماء والتواريخ والبصمات المفقودة بنقاط مباشرة ومختصرة جداً.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        temperature: 0.1,
        maxOutputTokens: 800,
        thinkingConfig: { thinkingBudget: 0 }
      }
    });
    return response.text?.trim() || "تعذر إكمال التدقيق الجماعي.";
  } catch (error) {
    return "⚠️ خطأ أثناء التدقيق الجماعي.";
  }
};

import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, Check,
  Fingerprint, RefreshCcw, Bell, 
  X, Activity, TrendingUp,
  AlertCircle, Briefcase, ChevronLeft,
  Sunrise, Sun, Sunset, Moon, LogOut as LogOutIcon,
  ShieldCheck, MoreHorizontal, UserCheck, Clock,
  Target, Zap, ArrowUpRight, Info,
  ClipboardCheck, FileWarning, Download
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'ai';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
      deficientEmployees: employees.filter(e => !e.isEligible).length
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
        const json = XLSX.utils.sheet_to_json(firstSheet);

        if (json.length === 0) {
          alert("الملف المرفوع فارغ.");
          setIsAnalyzing(false);
          return;
        }

        const processed = processExcelData(json);
        setEmployees(processed);
        setBulkReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
        event.target.value = '';
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleAiAudit = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    setCurrentView('ai');
    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result);
    } catch (e) { console.error(e); } finally { setIsAnalyzing(false); }
  };

  const exportAuditToExcel = () => {
    if (employees.length === 0) return;
    const exportData = employees.map(emp => {
      const missingDaysDetails = emp.shifts
        .filter(s => s.status === 'ناقصة')
        .map(s => {
          const missingPeriods = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
            .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate));
          return `${s.shift_date}: (${missingPeriods.join(' - ')})`;
        }).join(' | ');
      return {
        "الرقم الوظيفي (ACNo)": emp.id,
        "اسم الموظف": emp.name,
        "الحالة العامة": emp.isEligible ? "مكتمل" : "ناقص",
        "إجمالي البصمات": emp.totalPunches,
        "نواقص التدقيق": missingDaysDetails || "لا توجد نواقص"
      };
    });
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "تقرير البصمة");
    XLSX.writeFile(workbook, `Audit_Report_${new Date().toLocaleDateString('en-CA')}.xlsx`);
  };

  return (
    <div className="flex h-screen bg-[#ffffff] text-[#1e293b] rtl overflow-hidden">
      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 right-0 z-50 w-64 bg-slate-50 border-l border-slate-100 flex flex-col transition-all duration-300 transform ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'}`}>
        <div className="p-8">
           <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg">
                 <ShieldCheck size={24} />
              </div>
              <h1 className="text-xl font-black tracking-tight">بصمتي <span className="text-blue-600">برو</span></h1>
           </div>
        </div>
        <nav className="flex-1 px-4 space-y-1 mt-2">
          <NavItem icon={<LayoutDashboard size={18}/>} label="لوحة التحكم" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <NavItem icon={<Users size={18}/>} label="سجل الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
          <NavItem icon={<BrainCircuit size={18}/>} label="المدقق الجماعي" active={currentView === 'ai'} onClick={() => { setCurrentView('ai'); setIsSidebarOpen(false); }} />
        </nav>
        <div className="p-6 space-y-3">
           <label className="flex items-center justify-center gap-2 w-full py-4 bg-blue-600 text-white rounded-2xl cursor-pointer hover:bg-blue-700 transition-all font-black text-xs shadow-lg">
              <FileUp size={16} />
              <span>رفع سجل البصمة</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
           </label>
           {employees.length > 0 && (
             <button onClick={exportAuditToExcel} className="flex items-center justify-center gap-2 w-full py-4 bg-emerald-600 text-white rounded-2xl font-black text-xs shadow-lg">
                <Download size={16} /> تصدير التقرير
             </button>
           )}
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden">
        <header className="h-20 px-6 lg:px-10 flex items-center justify-between shrink-0">
          <div className="flex items-center gap-4 flex-1">
             <button className="lg:hidden p-2 bg-slate-100 rounded-xl" onClick={() => setIsSidebarOpen(true)}>
               <Menu size={20} />
             </button>
             <div className="relative max-w-lg w-full">
                <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  type="text" 
                  placeholder="بحث بالرقم الوظيفي (ACNo) أو الاسم..." 
                  className="w-full bg-slate-50 border-none rounded-2xl pr-12 pl-4 py-3 text-xs font-black focus:outline-none focus:ring-2 focus:ring-blue-500/10"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
             </div>
          </div>
          <div className="flex items-center gap-4">
             <button onClick={handleAiAudit} disabled={employees.length === 0 || isAnalyzing} className="hidden sm:flex items-center gap-2 px-6 py-3 bg-slate-900 text-white rounded-2xl text-[10px] font-black hover:bg-blue-600 transition-all">
               <BrainCircuit size={14} /> تشغيل المدقق الجماعي
             </button>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto px-6 lg:px-10 pb-10 bento-scroll">
          {currentView === 'dashboard' && (
            <div className="max-w-screen-2xl mx-auto h-full flex flex-col gap-6 animate-bento">
              {stats ? (
                <>
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4 shrink-0">
                    <BentoStat title="إجمالي الموظفين" value={stats.totalEmployees} icon={<Users size={20}/>} color="bg-[#E0F2FE]" />
                    <BentoStat title="نسبة الانضباط" value={`${stats.completionRate}%`} icon={<UserCheck size={20}/>} color="bg-[#DCFCE7]" />
                    <BentoStat title="بصمات مسجلة" value={stats.totalPunches} icon={<Fingerprint size={20}/>} color="bg-[#F3E8FF]" />
                    <BentoStat title="سجلات ناقصة" value={stats.deficientEmployees} icon={<AlertCircle size={20}/>} color="bg-[#FCE7F3]" />
                  </div>
                  <div className="flex-1 min-h-0 grid grid-cols-1 lg:grid-cols-12 gap-6">
                    <div className="lg:col-span-12 flex flex-col gap-4 overflow-hidden">
                       <h2 className="text-xl font-black text-slate-900 px-2">نظام البطاقات الذكية (تجميع ACNo)</h2>
                       <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 overflow-y-auto bento-scroll pr-2 pb-6">
                          {filteredEmployees.map((emp, idx) => (
                            <BentoEmployeeCard key={emp.id} employee={emp} index={idx} />
                          ))}
                       </div>
                    </div>
                  </div>
                </>
              ) : <BentoEmptyState handleFileUpload={handleFileUpload} isAnalyzing={isAnalyzing} />}
            </div>
          )}
          {currentView === 'employees' && (
             <div className="max-w-screen-2xl mx-auto animate-bento">
                <h2 className="text-3xl font-black text-slate-900 mb-8 px-2">قاعدة بيانات الموظفين</h2>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                   {filteredEmployees.map((emp, idx) => (
                      <BentoEmployeeCard key={emp.id} employee={emp} index={idx} />
                   ))}
                </div>
             </div>
          )}
          {currentView === 'ai' && (
             <div className="max-w-4xl mx-auto h-full flex flex-col py-6 animate-bento">
                <div className="bento-card bg-white border border-slate-100 p-10 shadow-xl rounded-[3rem]">
                   <div className="flex items-center justify-between mb-8">
                      <div>
                         <h2 className="text-2xl font-black">تقرير التدقيق الفني المباشر (جماعي)</h2>
                         <p className="text-xs font-bold text-slate-400 mt-1">فحص ذكي وفوري لكافة السجلات والبحث عن النواقص</p>
                      </div>
                      <div className="p-4 bg-slate-900 text-white rounded-2xl">
                         <ShieldCheck size={24} />
                      </div>
                   </div>
                   <div className="bg-slate-50 p-8 rounded-[2rem] whitespace-pre-line text-sm font-bold leading-relaxed border border-slate-100 shadow-inner max-h-[60vh] overflow-y-auto bento-scroll">
                      {isAnalyzing ? (
                        <div className="flex flex-col items-center justify-center py-10 gap-4">
                           <RefreshCcw size={32} className="animate-spin text-blue-600" />
                           <p className="animate-pulse">جاري التدقيق الفني الفوري...</p>
                        </div>
                      ) : bulkReport || "يرجى تشغيل المدقق من الزر العلوي."}
                   </div>
                   <div className="mt-8 flex justify-end">
                      <button onClick={exportAuditToExcel} className="px-8 py-3 bg-blue-600 text-white rounded-xl font-black text-xs hover:bg-blue-700 transition-all flex items-center gap-2">
                         <Download size={14} /> تصدير التقرير كـ Excel
                      </button>
                   </div>
                </div>
             </div>
          )}
        </div>
      </main>
    </div>
  );
};

