import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary } from "../types";

/**
 * المدقق الذكي الفردي (زر الدماغ)
 * تم تحسين السرعة القصوى وتقليل التوكنز عبر الاختصار الشديد
 */
export const generateDetailedAuditSummaryAI = async (employee: EmployeeSummary): Promise<{ text: string; tokens: number }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const data = employee.shifts
    .filter(s => s.status === 'ناقصة')
    .map(s => `${s.shift_date}: ${["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
        .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate))
        .join(',')}`);

  if (data.length === 0) return { text: "✅ السجل مكتمل.", tokens: 0 };

  const prompt = `مدقق بصمة: لخص النواقص التالية باختصار شديد جداً (التاريخ: البصمات المفقودة):
${data.join('\n')}
(رد بالعربية، نقاط سريعة فقط)`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        temperature: 0, 
        maxOutputTokens: 150,
        thinkingConfig: { thinkingBudget: 0 } 
      }
    });

    // تقدير تقريبي للتوكنز (1 توكن لكل 4 أحرف تقريباً)
    const estimatedTokens = Math.ceil((prompt.length + (response.text?.length || 0)) / 4);

    return { 
      text: response.text?.trim() || "لا توجد نواقص فنية.",
      tokens: estimatedTokens
    };
  } catch (error) {
    console.error("AI Audit Error:", error);
    throw error;
  }
};

/**
 * المدقق الذكي الجماعي
 */
export const generateBulkAuditSummaryAI = async (employees: EmployeeSummary[]): Promise<{ text: string; tokens: number; count: number }> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // نرسل فقط أول 15 موظفاً يعانون من مشاكل لضمان السرعة وعدم تجاوز الحدود (Token Limit Control)
  const limit = 15;
  const problematic = employees
    .filter(e => !e.isEligible)
    .slice(0, limit)
    .map(e => ({
      id: e.id,
      n: e.name,
      m: e.shifts.filter(s => s.status === 'ناقصة').map(s => ({
        d: s.shift_date,
        p: ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
          .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate))
      }))
    }));

  if (problematic.length === 0) return { text: "✅ كافة السجلات في هذه الدفعة سليمة تقنياً.", tokens: 0, count: 0 };

  const prompt = `تقرير تدقيق فني سريع (بالعربية):
${JSON.stringify(problematic)}
أذكر فقط الأسماء والتواريخ والبصمات المفقودة بنقاط مباشرة ومختصرة جداً.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        temperature: 0.1,
        maxOutputTokens: 800,
        thinkingConfig: { thinkingBudget: 0 }
      }
    });

    const estimatedTokens = Math.ceil((prompt.length + (response.text?.length || 0)) / 4);

    return { 
      text: response.text?.trim() || "تعذر إكمال التدقيق الجماعي.",
      tokens: estimatedTokens,
      count: problematic.length
    };
  } catch (error) {
    throw error;
  }
};

import React, { useState, useMemo, useEffect } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, Check,
  Fingerprint, RefreshCcw, Bell, 
  X, Activity, TrendingUp,
  AlertCircle, Briefcase, ChevronLeft,
  Sunrise, Sun, Sunset, Moon, LogOut as LogOutIcon,
  ShieldCheck, MoreHorizontal, UserCheck, Clock,
  Target, Zap, ArrowUpRight, Info,
  ClipboardCheck, FileWarning, Download, Cpu, ActivitySquare
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'ai';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  // حالات الذكاء الاصطناعي
  const [aiStatus, setAiStatus] = useState<'idle' | 'busy' | 'error' | 'token_limit'>('idle');
  const [sessionTokens, setSessionTokens] = useState(0);

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
      deficientEmployees: employees.filter(e => !e.isEligible).length
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
        const json = XLSX.utils.sheet_to_json(firstSheet);

        if (json.length === 0) {
          alert("الملف المرفوع فارغ.");
          setIsAnalyzing(false);
          return;
        }

        const processed = processExcelData(json);
        setEmployees(processed);
        setBulkReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
        event.target.value = '';
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleAiAudit = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    setAiStatus('busy');
    setCurrentView('ai');
    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result.text);
      setSessionTokens(prev => prev + result.tokens);
      setAiStatus('idle');
    } catch (e: any) { 
      console.error(e); 
      setAiStatus('error');
    } finally { 
      setIsAnalyzing(false); 
    }
  };

  const exportAuditToExcel = () => {
    if (employees.length === 0) return;
    const exportData = employees.map(emp => {
      const missingDaysDetails = emp.shifts
        .filter(s => s.status === 'ناقصة')
        .map(s => {
          const missingPeriods = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
            .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate));
          return `${s.shift_date}: (${missingPeriods.join(' - ')})`;
        }).join(' | ');
      return {
        "الرقم الوظيفي (ACNo)": emp.id,
        "اسم الموظف": emp.name,
        "الحالة العامة": emp.isEligible ? "مكتمل" : "ناقص",
        "إجمالي البصمات": emp.totalPunches,
        "نواقص التدقيق": missingDaysDetails || "لا توجد نواقص"
      };
    });
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "تقرير البصمة");
    XLSX.writeFile(workbook, `Audit_Report_${new Date().toLocaleDateString('en-CA')}.xlsx`);
  };

  return (
    <div className="flex h-screen bg-[#ffffff] text-[#1e293b] rtl overflow-hidden">
      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 right-0 z-50 w-64 bg-slate-50 border-l border-slate-100 flex flex-col transition-all duration-300 transform ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'}`}>
        <div className="p-8">
           <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg">
                 <ShieldCheck size={24} />
              </div>
              <h1 className="text-xl font-black tracking-tight">بصمتي <span className="text-blue-600">برو</span></h1>
           </div>
        </div>

        <nav className="flex-1 px-4 space-y-1 mt-2">
          <NavItem icon={<LayoutDashboard size={18}/>} label="لوحة التحكم" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <NavItem icon={<Users size={18}/>} label="سجل الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
          <NavItem icon={<BrainCircuit size={18}/>} label="المدقق الجماعي" active={currentView === 'ai'} onClick={() => { setCurrentView('ai'); setIsSidebarOpen(false); }} />
        </nav>

        {/* AI Health & Tokens Monitor */}
        <div className="px-6 py-4 mx-4 mb-4 bg-white rounded-3xl border border-slate-100 shadow-sm flex flex-col gap-3">
           <div className="flex items-center justify-between">
              <span className="text-[10px] font-black text-slate-400 uppercase">حالة الموديل (AI)</span>
              <div className="flex items-center gap-1.5">
                 <div className={`w-2 h-2 rounded-full ${aiStatus === 'idle' ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]' : aiStatus === 'busy' ? 'bg-amber-500 animate-pulse' : 'bg-rose-500'}`}></div>
                 <span className="text-[9px] font-black text-slate-600">{aiStatus === 'idle' ? 'جاهز' : aiStatus === 'busy' ? 'جاري التدقيق' : 'خطأ'}</span>
              </div>
           </div>
           <div className="space-y-1.5">
