              </div>
           </div>
           <div className={`px-2 py-1 rounded-lg text-[9px] font-black ${isComplete ? 'bg-emerald-200 text-emerald-800 shadow-sm' : 'bg-rose-200 text-rose-800 shadow-sm'}`}>
              {isComplete ? 'مكتمل' : 'ناقص'}
           </div>
        </div>

        <div className="mt-2 bg-white/40 p-3 rounded-2xl flex flex-col gap-2 shadow-inner">
           <span className="text-[8px] font-black text-slate-500 uppercase">ملخص البصمات (آخر يوم)</span>
           <div className="flex items-center gap-2">
              {["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"].map(p => {
