        </div>

        <div className="flex items-center justify-between mt-auto pt-2 border-t border-black/5">
           <div className="flex items-center gap-2">
              <Fingerprint size={14} className="text-blue-600" />
              <span className="text-sm font-black text-slate-900">{employee.totalPunches} بصمة</span>
           </div>
           <button onClick={handleAiAudit} title="مدقق البصمة الذكي" className="w-8 h-8 bg-white rounded-lg flex items-center justify-center text-slate-800 hover:bg-slate-900 hover:text-white transition-all shadow-sm active:scale-90">
