                    </div>
                    <div>
                       <h2 className="text-2xl font-black text-slate-900 mb-1">{employee.name}</h2>
                       <p className="text-xs font-bold text-slate-400 tracking-wide">ACNo: {employee.id} • إجمالي الأيام: {employee.shifts.length}</p>
                    </div>
                 </div>
