const getMiniIcon = (period: string) => {
  const s = 12;
  switch (period) {
    case 'دخول صباحي': return <Sunrise size={s} />;
    case 'بصمة وسطية': return <Sun size={s} />;
    case 'بصمة مسائية': return <Sunset size={s} />;
    case 'بصمة ليلية': return <Moon size={s} />;
    case 'بصمة خروج': return <LogOutIcon size={s} />;
    default: return <Clock size={s} />;
  }
};

const BentoDetailBox = ({ title, value, label, color }: any) => (
  <div className={`p-6 rounded-[2rem] ${color} text-center flex flex-col justify-center min-h-[120px] shadow-sm`}>
     <p className="text-[9px] font-black text-slate-500 uppercase mb-1">{title}</p>
     <p className="text-3xl font-black text-slate-900 leading-none">{value}</p>
     <p className="text-[9px] font-black text-slate-400 mt-2">{label}</p>
  </div>
);

