export default App;

import React, { useState, useMemo, useEffect } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Fingerprint, RefreshCcw, 
  X, AlertCircle, Sunrise, Sun, Sunset, Moon, 
  LogOut as LogOutIcon, ShieldCheck, UserCheck, Clock,
  Zap, Download, FileWarning, Cpu, Key, Info
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary } from './types';

type ViewType = 'dashboard' | 'employees' | 'ai';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  // AI State Management
  const [aiStatus, setAiStatus] = useState<'idle' | 'busy' | 'error' | 'locked'>('idle');
  const [sessionTokens, setSessionTokens] = useState(0);
  const [hasApiKey, setHasApiKey] = useState<boolean | null>(null);

  // Check for API Key on mount
  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(selected);
        if (!selected) setAiStatus('locked');
      } else {
        // Fallback for non-AI Studio environments if process.env.API_KEY exists
        setHasApiKey(!!process.env.API_KEY);
      }
    };
    checkKey();
  }, []);

  const handleOpenKeySelector = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      setHasApiKey(true);
      setAiStatus('idle');
    }
  };

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
      deficientEmployees: employees.filter(e => !e.isEligible).length
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
        const json = XLSX.utils.sheet_to_json(firstSheet);

        if (json.length === 0) {
          alert("الملف المرفوع فارغ.");
          return;
        }

        const processed = processExcelData(json);
        setEmployees(processed);
        setBulkReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
        event.target.value = '';
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleAiAudit = async () => {
    if (employees.length === 0) return;
    if (!hasApiKey) {
      handleOpenKeySelector();
      return;
    }

    setIsAnalyzing(true);
    setAiStatus('busy');
    setCurrentView('ai');
    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result.text);
      setSessionTokens(prev => prev + result.tokens);
      setAiStatus('idle');
    } catch (e: any) { 
      console.error(e);
      if (e.message?.includes("not found")) {
        setHasApiKey(false);
        setAiStatus('locked');
      } else {
        setAiStatus('error');
      }
    } finally { 
      setIsAnalyzing(false); 
    }
  };

  const exportAuditToExcel = () => {
    if (employees.length === 0) return;
    const exportData = employees.map(emp => {
      const missingDaysDetails = emp.shifts
        .filter(s => s.status === 'ناقصة')
        .map(s => {
          const missingPeriods = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
            .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate));
          return `${s.shift_date}: (${missingPeriods.join(' - ')})`;
        }).join(' | ');
      return {
        "الرقم الوظيفي (ACNo)": emp.id,
        "اسم الموظف": emp.name,
        "الحالة العامة": emp.isEligible ? "مكتمل" : "ناقص",
        "إجمالي البصمات": emp.totalPunches,
        "نواقص التدقيق": missingDaysDetails || "لا توجد نواقص"
      };
    });
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "تقرير البصمة");
    XLSX.writeFile(workbook, `Audit_Report_${new Date().toLocaleDateString('en-CA')}.xlsx`);
  };

  if (hasApiKey === false && currentView === 'ai') {
    return <KeyRequiredScreen onSelect={handleOpenKeySelector} />;
  }

  return (
    <div className="flex h-screen bg-[#ffffff] text-[#1e293b] rtl overflow-hidden">
      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 right-0 z-50 w-72 bg-slate-50 border-l border-slate-100 flex flex-col transition-all duration-300 transform ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'}`}>
        <div className="p-8">
           <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg">
                 <ShieldCheck size={24} />
              </div>
              <h1 className="text-xl font-black tracking-tight">بصمتي <span className="text-blue-600">برو</span></h1>
           </div>
        </div>

        <nav className="flex-1 px-4 space-y-1 mt-2">
          <NavItem icon={<LayoutDashboard size={18}/>} label="لوحة التحكم" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <NavItem icon={<Users size={18}/>} label="سجل الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
          <NavItem icon={<BrainCircuit size={18}/>} label="المدقق الجماعي" active={currentView === 'ai'} onClick={() => { setCurrentView('ai'); setIsSidebarOpen(false); }} />
        </nav>

        {/* AI Performance Monitor */}
        <div className="px-6 py-5 mx-4 mb-4 bg-white rounded-[2rem] border border-slate-100 shadow-sm flex flex-col gap-4">
           <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <div className="w-8 h-8 bg-blue-50 text-blue-600 rounded-lg flex items-center justify-center">
                  <Cpu size={16} />
                </div>
                <span className="text-[10px] font-black text-slate-500 uppercase tracking-tighter">حالة الأنظمة</span>
              </div>
              <div className="flex items-center gap-1.5 px-2 py-1 bg-slate-50 rounded-lg">
                 <div className={`w-2 h-2 rounded-full ${aiStatus === 'idle' ? 'bg-emerald-500 shadow-[0_0_8px_rgba(16,185,129,0.5)]' : aiStatus === 'busy' ? 'bg-amber-500 animate-pulse' : 'bg-rose-500'}`}></div>
                 <span className="text-[9px] font-black text-slate-600">{aiStatus === 'idle' ? 'متصل' : aiStatus === 'busy' ? 'جاري التوليد' : 'مغلق'}</span>
              </div>
           </div>

           <div className="space-y-2">
              <div className="flex justify-between text-[10px] font-black">
                 <span className="text-slate-400">استهلاك التوكنز</span>
                 <span className="text-blue-600 font-bold">{sessionTokens.toLocaleString()} / 100K</span>
              </div>
              <div className="h-1.5 w-full bg-slate-100 rounded-full overflow-hidden">
                 <div 
                   className={`h-full transition-all duration-1000 ${sessionTokens > 80000 ? 'bg-rose-500' : 'bg-blue-500'}`}
                   style={{ width: `${Math.min((sessionTokens / 100000) * 100, 100)}%` }}
                 ></div>
              </div>
              {sessionTokens > 90000 && <p className="text-[8px] font-bold text-rose-500 animate-pulse text-center">اقتربت من الحد الأقصى للجلسة</p>}
           </div>
        </div>

        <div className="p-6 pt-0 space-y-3">
           <label className="flex items-center justify-center gap-2 w-full py-4 bg-blue-600 text-white rounded-2xl cursor-pointer hover:bg-blue-700 transition-all font-black text-xs shadow-lg">
              <FileUp size={16} />
              <span>رفع سجل البصمة</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
           </label>
           {employees.length > 0 && (
             <button onClick={exportAuditToExcel} className="flex items-center justify-center gap-2 w-full py-4 bg-emerald-600 text-white rounded-2xl font-black text-xs shadow-lg hover:bg-emerald-700 transition-all">
                <Download size={16} /> تصدير التقرير
             </button>
           )}
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        <header className="h-20 px-6 lg:px-10 flex items-center justify-between shrink-0 bg-white/50 backdrop-blur-md z-10 border-b border-slate-50">
          <div className="flex items-center gap-4 flex-1">
             <button className="lg:hidden p-2 bg-slate-100 rounded-xl" onClick={() => setIsSidebarOpen(true)}>
               <Menu size={20} />
             </button>
             <div className="relative max-w-lg w-full">
                <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  type="text" 
                  placeholder="بحث سريع (رقم ACNo أو اسم الموظف)..." 
                  className="w-full bg-slate-50 border-none rounded-2xl pr-12 pl-4 py-3 text-xs font-black focus:outline-none focus:ring-2 focus:ring-blue-500/10 transition-all"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
             </div>
          </div>
          <div className="flex items-center gap-4">
             <button 
               onClick={handleAiAudit} 
               disabled={employees.length === 0 || isAnalyzing || aiStatus === 'busy'} 
               className={`hidden sm:flex items-center gap-2 px-6 py-3 rounded-2xl text-[10px] font-black transition-all shadow-md active:scale-95 ${aiStatus === 'busy' ? 'bg-slate-200 text-slate-500' : 'bg-slate-900 text-white hover:bg-blue-600'}`}
             >
               {aiStatus === 'busy' ? <RefreshCcw size={14} className="animate-spin" /> : <BrainCircuit size={14} />}
               تشغيل المدقق الجماعي
             </button>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto px-6 lg:px-10 pb-10 bento-scroll">
          {currentView === 'dashboard' && (
            <div className="max-w-screen-2xl mx-auto h-full flex flex-col gap-6 animate-bento">
              {stats ? (
                <>
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4 shrink-0">
                    <BentoStat title="إجمالي الموظفين" value={stats.totalEmployees} icon={<Users size={20}/>} color="bg-[#E0F2FE]" />
                    <BentoStat title="نسبة الانضباط" value={`${stats.completionRate}%`} icon={<UserCheck size={20}/>} color="bg-[#DCFCE7]" />
                    <BentoStat title="بصمات مسجلة" value={stats.totalPunches} icon={<Fingerprint size={20}/>} color="bg-[#F3E8FF]" />
                    <BentoStat title="سجلات ناقصة" value={stats.deficientEmployees} icon={<AlertCircle size={20}/>} color="bg-[#FCE7F3]" />
                  </div>
                  <div className="flex-1 min-h-0">
                    <div className="flex flex-col gap-4 overflow-hidden">
                       <div className="flex items-center justify-between px-2">
                         <h2 className="text-xl font-black text-slate-900">نظام البطاقات الذكية</h2>
                         <div className="flex items-center gap-2 text-[10px] font-bold text-slate-400">
                           <Info size={14} /> يتم فرز البطاقات آلياً حسب رقم ACNo
                         </div>
                       </div>
                       <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 overflow-y-auto bento-scroll pr-2 pb-6">
                          {filteredEmployees.map((emp, idx) => (
                            <BentoEmployeeCard key={emp.id} employee={emp} index={idx} onAuditUpdate={(tokens) => setSessionTokens(prev => prev + tokens)} onKeyNeeded={handleOpenKeySelector} />
                          ))}
                       </div>
                    </div>
                  </div>
                </>
              ) : <BentoEmptyState handleFileUpload={handleFileUpload} isAnalyzing={isAnalyzing} />}
            </div>
          )}
          {currentView === 'employees' && (
             <div className="max-w-screen-2xl mx-auto animate-bento">
                <h2 className="text-3xl font-black text-slate-900 mb-8 px-2">قاعدة بيانات الموظفين</h2>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                   {filteredEmployees.map((emp, idx) => (
                      <BentoEmployeeCard key={emp.id} employee={emp} index={idx} onAuditUpdate={(tokens) => setSessionTokens(prev => prev + tokens)} onKeyNeeded={handleOpenKeySelector} />
                   ))}
                </div>
             </div>
          )}
          {currentView === 'ai' && (
             <div className="max-w-4xl mx-auto h-full flex flex-col py-6 animate-bento">
                <div className="bento-card bg-white border border-slate-100 p-10 shadow-xl rounded-[3rem]">
                   <div className="flex items-center justify-between mb-8">
                      <div>
                         <h2 className="text-2xl font-black">تقرير التدقيق الفني المباشر</h2>
                         <p className="text-xs font-bold text-slate-400 mt-1">فحص ذكي وفوري لكافة السجلات والبحث عن النواقص</p>
                      </div>
                      <div className="p-4 bg-slate-900 text-white rounded-2xl shadow-xl">
                         <ShieldCheck size={24} />
                      </div>
                   </div>
                   <div className="bg-slate-50 p-8 rounded-[2rem] whitespace-pre-line text-sm font-bold leading-relaxed border border-slate-100 shadow-inner max-h-[60vh] overflow-y-auto bento-scroll">
                      {isAnalyzing ? (
                        <div className="flex flex-col items-center justify-center py-20 gap-4">
                           <RefreshCcw size={32} className="animate-spin text-blue-600" />
                           <p className="animate-pulse text-lg font-black">جاري تدقيق البيانات...</p>
                           <p className="text-xs text-slate-400">نقوم بتحليل سجلات {employees.length} موظفاً</p>
                        </div>
                      ) : bulkReport || (
                        <div className="flex flex-col items-center justify-center py-20 text-slate-400 gap-4">
                          <Zap size={40} className="opacity-20" />
                          <p>يرجى تشغيل المدقق من الزر العلوي لبدء التحليل.</p>
                        </div>
                      )}
                   </div>
                   <div className="mt-8 flex items-center justify-between">
                      <div className="flex items-center gap-3 bg-blue-50 px-5 py-3 rounded-2xl border border-blue-100">
                         <Zap size={16} className="text-blue-600" />
                         <span className="text-[11px] font-black text-blue-800 italic">نظام فحص أولي لضمان سرعة الاستجابة القصوى.</span>
                      </div>
                      <button onClick={exportAuditToExcel} className="px-8 py-3 bg-blue-600 text-white rounded-xl font-black text-xs hover:bg-blue-700 transition-all flex items-center gap-2 shadow-lg active:scale-95">
                         <Download size={14} /> تصدير التقرير
                      </button>
                   </div>
                </div>
             </div>
          )}
        </div>
      </main>
    </div>
  );
};

/* --- Components --- */

const NavItem = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-3 px-5 py-4 rounded-2xl text-[11px] font-black transition-all ${active ? 'nav-active' : 'text-slate-500 hover:bg-white'}`}>
    {icon}
    <span>{label}</span>
  </button>
);

const BentoStat = ({ title, value, icon, color }: any) => (
  <div className={`bento-card ${color} border-none p-6 flex flex-col justify-center`}>
     <div className="flex items-center justify-between mb-2">
        <div className="p-2 bg-white/40 rounded-xl text-slate-800 shadow-sm">{icon}</div>
        <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest">{title}</span>
     </div>
     <h4 className="text-2xl font-black text-slate-900 leading-none">{value}</h4>
  </div>
);

const KeyRequiredScreen = ({ onSelect }: { onSelect: () => void }) => (
  <div className="fixed inset-0 z-[200] bg-white flex items-center justify-center p-6 text-center">
    <div className="max-w-md w-full animate-bento">
      <div className="w-20 h-20 bg-blue-50 text-blue-600 rounded-3xl flex items-center justify-center mx-auto mb-8 shadow-xl">
        <Key size={40} />
      </div>
      <h2 className="text-3xl font-black text-slate-900 mb-4">تنشيط الذكاء الاصطناعي</h2>
      <p className="text-slate-500 font-bold mb-8 leading-relaxed">
        للوصول إلى ميزات التدقيق الذكي، يجب اختيار مفتاح API مفعل. هذا يضمن عمل النظام بأقصى سرعة ودقة.
      </p>
      <button 
        onClick={onSelect}
        className="w-full py-4 bg-blue-600 text-white rounded-2xl font-black shadow-xl hover:bg-blue-700 transition-all active:scale-95 flex items-center justify-center gap-2"
      >
        <ShieldCheck size={20} /> اختيار مفتاح التشغيل
      </button>
      <p className="mt-6 text-[10px] text-slate-400 font-black flex items-center justify-center gap-2 italic">
        <Info size={12} /> تتطلب هذه الخطوة حساباً مفعلاً في Google AI Studio
      </p>
    </div>
  </div>
);

const BentoEmployeeCard = ({ employee, index = 0, onAuditUpdate, onKeyNeeded }: { employee: EmployeeSummary, index?: number, onAuditUpdate?: (tokens: number) => void, onKeyNeeded: () => void }) => {
  const [showModal, setShowModal] = useState(false);
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const isComplete = employee.isEligible;

  const lastShift = employee.shifts[employee.shifts.length - 1];

  const handleAiAudit = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (loadingAi) return;

    setLoadingAi(true);
    try {
      const report = await generateDetailedAuditSummaryAI(employee);
      setAiReport(report.text);
      if (onAuditUpdate) onAuditUpdate(report.tokens);
    } catch (err: any) {
      if (err.message?.includes("API Key") || err.message?.includes("not found")) {
        onKeyNeeded();
      } else {
        setAiReport("⚠️ خطأ في الاتصال بالمدقق.");
      }
    } finally {
      setLoadingAi(false);
    }
  };

  return (
    <>
      <div 
        onClick={() => setShowModal(true)} 
        style={{ animationDelay: `${index * 30}ms` }}
        className={`bento-card animate-card-fade ${isComplete ? 'bg-[#DCFCE7]' : 'bg-[#FCE7F3]'} border-none group cursor-pointer p-6 flex flex-col gap-3 min-h-[220px] shadow-sm transition-all hover:shadow-xl hover:-translate-y-1`}
      >
        <div className="flex items-start justify-between">
           <div className="flex items-center gap-3">
              <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center font-black text-slate-900 shadow-sm border border-black/5">
                {employee.name.charAt(0)}
              </div>
              <div>
                 <h3 className="text-[13px] font-black text-slate-900 truncate max-w-[120px]">{employee.name}</h3>
                 <span className="text-[10px] font-bold text-slate-500 tracking-tighter">ACNo: {employee.id}</span>
              </div>
           </div>
           <div className={`px-2.5 py-1.5 rounded-lg text-[9px] font-black shadow-sm ${isComplete ? 'bg-emerald-200 text-emerald-800' : 'bg-rose-200 text-rose-800'}`}>
              {isComplete ? 'مكتمل' : 'ناقص'}
           </div>
        </div>

        <div className="mt-2 bg-white/40 p-3 rounded-2xl flex flex-col gap-2 shadow-inner border border-black/5">
           <span className="text-[8px] font-black text-slate-500 uppercase">ملخص البصمات (آخر يوم)</span>
           <div className="flex items-center gap-2">
              {["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"].map(p => {
                const found = lastShift?.punches_details.some(pd => pd.period === p && !pd.is_duplicate);
                return (
                  <div key={p} title={p} className={`w-6 h-6 rounded-lg flex items-center justify-center transition-all ${found ? 'bg-blue-600 text-white shadow-md scale-110' : 'bg-slate-200 text-slate-400 opacity-40'}`}>
                     {getMiniIcon(p)}
                  </div>
                );
              })}
           </div>
        </div>

        <div className="flex items-center justify-between mt-auto pt-2 border-t border-black/5">
           <div className="flex items-center gap-2">
              <Fingerprint size={14} className="text-blue-600" />
              <span className="text-sm font-black text-slate-900">{employee.totalPunches} بصمة</span>
           </div>
           <button onClick={handleAiAudit} title="مدقق البصمة الذكي" className="w-8 h-8 bg-white rounded-lg flex items-center justify-center text-slate-800 hover:bg-slate-900 hover:text-white transition-all shadow-sm active:scale-90 border border-black/5">
              {loadingAi ? <RefreshCcw size={12} className="animate-spin text-blue-600" /> : <BrainCircuit size={14} />}
           </button>
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-[150] flex items-center justify-center p-4 lg:p-12 bg-slate-900/60 backdrop-blur-xl overflow-hidden">
           <div className="bg-white w-full max-w-6xl h-full max-h-[92vh] rounded-[3.5rem] overflow-hidden flex flex-col animate-bento shadow-2xl border border-white/20">
              <div className="p-8 border-b border-slate-100 flex items-center justify-between shrink-0 bg-slate-50/50">
                 <div className="flex items-center gap-6">
                    <div className="w-16 h-16 bg-slate-900 text-white rounded-[1.8rem] flex items-center justify-center font-black text-2xl shadow-xl">
                       {employee.name.charAt(0)}
                    </div>
                    <div>
                       <h2 className="text-2xl font-black text-slate-900 mb-1">{employee.name}</h2>
                       <p className="text-xs font-bold text-slate-400 tracking-wide">الرقم الوظيفي: {employee.id} • إجمالي الأيام: {employee.shifts.length}</p>
                    </div>
                 </div>
                 <button onClick={() => setShowModal(false)} className="w-12 h-12 bg-white border border-slate-100 text-slate-400 rounded-xl hover:bg-rose-50 hover:text-rose-500 transition-all flex items-center justify-center shadow-sm">
                    <X size={20} />
                 </button>
              </div>

              <div className="flex-1 overflow-hidden flex flex-col lg:flex-row bg-white">
                 <div className="w-full lg:w-1/3 p-8 bg-slate-50/30 border-l border-slate-100 overflow-y-auto bento-scroll flex flex-col gap-6">
                    <div className="grid grid-cols-1 gap-4">
                       <BentoDetailBox title="معدل الاكتمال" value={`${employee.completionRate}%`} label="نسبة الأيام الصالحة" color="bg-[#DCFCE7]" />
                       <BentoDetailBox title="إجمالي الحركات" value={employee.totalPunches} label="حركة بصمة مسجلة" color="bg-[#E0F2FE]" />
                    </div>
                    <div className="bg-white rounded-[2rem] border border-slate-100 p-6 shadow-sm">
                       <h3 className="text-xs font-black text-slate-900 mb-4 flex items-center gap-2">
                         <BrainCircuit size={16} className="text-blue-600" /> ملخص النواقص (AI)
                       </h3>
                       <div className="text-[11px] font-bold text-slate-700 leading-relaxed italic whitespace-pre-line bg-slate-50/50 p-4 rounded-xl border border-slate-100 shadow-inner min-h-[100px]">
                          {loadingAi ? (
                            <div className="flex flex-col items-center justify-center gap-2 py-6">
                               <RefreshCcw size={20} className="animate-spin text-blue-600" />
                               <span className="text-[10px] font-black">جاري التدقيق الفوري...</span>
                            </div>
                          ) : aiReport || (
                            <div className="flex flex-col items-center justify-center py-6 gap-2 text-slate-300">
                              <Info size={24} />
                              <span className="text-[9px] font-black">اضغط لتفعيل التدقيق التقني</span>
                            </div>
                          )}
                       </div>
                       {!aiReport && !loadingAi && (
                         <button onClick={handleAiAudit} className="mt-4 w-full py-3 bg-slate-900 text-white rounded-xl text-[10px] font-black hover:bg-blue-600 transition-all shadow-md active:scale-95">تفعيل التدقيق الآن</button>
                       )}
                    </div>
                 </div>

                 <div className="flex-1 p-8 lg:p-10 overflow-y-auto bento-scroll">
                    <h3 className="text-lg font-black text-slate-900 mb-6 flex items-center gap-3">
                       <div className="w-1.5 h-6 bg-blue-600 rounded-full"></div>
                       سجل الحركات اليومي المجمع
                    </h3>
                    <div className="space-y-4">
                       {employee.shifts.map((shift, i) => {
                          const missingPeriods = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
                            .filter(p => !shift.punches_details.some(pd => pd.period === p && !pd.is_duplicate));

                          return (
                            <div key={i} className={`p-6 rounded-[2rem] border transition-all hover:shadow-lg ${shift.status === 'مكتملة' ? 'border-emerald-100 bg-emerald-50/10' : 'border-rose-100 bg-rose-50/10'}`}>
