                                     <div className={`w-10 h-10 rounded-xl flex items-center justify-center text-white shadow-sm ${shift.status === 'مكتملة' ? 'bg-emerald-500' : 'bg-rose-500'}`}>
                                        <Calendar size={18} />
                                     </div>
                                     <span className="font-black text-sm text-slate-900">{shift.shift_date}</span>
                                  </div>
                                  <span className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase shadow-sm ${shift.status === 'مكتملة' ? 'bg-emerald-100 text-emerald-700 border border-emerald-200' : 'bg-rose-100 text-rose-700 border border-rose-200'}`}>الحالة: {shift.status}</span>
                               </div>

                               {shift.status === 'ناقصة' && (
                                 <div className="mb-4 p-4 bg-rose-50/80 border border-rose-200 rounded-2xl text-[11px] font-black text-rose-600 flex flex-col gap-1 shadow-sm">
                                    <div className="flex items-center gap-2 mb-1">
                                      <FileWarning size={14} />
                                      <span className="underline decoration-rose-300 font-black">نواقص السجل:</span>
                                    </div>
                                    <div className="pr-6 leading-relaxed italic">
                                      {missingPeriods.length === 5 ? "(انقطاع كامل للبيانات اليومية)" : `(${missingPeriods.join(' ، ')})`}
                                    </div>
                                 </div>
                               )}

                               <div className="grid grid-cols-5 gap-2">
                                  {["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"].map(p => {
                                    const punch = shift.punches_details.find(pd => pd.period === p && !pd.is_duplicate);
                                    return (
                                      <div key={p} className={`p-3 rounded-2xl border text-center transition-all ${punch ? 'bg-blue-50 border-blue-100 shadow-sm' : 'bg-white border-slate-100 opacity-40 grayscale'}`}>
                                         <p className="text-[8px] font-black text-slate-400 mb-1">{p}</p>
                                         <p className="text-[10px] font-black text-slate-900">{punch ? punch.time : '--:--'}</p>
                                      </div>
                                    );
                                  })}
                               </div>
                            </div>
                          );
                       })}
                    </div>
                 </div>
              </div>
           </div>
        </div>
      )}
    </>
  );
};

