import React, { useState, useMemo, useEffect } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Fingerprint, RefreshCcw, 
  X, AlertCircle, Sunrise, Sun, Sunset, Moon, 
  LogOut as LogOutIcon, ShieldCheck, UserCheck, Clock,
  Zap, Download, FileWarning, Cpu, Key, Info, Activity
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary } from './types';

type ViewType = 'dashboard' | 'employees' | 'ai';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  // AI State
  const [aiStatus, setAiStatus] = useState<'idle' | 'busy' | 'error' | 'locked'>('idle');
  const [sessionTokens, setSessionTokens] = useState(0);
  const [hasApiKey, setHasApiKey] = useState<boolean | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      // Use window.aistudio helper functions to check API key status.
      // @ts-ignore
      if (window.aistudio) {
        // @ts-ignore
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(selected);
        if (!selected) setAiStatus('locked');
      } else {
        setHasApiKey(!!process.env.API_KEY);
      }
    };
    checkKey();
  }, []);

  const handleOpenKeySelector = async () => {
    // Open the API key selection dialog.
    // @ts-ignore
    if (window.aistudio) {
      // @ts-ignore
      await window.aistudio.openSelectKey();
      // Assume success immediately after triggering openSelectKey to avoid race conditions.
      setHasApiKey(true);
      setAiStatus('idle');
    }
  };

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
      deficientEmployees: employees.filter(e => !e.isEligible).length
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
        const json = XLSX.utils.sheet_to_json(firstSheet);

        if (json.length === 0) {
          alert("الملف المرفوع فارغ.");
          return;
        }

        const processed = processExcelData(json);
        setEmployees(processed);
        setBulkReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف. يرجى التأكد من صيغة Excel الصحيحة.");
      } finally {
        setIsAnalyzing(false);
        event.target.value = '';
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleAiAudit = async () => {
    if (employees.length === 0) return;
    if (!hasApiKey) {
      handleOpenKeySelector();
      return;
    }

    setIsAnalyzing(true);
    setAiStatus('busy');
    setCurrentView('ai');
    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result.text);
      setSessionTokens(prev => prev + result.tokens);
      setAiStatus('idle');
    } catch (e: any) { 
      console.error(e);
      // Reset key selection if entity not found error occurs as per guidelines.
      if (e.message?.includes("not found")) {
        setHasApiKey(false);
        setAiStatus('locked');
      } else {
        setAiStatus('error');
      }
    } finally { 
      setIsAnalyzing(false); 
    }
  };

  const exportAuditToExcel = () => {
    if (employees.length === 0) return;
    const exportData = employees.map(emp => {
      const missingDaysDetails = emp.shifts
        .filter(s => s.status === 'ناقصة')
        .map(s => {
          const missingPeriods = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
            .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate));
          return `${s.shift_date}: (${missingPeriods.join(' - ')})`;
        }).join(' | ');
      return {
        "ACNo": emp.id,
        "الاسم": emp.name,
        "الحالة": emp.isEligible ? "مكتمل" : "ناقص",
        "البصمات": emp.totalPunches,
        "التفاصيل": missingDaysDetails || "سجل سليم"
      };
    });
    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "تدقيق البصمة");
    XLSX.writeFile(workbook, `Bantomi_Pro_Audit_${new Date().getTime()}.xlsx`);
  };

  return (
    <div className="flex h-screen bg-[#f8fafc] text-[#1e293b] rtl overflow-hidden">
      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 right-0 z-[100] w-72 bg-white border-l border-slate-100 flex flex-col transition-all duration-300 transform ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'} shadow-2xl lg:shadow-none`}>
        <div className="p-8">
           <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-200">
                 <ShieldCheck size={24} />
              </div>
              <h1 className="text-xl font-black tracking-tight">بصمتي <span className="text-blue-600">برو</span></h1>
           </div>
        </div>

        <nav className="flex-1 px-4 space-y-2 mt-4">
          <NavItem icon={<LayoutDashboard size={18}/>} label="لوحة التحكم" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <NavItem icon={<Users size={18}/>} label="سجل الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
          <NavItem icon={<BrainCircuit size={18}/>} label="المدقق الذكي" active={currentView === 'ai'} onClick={() => { setCurrentView('ai'); setIsSidebarOpen(false); }} />
        </nav>

        {/* AI Performance Monitor Card */}
        <div className="mx-4 mb-6 p-5 bg-slate-900 text-white rounded-[2rem] shadow-xl relative overflow-hidden group">
           <div className="absolute top-0 left-0 w-full h-full bg-blue-600/10 opacity-0 group-hover:opacity-100 transition-opacity"></div>
           <div className="flex items-center justify-between mb-4 relative z-10">
              <div className="flex items-center gap-2">
                 <Cpu size={16} className="text-blue-400" />
                 <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">حالة النظام</span>
              </div>
              <div className={`px-2 py-0.5 rounded-full text-[8px] font-black flex items-center gap-1 ${aiStatus === 'idle' ? 'bg-emerald-500/20 text-emerald-400' : 'bg-amber-500/20 text-amber-400'}`}>
                 <div className={`w-1 h-1 rounded-full ${aiStatus === 'idle' ? 'bg-emerald-400' : 'bg-amber-400 animate-pulse'}`}></div>
                 {aiStatus === 'idle' ? 'مستقر' : 'نشط'}
              </div>
           </div>

           <div className="space-y-3 relative z-10">
              <div className="flex justify-between text-[10px] font-bold">
                 <span className="text-slate-400">استهلاك التوكنز</span>
                 <span className="text-blue-400">{sessionTokens.toLocaleString()} / 100K</span>
              </div>
              <div className="h-1.5 w-full bg-slate-800 rounded-full overflow-hidden">
                 <div 
                   className="h-full bg-blue-500 transition-all duration-700"
                   style={{ width: `${Math.min((sessionTokens / 100000) * 100, 100)}%` }}
                 ></div>
              </div>
           </div>
        </div>

        <div className="p-6 pt-0 space-y-3">
           <label className="flex items-center justify-center gap-3 w-full py-4 bg-blue-600 text-white rounded-2xl cursor-pointer hover:bg-blue-700 transition-all font-black text-xs shadow-lg shadow-blue-100 active:scale-95">
              <FileUp size={18} />
              <span>رفع ملف جديد</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
           </label>
           {employees.length > 0 && (
             <button onClick={exportAuditToExcel} className="flex items-center justify-center gap-3 w-full py-4 bg-white border border-slate-200 text-slate-700 rounded-2xl font-black text-xs shadow-sm hover:bg-slate-50 transition-all active:scale-95">
                <Download size={18} /> تصدير البيانات
             </button>
           )}
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative bg-white lg:rounded-r-[3rem] lg:my-4 lg:ml-4 shadow-sm border border-slate-100">
        <header className="h-20 px-6 lg:px-10 flex items-center justify-between shrink-0 bg-white/80 backdrop-blur-md z-40">
          <div className="flex items-center gap-4 flex-1">
             <button className="lg:hidden p-2 bg-slate-100 rounded-xl" onClick={() => setIsSidebarOpen(true)}>
               <Menu size={20} />
             </button>
             <div className="relative max-w-lg w-full">
                <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  type="text" 
                  placeholder="ابحث بالاسم أو الرقم الوظيفي..." 
                  className="w-full bg-slate-50 border-none rounded-2xl pr-12 pl-4 py-3 text-xs font-black focus:outline-none focus:ring-2 focus:ring-blue-500/10 transition-all placeholder:text-slate-300"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
             </div>
          </div>
          <div className="flex items-center gap-4">
             <button 
               onClick={handleAiAudit} 
               disabled={employees.length === 0 || isAnalyzing || aiStatus === 'busy'} 
               className={`flex items-center gap-2 px-5 py-2.5 rounded-xl text-[10px] font-black transition-all shadow-md active:scale-95 ${aiStatus === 'busy' ? 'bg-slate-100 text-slate-400' : 'bg-slate-900 text-white hover:bg-blue-600'}`}
             >
               {aiStatus === 'busy' ? <RefreshCcw size={14} className="animate-spin" /> : <BrainCircuit size={14} />}
               <span className="hidden sm:inline">تشغيل التدقيق الذكي</span>
             </button>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto px-6 lg:px-10 pb-10 bento-scroll">
          {currentView === 'dashboard' && (
            <div className="max-w-screen-2xl mx-auto h-full flex flex-col gap-8 pt-4">
              {stats ? (
                <>
                  <div className="grid grid-cols-2 md:grid-cols-4 gap-5 shrink-0">
                    <BentoStat title="إجمالي القوة" value={stats.totalEmployees} icon={<Users size={20}/>} color="bg-blue-50 text-blue-600" />
                    <BentoStat title="الانضباط العام" value={`${stats.completionRate}%`} icon={<UserCheck size={20}/>} color="bg-emerald-50 text-emerald-600" />
                    <BentoStat title="حركات البصمة" value={stats.totalPunches} icon={<Fingerprint size={20}/>} color="bg-purple-50 text-purple-600" />
                    <BentoStat title="نواقص مرصودة" value={stats.deficientEmployees} icon={<AlertCircle size={20}/>} color="bg-rose-50 text-rose-600" />
                  </div>
                  <div className="flex-1 min-h-0 flex flex-col gap-6">
                     <div className="flex items-center justify-between px-2">
                       <h2 className="text-2xl font-black text-slate-900 tracking-tight">قائمة بطاقات الموظفين</h2>
                       <div className="flex items-center gap-2 px-3 py-1.5 bg-slate-50 rounded-lg border border-slate-100 text-[10px] font-bold text-slate-400">
                          <Activity size={12} /> الحالة: {filteredEmployees.length} بطاقة معروضة
                       </div>
                     </div>
                     <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-5 overflow-y-auto bento-scroll pr-2 pb-10">
                        {filteredEmployees.map((emp, idx) => (
                          <BentoEmployeeCard key={emp.id} employee={emp} index={idx} onAuditUpdate={(tokens) => setSessionTokens(prev => prev + tokens)} onKeyNeeded={handleOpenKeySelector} />
                        ))}
                     </div>
                  </div>
                </>
              ) : <BentoEmptyState handleFileUpload={handleFileUpload} isAnalyzing={isAnalyzing} />}
            </div>
          )}

          {currentView === 'ai' && (
             <div className="max-w-4xl mx-auto h-full flex flex-col py-8 animate-in">
                <div className="bg-white border border-slate-100 p-10 shadow-2xl rounded-[3.5rem] relative overflow-hidden">
                   <div className="absolute top-0 right-0 w-64 h-64 bg-blue-50 rounded-full -mr-32 -mt-32 blur-3xl opacity-50"></div>
                   <div className="flex items-center justify-between mb-10 relative z-10">
                      <div>
                         <h2 className="text-3xl font-black text-slate-900">تقرير التدقيق التقني</h2>
                         <p className="text-sm font-bold text-slate-400 mt-2">تحليل ذكي فوري لبيانات بصمة الدوام المرصودة</p>
                      </div>
                      <div className="w-16 h-16 bg-slate-900 text-white rounded-3xl flex items-center justify-center shadow-2xl">
                         <BrainCircuit size={32} />
                      </div>
                   </div>

                   <div className="bg-slate-50/50 p-8 rounded-[2.5rem] whitespace-pre-line text-sm font-bold leading-relaxed border border-slate-100 shadow-inner max-h-[55vh] overflow-y-auto bento-scroll relative z-10">
                      {isAnalyzing ? (
                        <div className="flex flex-col items-center justify-center py-20 gap-6">
                           <div className="relative">
                              <RefreshCcw size={48} className="animate-spin text-blue-600" />
                              <div className="absolute inset-0 flex items-center justify-center">
                                 <Zap size={16} className="text-blue-400 animate-pulse" />
                              </div>
                           </div>
                           <div className="text-center">
                              <p className="text-lg font-black text-slate-900">جاري تحليل {employees.length} سجلاً...</p>
                              <p className="text-xs text-slate-400 mt-1 uppercase tracking-widest font-black">AI is thinking</p>
                           </div>
                        </div>
                      ) : bulkReport ? (
                        <div className="text-slate-700 animate-in">{bulkReport}</div>
                      ) : (
                        <div className="flex flex-col items-center justify-center py-24 text-slate-300 gap-6">
                          <Zap size={56} className="opacity-10" />
                          <p className="font-black text-slate-400">اضغط على زر "تشغيل التدقيق الذكي" لبدء الفحص.</p>
                        </div>
                      )}
                   </div>

                   <div className="mt-10 flex items-center justify-between relative z-10">
                      <div className="flex items-center gap-3 bg-white px-5 py-3 rounded-2xl border border-slate-100 shadow-sm">
                         <Info size={16} className="text-blue-500" />
                         <span className="text-[11px] font-black text-slate-500">تم فحص أهم الحالات لضمان جودة الأداء التقني.</span>
                      </div>
                      <button onClick={exportAuditToExcel} className="px-10 py-4 bg-blue-600 text-white rounded-2xl font-black text-xs hover:bg-blue-700 transition-all flex items-center gap-3 shadow-xl shadow-blue-200 active:scale-95">
                         <Download size={18} /> حفظ كملف Excel
                      </button>
                   </div>
                </div>
             </div>
          )}
        </div>
      </main>
    </div>
  );
};

/* --- Components --- */

const NavItem = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl text-[11px] font-black transition-all group ${active ? 'bg-blue-50 text-blue-600 shadow-sm border border-blue-100' : 'text-slate-400 hover:bg-slate-50 hover:text-slate-600'}`}>
    <div className={`transition-transform group-hover:scale-110 ${active ? 'text-blue-600' : 'text-slate-300'}`}>{icon}</div>
    <span>{label}</span>
  </button>
);

const BentoStat = ({ title, value, icon, color }: any) => (
  <div className={`p-6 rounded-[2.5rem] ${color} flex flex-col justify-between min-h-[140px] shadow-sm border border-black/5 animate-in`}>
     <div className="flex items-center justify-between">
        <div className="p-2.5 bg-white/60 rounded-xl shadow-sm">{icon}</div>
        <span className="text-[9px] font-black uppercase tracking-widest opacity-60">{title}</span>
     </div>
     <h4 className="text-3xl font-black leading-none mt-4">{value}</h4>
  </div>
);

// Defined an interface for BentoEmployeeCard props to resolve TypeScript recognition of standard React attributes.
interface BentoEmployeeCardProps {
  employee: EmployeeSummary;
  index?: number;
  onAuditUpdate?: (tokens: number) => void;
  onKeyNeeded: () => void | Promise<void>;
}

// Fixed: Wrapping BentoEmployeeCard with React.FC ensures React's internal props (like 'key') are correctly handled.
const BentoEmployeeCard: React.FC<BentoEmployeeCardProps> = ({ employee, index = 0, onAuditUpdate, onKeyNeeded }) => {
  const [showModal, setShowModal] = useState(false);
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [loadingAi, setLoadingAi] = useState(false);
  const isComplete = employee.isEligible;
  const lastShift = employee.shifts[employee.shifts.length - 1];

  const handleAiAudit = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (loadingAi) return;
    setLoadingAi(true);
    try {
      const report = await generateDetailedAuditSummaryAI(employee);
      setAiReport(report.text);
      if (onAuditUpdate) onAuditUpdate(report.tokens);
    } catch (err: any) {
      if (err.message?.includes("API Key") || err.message?.includes("not found")) onKeyNeeded();
      else setAiReport("⚠️ تعذر الاتصال بالخادم.");
    } finally {
      setLoadingAi(false);
    }
  };

  return (
    <>
      <div 
        onClick={() => setShowModal(true)} 
        style={{ animationDelay: `${index * 40}ms` }}
        className={`p-6 rounded-[2.5rem] border-none cursor-pointer flex flex-col gap-4 min-h-[240px] shadow-sm transition-all hover:shadow-2xl hover:-translate-y-2 animate-in group ${isComplete ? 'bg-emerald-50/50' : 'bg-rose-50/50'}`}
      >
        <div className="flex items-start justify-between">
           <div className="flex items-center gap-4">
              <div className="w-14 h-14 bg-white rounded-2xl flex items-center justify-center font-black text-xl text-slate-800 shadow-sm border border-slate-100 group-hover:scale-110 transition-transform">
                {employee.name.charAt(0)}
              </div>
              <div>
                 <h3 className="text-sm font-black text-slate-900 truncate max-w-[130px] leading-tight mb-1">{employee.name}</h3>
                 <span className="text-[10px] font-bold text-slate-400 bg-white px-2 py-0.5 rounded-md border border-slate-100">ACNo: {employee.id}</span>
              </div>
           </div>
           <div className={`px-3 py-1.5 rounded-xl text-[9px] font-black shadow-sm ${isComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
              {isComplete ? 'سجل مكتمل' : 'نواقص'}
           </div>
        </div>

        <div className="bg-white/60 p-4 rounded-3xl flex flex-col gap-3 shadow-inner border border-black/5">
           <div className="flex items-center justify-between">
              <span className="text-[8px] font-black text-slate-400 uppercase tracking-tighter">آخر بصمات مرصودة</span>
              <div className="flex items-center gap-1">
                 <div className="w-1.5 h-1.5 rounded-full bg-blue-500 animate-pulse"></div>
                 <span className="text-[8px] font-black text-blue-600">LIVE</span>
              </div>
           </div>
           <div className="flex items-center gap-2.5">
              {["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"].map(p => {
                const found = lastShift?.punches_details.some(pd => pd.period === p && !pd.is_duplicate);
                return (
                  <div key={p} title={p} className={`w-7 h-7 rounded-xl flex items-center justify-center transition-all ${found ? 'bg-slate-900 text-white shadow-lg' : 'bg-slate-200/50 text-slate-300'}`}>
                     {getMiniIcon(p)}
                  </div>
                );
              })}
           </div>
        </div>

        <div className="flex items-center justify-between mt-auto pt-4 border-t border-slate-200/50">
           <div className="flex items-center gap-2">
              <div className="w-7 h-7 bg-blue-50 text-blue-600 rounded-lg flex items-center justify-center">
                 <Fingerprint size={16} />
              </div>
              <span className="text-sm font-black text-slate-900">{employee.totalPunches} بصمة</span>
           </div>
           <button onClick={handleAiAudit} className="w-10 h-10 bg-white rounded-xl flex items-center justify-center text-slate-400 hover:bg-slate-900 hover:text-white transition-all shadow-sm border border-slate-100 active:scale-90">
              {loadingAi ? <RefreshCcw size={16} className="animate-spin text-blue-600" /> : <BrainCircuit size={18} />}
           </button>
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 lg:p-10 bg-slate-900/40 backdrop-blur-xl overflow-hidden animate-in">
           <div className="bg-white w-full max-w-6xl h-full max-h-[92vh] rounded-[4rem] overflow-hidden flex flex-col shadow-2xl border border-white/20">
              <div className="p-8 lg:p-10 border-b border-slate-50 flex items-center justify-between shrink-0 bg-slate-50/30">
                 <div className="flex items-center gap-8">
                    <div className="w-20 h-20 bg-slate-900 text-white rounded-[2rem] flex items-center justify-center font-black text-3xl shadow-2xl">
                       {employee.name.charAt(0)}
                    </div>
                    <div>
                       <h2 className="text-3xl font-black text-slate-900 mb-2">{employee.name}</h2>
                       <div className="flex gap-3">
                          <span className="px-3 py-1 bg-white border border-slate-100 rounded-lg text-xs font-bold text-slate-400">الرقم الوظيفي: {employee.id}</span>
                          <span className="px-3 py-1 bg-white border border-slate-100 rounded-lg text-xs font-bold text-slate-400">إجمالي النوبات: {employee.shifts.length}</span>
                       </div>
                    </div>
                 </div>
                 <button onClick={() => setShowModal(false)} className="w-14 h-14 bg-white border border-slate-100 text-slate-400 rounded-2xl hover:bg-rose-50 hover:text-rose-500 transition-all flex items-center justify-center shadow-sm">
                    <X size={24} />
                 </button>
              </div>

              <div className="flex-1 overflow-hidden flex flex-col lg:flex-row bg-white">
                 <div className="w-full lg:w-1/3 p-10 bg-slate-50/50 border-l border-slate-100 overflow-y-auto bento-scroll flex flex-col gap-8">
                    <div className="grid grid-cols-1 gap-5">
                       <BentoDetailBox title="مستوى الانضباط" value={`${employee.completionRate}%`} label="نسبة اكتمال النوبات" color="bg-emerald-50 text-emerald-600" />
                       <BentoDetailBox title="إجمالي الحركات" value={employee.totalPunches} label="حركة بصمة مسجلة" color="bg-blue-50 text-blue-600" />
                    </div>

                    <div className="bg-white rounded-[3rem] border border-slate-100 p-8 shadow-sm relative overflow-hidden">
                       <div className="absolute top-0 right-0 w-24 h-24 bg-blue-50/50 rounded-full -mr-12 -mt-12"></div>
                       <h3 className="text-xs font-black text-slate-900 mb-6 flex items-center gap-2 relative z-10">
                         <BrainCircuit size={18} className="text-blue-500" /> تقرير النواقص الذكي
                       </h3>
                       <div className="text-xs font-bold text-slate-600 leading-relaxed italic whitespace-pre-line bg-slate-50/50 p-6 rounded-3xl border border-slate-100 shadow-inner min-h-[140px] relative z-10">
                          {loadingAi ? (
                            <div className="flex flex-col items-center justify-center gap-4 py-8">
                               <RefreshCcw size={24} className="animate-spin text-blue-600" />
                               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Analysing Data</span>
                            </div>
                          ) : aiReport || (
                            <div className="flex flex-col items-center justify-center py-10 gap-3 text-slate-300">
                              <Info size={32} />
                              <span className="text-[10px] font-black">اضغط لتوليد التقرير الفني</span>
                            </div>
                          )}
                       </div>
                       {!aiReport && !loadingAi && (
                         <button onClick={handleAiAudit} className="mt-6 w-full py-4 bg-slate-900 text-white rounded-2xl text-[10px] font-black hover:bg-blue-600 transition-all shadow-xl active:scale-95">بدء التحليل الفوري</button>
                       )}
                    </div>
                 </div>

                 <div className="flex-1 p-10 overflow-y-auto bento-scroll bg-white">
                    <h3 className="text-xl font-black text-slate-900 mb-8 flex items-center gap-4">
                       <div className="w-2 h-8 bg-blue-600 rounded-full"></div>
                       سجل البصمات اليومي المجمع
                    </h3>
                    <div className="space-y-6">
                       {employee.shifts.map((shift, i) => {
                          const missingPeriods = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
                            .filter(p => !shift.punches_details.some(pd => pd.period === p && !pd.is_duplicate));

                          return (
                            <div key={i} className={`p-8 rounded-[3rem] border transition-all hover:shadow-xl ${shift.status === 'مكتملة' ? 'border-emerald-100 bg-emerald-50/10' : 'border-rose-100 bg-rose-50/10'}`}>
                               <div className="flex justify-between items-center mb-6">
                                  <div className="flex items-center gap-4">
                                     <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-white shadow-lg ${shift.status === 'مكتملة' ? 'bg-emerald-500 shadow-emerald-100' : 'bg-rose-500 shadow-rose-100'}`}>
                                        <Calendar size={22} />
                                     </div>
                                     <span className="font-black text-lg text-slate-800">{shift.shift_date}</span>
                                  </div>
                                  <span className={`px-4 py-1.5 rounded-xl text-[10px] font-black shadow-sm ${shift.status === 'مكتملة' ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>الحالة: {shift.status}</span>
                               </div>

                               {shift.status === 'ناقصة' && (
                                 <div className="mb-6 p-5 bg-white border border-rose-100 rounded-[2rem] text-xs font-bold text-rose-600 flex flex-col gap-2 shadow-sm">
                                    <div className="flex items-center gap-2 mb-1">
                                      <FileWarning size={16} />
                                      <span className="font-black text-rose-700">النواقص المرصودة في النوبة:</span>
                                    </div>
                                    <div className="pr-6 leading-relaxed italic bg-rose-50/50 p-3 rounded-xl">
                                      {missingPeriods.length === 5 ? "لم يتم رصد أي حركات لهذا اليوم (غياب أو انقطاع بيانات)" : `(${missingPeriods.join(' • ')})`}
                                    </div>
                                 </div>
                               )}

                               <div className="grid grid-cols-5 gap-3">
                                  {["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"].map(p => {
                                    const punch = shift.punches_details.find(pd => pd.period === p && !pd.is_duplicate);
                                    return (
                                      <div key={p} className={`p-4 rounded-3xl border text-center transition-all ${punch ? 'bg-white border-blue-100 shadow-md' : 'bg-slate-50 border-slate-100 opacity-40 grayscale'}`}>
                                         <div className="w-8 h-8 bg-slate-50 rounded-xl mx-auto mb-2 flex items-center justify-center text-slate-400">{getMiniIcon(p)}</div>
                                         <p className="text-[8px] font-black text-slate-400 mb-1">{p}</p>
                                         <p className="text-xs font-black text-slate-900 tracking-tighter">{punch ? punch.time : '--:--'}</p>
                                      </div>
                                    );
                                  })}
                               </div>
                            </div>
                          );
                       })}
                    </div>
                 </div>
              </div>
           </div>
        </div>
      )}
    </>
  );
};

const getMiniIcon = (period: string) => {
  const s = 14;
  switch (period) {
    case 'دخول صباحي': return <Sunrise size={s} />;
    case 'بصمة وسطية': return <Sun size={s} />;
    case 'بصمة مسائية': return <Sunset size={s} />;
