import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary } from "../types";

/**
 * دالة مساعدة للحصول على المفتاح بأمان
 */
const getApiKey = () => {
  return typeof process !== 'undefined' ? process.env?.API_KEY : undefined;
};

/**
 * المدقق الذكي الفردي
 */
export const generateDetailedAuditSummaryAI = async (employee: EmployeeSummary): Promise<{ text: string; tokens: number }> => {
  const apiKey = getApiKey();
  if (!apiKey) {
    throw new Error("API_KEY_MISSING");
  }

  // إنشاء مثيل جديد عند كل طلب لضمان تحديث المفتاح
  const ai = new GoogleGenAI({ apiKey });

  const data = employee.shifts
    .filter(s => s.status === 'ناقصة')
    .map(s => `${s.shift_date}: ${["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
        .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate))
        .join(',')}`);

  if (data.length === 0) return { text: "✅ السجل مكتمل تقنياً.", tokens: 0 };

  const prompt = `بصفتك مدقق تقني، لخص نواقص البصمة التالية لموظف واحد (التاريخ: النواقص):
${data.join('\n')}
الرد بالعربية، نقاط سريعة واحترافية فقط.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        temperature: 0.2, 
        maxOutputTokens: 200,
      }
    });

    const text = response.text || "لا توجد تفاصيل إضافية.";
    const estimatedTokens = Math.ceil(text.length / 2); // تقدير تقريبي للتوكنز

    return { text, tokens: estimatedTokens };
  } catch (error) {
    console.error("AI Error:", error);
    throw error;
  }
};

/**
 * المدقق الذكي الجماعي
 */
export const generateBulkAuditSummaryAI = async (employees: EmployeeSummary[]): Promise<{ text: string; tokens: number; count: number }> => {
  const apiKey = getApiKey();
  if (!apiKey) {
    throw new Error("API_KEY_MISSING");
  }

  const ai = new GoogleGenAI({ apiKey });

  const problematic = employees
    .filter(e => !e.isEligible)
    .slice(0, 10)
    .map(e => ({
      id: e.id,
      name: e.name,
      missing: e.shifts.filter(s => s.status === 'ناقصة').map(s => ({
        date: s.shift_date,
        periods: ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
          .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate))
      }))
    }));

  if (problematic.length === 0) return { text: "✅ جميع الموظفين لديهم سجلات كاملة.", tokens: 0, count: 0 };

  const prompt = `تقرير تدقيق إداري (بالعربية) لـ ${problematic.length} موظف:
${JSON.stringify(problematic)}
أذكر الأسماء والتواريخ والنواقص بشكل موجز جداً ومهني.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        temperature: 0.1,
        maxOutputTokens: 1000,
      }
    });

    const text = response.text || "فشل التحليل.";
    const estimatedTokens = Math.ceil(text.length / 2);

    return { 
      text,
      tokens: estimatedTokens,
      count: problematic.length
    };
  } catch (error) {
    console.error("Bulk AI Error:", error);
    throw error;
  }
};

import React, { useState, useMemo, useEffect } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Fingerprint, RefreshCcw, 
  X, AlertCircle, Sunrise, Sun, Sunset, Moon, 
  LogOut as LogOutIcon, ShieldCheck, UserCheck, Clock,
  Zap, Download, FileWarning, Cpu, Key, Info, Activity
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary } from './types';

type ViewType = 'dashboard' | 'employees' | 'ai';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  // AI State
  const [aiStatus, setAiStatus] = useState<'idle' | 'busy' | 'error' | 'locked'>('idle');
  const [sessionTokens, setSessionTokens] = useState(0);
  const [hasApiKey, setHasApiKey] = useState<boolean | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      if (typeof window !== 'undefined' && window.aistudio) {
        // @ts-ignore
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(selected);
        if (!selected) setAiStatus('locked');
      } else {
        // التحقق من وجود المفتاح في متغيرات البيئة (لـ Netlify وغيرها)
        const keyExists = !!(typeof process !== 'undefined' && process.env?.API_KEY);
        setHasApiKey(keyExists);
        if (!keyExists) setAiStatus('locked');
      }
    };
    checkKey();
  }, []);

  const handleOpenKeySelector = async () => {
    // @ts-ignore
    if (typeof window !== 'undefined' && window.aistudio) {
      // @ts-ignore
      await window.aistudio.openSelectKey();
      setHasApiKey(true);
      setAiStatus('idle');
    } else {
      alert("تنبيه: يرجى التأكد من إضافة API_KEY في إعدادات البيئة (Environment Variables) في لوحة تحكم Netlify.");
    }
  };

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
      deficientEmployees: employees.filter(e => !e.isEligible).length
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
        const json = XLSX.utils.sheet_to_json(firstSheet);

        if (json.length === 0) {
          alert("الملف المرفوع فارغ.");
          return;
        }

        const processed = processExcelData(json);
        setEmployees(processed);
        setBulkReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
        event.target.value = '';
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleAiAudit = async () => {
    if (employees.length === 0) return;
    if (!hasApiKey) {
      handleOpenKeySelector();
      return;
    }

    setIsAnalyzing(true);
    setAiStatus('busy');
    setCurrentView('ai');
    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result.text);
      setSessionTokens(prev => prev + result.tokens);
      setAiStatus('idle');
    } catch (e: any) { 
      console.error(e);
      if (e.message?.includes("API_KEY_MISSING") || e.message?.includes("not found")) {
        setHasApiKey(false);
        setAiStatus('locked');
      } else {
        setAiStatus('error');
      }
    } finally { 
      setIsAnalyzing(false); 
    }
  };

