import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary } from "../types";

/**
 * دالة الحصول على المفتاح بأمان من المتصفح أو البيئة
 */
const getSafeApiKey = (): string | undefined => {
  try {
    // محاولة الحصول على المفتاح من متغيرات البيئة
    return process.env.API_KEY;
  } catch {
    return undefined;
  }
};

/**
 * إنشاء مثيل الذكاء الاصطناعي بشكل لحظي لضمان الحداثة
 */
const createAiClient = () => {
  const apiKey = getSafeApiKey();
  if (!apiKey) throw new Error("API_KEY_MISSING");
  return new GoogleGenAI({ apiKey });
};

export const generateDetailedAuditSummaryAI = async (employee: EmployeeSummary): Promise<{ text: string; tokens: number }> => {
  try {
    const ai = createAiClient();

    const missingData = employee.shifts
      .filter(s => s.status === 'ناقصة')
      .map(s => {
        const missing = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
          .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate));
        return `${s.shift_date}: (${missing.join(', ')})`;
      });

    if (missingData.length === 0) return { text: "✅ السجل التقني مكتمل تماماً.", tokens: 0 };

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `بصفتك مدقق جودة، حلل نواقص البصمة التالية للموظف (${employee.name}):\n${missingData.join('\n')}\nالرد بالعربية، موجز جداً وتقني.`,
      config: { temperature: 0.1 }
    });

    const text = response.text || "لا توجد ملاحظات.";
    return { text, tokens: text.length };
  } catch (error) {
    console.error("Single Audit Error:", error);
    throw error;
  }
};

export const generateBulkAuditSummaryAI = async (employees: EmployeeSummary[]): Promise<{ text: string; tokens: number }> => {
  try {
    const ai = createAiClient();

    const problematic = employees
      .filter(e => !e.isEligible)
      .slice(0, 15)
      .map(e => `${e.name} (ID:${e.id}): لديه نواقص في ${e.shifts.filter(s => s.status === 'ناقصة').length} نوبة.`);

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `قدم تقريراً إدارياً مختصراً عن حالة الانضباط لهؤلاء الموظفين:\n${problematic.join('\n')}\nالرد بالعربية، نقاط مهنية.`,
      config: { temperature: 0.1 }
    });

    const text = response.text || "فشل التحليل الجماعي.";
    return { text, tokens: text.length };
  } catch (error) {
    console.error("Bulk Audit Error:", error);
    throw error;
  }
};

import React, { useState, useMemo, useEffect } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Fingerprint, RefreshCcw, 
  X, AlertCircle, Sunrise, Sun, Sunset, Moon, 
  LogOut as LogOutIcon, ShieldCheck, UserCheck, Clock,
  Zap, Download, FileWarning, Cpu, Key, Info, Activity
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary } from './types';

type ViewType = 'dashboard' | 'employees' | 'ai';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  // AI State
  const [aiStatus, setAiStatus] = useState<'idle' | 'busy' | 'error' | 'locked'>('idle');
  const [sessionTokens, setSessionTokens] = useState(0);
  const [hasApiKey, setHasApiKey] = useState<boolean | null>(null);

  // فحص وجود المفتاح عند التحميل
  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      if (typeof window !== 'undefined' && window.aistudio) {
        // @ts-ignore
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(selected);
        if (!selected) setAiStatus('locked');
      } else {
        const keyExists = !!(typeof process !== 'undefined' && process.env?.API_KEY);
        setHasApiKey(keyExists);
        if (!keyExists) setAiStatus('locked');
      }
    };
    checkKey();
  }, []);

  const handleOpenKeySelector = async () => {
    // @ts-ignore
    if (typeof window !== 'undefined' && window.aistudio) {
      // @ts-ignore
      await window.aistudio.openSelectKey();
      setHasApiKey(true);
      setAiStatus('idle');
    } else {
      alert("⚠️ المفتاح غير معرف في Netlify. يرجى إضافته في إعدادات البيئة باسم API_KEY.");
    }
  };

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleAiAudit = async () => {
    if (employees.length === 0) return;

    // محاولة ذكية: إذا لم يكن هناك مفتاح، نفتح النافذة ونحاول المتابعة
    if (!hasApiKey) {
      await handleOpenKeySelector();
    }

    setIsAnalyzing(true);
    setAiStatus('busy');
    setCurrentView('ai');
    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result.text);
      setSessionTokens(prev => prev + result.tokens);
      setAiStatus('idle');
    } catch (e: any) { 
      console.error(e);
      if (e.message?.includes("API_KEY_MISSING") || e.message?.includes("not found")) {
        setHasApiKey(false);
        setAiStatus('locked');
      } else {
        setAiStatus('error');
      }
    } finally { 
      setIsAnalyzing(false); 
    }
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
        const json = XLSX.utils.sheet_to_json(firstSheet);
        const processed = processExcelData(json);
        setEmployees(processed);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في قراءة ملف Excel.");
      } finally {
        setIsAnalyzing(false);
        event.target.value = '';
      }
    };
    reader.readAsArrayBuffer(file);
  };

  return (
    <div className="flex h-screen bg-[#f8fafc] text-[#1e293b] rtl overflow-hidden">
      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 right-0 z-[100] w-72 bg-white border-l border-slate-100 flex flex-col transition-all duration-300 transform ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'} shadow-2xl lg:shadow-none`}>
        <div className="p-8">
           <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-200">
                 <ShieldCheck size={24} />
              </div>
              <h1 className="text-xl font-black tracking-tight">بصمتي <span className="text-blue-600">برو</span></h1>
           </div>
        </div>

        <nav className="flex-1 px-4 space-y-2 mt-4">
          <NavItem icon={<LayoutDashboard size={18}/>} label="لوحة التحكم" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <NavItem icon={<Users size={18}/>} label="سجل الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
          <NavItem icon={<BrainCircuit size={18}/>} label="المدقق الذكي" active={currentView === 'ai'} onClick={() => { setCurrentView('ai'); setIsSidebarOpen(false); }} />
        </nav>

        {/* AI Performance Monitor */}
        <div className="mx-4 mb-6 p-5 bg-slate-900 text-white rounded-[2rem] shadow-xl relative overflow-hidden group">
           <div className="flex items-center justify-between mb-4 relative z-10">
              <div className="flex items-center gap-2">
                 <Cpu size={16} className="text-blue-400" />
                 <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">نظام AI</span>
              </div>
              <div className={`px-2 py-0.5 rounded-full text-[8px] font-black flex items-center gap-1 ${aiStatus === 'locked' ? 'bg-rose-500/20 text-rose-400' : 'bg-emerald-500/20 text-emerald-400'}`}>
                 <div className={`w-1 h-1 rounded-full ${aiStatus === 'locked' ? 'bg-rose-400' : 'bg-emerald-400'}`}></div>
                 {aiStatus === 'locked' ? 'معطل' : 'جاهز'}
              </div>
           </div>

           <div className="space-y-3 relative z-10">
              <div className="flex justify-between text-[10px] font-bold">
                 <span className="text-slate-400">الاستهلاك</span>
                 <span className="text-blue-400">{sessionTokens} / 100K</span>
              </div>
              <div className="h-1.5 w-full bg-slate-800 rounded-full overflow-hidden">
                 <div className="h-full bg-blue-500" style={{ width: `${Math.min((sessionTokens / 100000) * 100, 100)}%` }}></div>
              </div>
           </div>
        </div>

        <div className="p-6 pt-0 space-y-3">
           <label className="flex items-center justify-center gap-3 w-full py-4 bg-blue-600 text-white rounded-2xl cursor-pointer hover:bg-blue-700 transition-all font-black text-xs shadow-lg active:scale-95">
              <FileUp size={18} /> رفع Excel
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
           </label>
           {aiStatus === 'locked' && (
             <button onClick={handleOpenKeySelector} className="flex items-center justify-center gap-3 w-full py-4 bg-rose-50 text-rose-600 rounded-2xl font-black text-xs hover:bg-rose-100 transition-all active:scale-95">
                <Key size={18} /> تفعيل الذكاء الاصطناعي
             </button>
           )}
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative bg-white lg:rounded-r-[3rem] lg:my-4 lg:ml-4 shadow-sm border border-slate-100">
        <header className="h-20 px-6 lg:px-10 flex items-center justify-between shrink-0 bg-white/80 backdrop-blur-md z-40">
          <div className="flex items-center gap-4 flex-1">
             <button className="lg:hidden p-2 bg-slate-100 rounded-xl" onClick={() => setIsSidebarOpen(true)}>
               <Menu size={20} />
             </button>
             <div className="relative max-w-lg w-full">
                <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  type="text" 
                  placeholder="بحث..." 
                  className="w-full bg-slate-50 border-none rounded-2xl pr-12 pl-4 py-3 text-xs font-black focus:ring-2 focus:ring-blue-500/10"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
             </div>
          </div>
          <button 
             onClick={handleAiAudit} 
             disabled={employees.length === 0 || aiStatus === 'busy'} 
             className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-[11px] font-black transition-all shadow-md active:scale-95 ${aiStatus === 'busy' ? 'bg-slate-100 text-slate-400' : 'bg-slate-900 text-white hover:bg-blue-600'}`}
          >
             {aiStatus === 'busy' ? <RefreshCcw size={14} className="animate-spin" /> : <BrainCircuit size={14} />}
             <span>بدء التدقيق الذكي</span>
          </button>
        </header>

        <div className="flex-1 overflow-y-auto px-6 lg:px-10 pb-10 bento-scroll">
          {currentView === 'dashboard' && employees.length > 0 && (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-5 pt-8">
               {filteredEmployees.map((emp, idx) => (
                 <BentoEmployeeCard key={emp.id} employee={emp} index={idx} onAuditUpdate={(tokens) => setSessionTokens(prev => prev + tokens)} onKeyNeeded={handleOpenKeySelector} />
               ))}
            </div>
          )}

          {currentView === 'ai' && (
             <div className="max-w-4xl mx-auto py-10 animate-in">
                <div className="bg-white border border-slate-100 p-10 shadow-2xl rounded-[3rem]">
                   <h2 className="text-2xl font-black mb-6 flex items-center gap-3">
                      <BrainCircuit size={28} className="text-blue-600" /> تقرير الفحص الشامل
                   </h2>
                   <div className="bg-slate-50 p-8 rounded-[2rem] whitespace-pre-line text-sm font-bold leading-relaxed border border-slate-100 shadow-inner max-h-[60vh] overflow-y-auto bento-scroll">
                      {isAnalyzing ? "جاري تحليل البيانات عبر سحابة Gemini..." : bulkReport || "بانتظار بدء التحليل..."}
                   </div>
                </div>
             </div>
          )}

          {employees.length === 0 && <BentoEmptyState handleFileUpload={handleFileUpload} isAnalyzing={isAnalyzing} />}
        </div>
      </main>
    </div>
  );
};

/* --- Sub-Components --- */

const NavItem = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl text-[11px] font-black transition-all ${active ? 'bg-blue-50 text-blue-600 border border-blue-100' : 'text-slate-400 hover:bg-slate-50'}`}>
    {icon} <span>{label}</span>
  </button>
);

interface BentoEmployeeCardProps {
  employee: EmployeeSummary;
  index: number;
  onAuditUpdate: (tokens: number) => void;
  onKeyNeeded: () => void;
}

const BentoEmployeeCard: React.FC<BentoEmployeeCardProps> = ({ employee, index, onAuditUpdate, onKeyNeeded }) => {
  const [showModal, setShowModal] = useState(false);
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const isComplete = employee.isEligible;

  const handleAiAudit = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (loading) return;
    setLoading(true);
    try {
      const report = await generateDetailedAuditSummaryAI(employee);
      setAiReport(report.text);
      onAuditUpdate(report.tokens);
    } catch (err: any) {
      if (err.message === "API_KEY_MISSING") onKeyNeeded();
      else setAiReport("⚠️ تعذر الاتصال.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <div 
        onClick={() => setShowModal(true)} 
        className={`p-6 rounded-[2.5rem] cursor-pointer flex flex-col gap-4 min-h-[220px] transition-all hover:-translate-y-2 group border border-slate-50 ${isComplete ? 'bg-emerald-50/50 hover:bg-emerald-50' : 'bg-rose-50/50 hover:bg-rose-50'}`}
      >
        <div className="flex items-start justify-between">
           <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center font-black text-xl shadow-sm">
             {employee.name.charAt(0)}
           </div>
           <div className={`px-3 py-1 rounded-lg text-[9px] font-black ${isComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
              {isComplete ? 'مكتمل' : 'ناقص'}
           </div>
        </div>
        <div>
           <h3 className="text-sm font-black truncate">{employee.name}</h3>
           <p className="text-[10px] font-bold text-slate-400 mt-1">ACNo: {employee.id}</p>
        </div>
        <div className="mt-auto flex items-center justify-between">
           <span className="text-xs font-black">{employee.totalPunches} بصمة</span>
           <button onClick={handleAiAudit} className="w-9 h-9 bg-white rounded-xl flex items-center justify-center text-slate-400 hover:bg-slate-900 hover:text-white transition-all shadow-sm border border-slate-100">
              {loading ? <RefreshCcw size={14} className="animate-spin" /> : <BrainCircuit size={16} />}
           </button>
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-slate-900/60 backdrop-blur-xl animate-in">
           <div className="bg-white w-full max-w-5xl h-[85vh] rounded-[3rem] overflow-hidden flex flex-col shadow-2xl">
              <div className="p-8 border-b border-slate-50 flex items-center justify-between bg-slate-50/30">
                 <h2 className="text-xl font-black">{employee.name}</h2>
                 <button onClick={() => setShowModal(false)} className="w-10 h-10 bg-white rounded-xl flex items-center justify-center hover:bg-rose-50 hover:text-rose-500">
                    <X size={20} />
                 </button>
              </div>
              <div className="flex-1 flex overflow-hidden">
                 <div className="w-1/3 p-8 bg-slate-50/50 border-l border-slate-100 flex flex-col gap-6">
                    <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm text-center">
                       <p className="text-[10px] font-black uppercase opacity-50 mb-1">الانضباط</p>
                       <p className="text-4xl font-black">{employee.completionRate}%</p>
                    </div>
                    <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm flex-1 overflow-y-auto bento-scroll">
                       <h4 className="text-[10px] font-black mb-4 flex items-center gap-2">
                         <BrainCircuit size={14} className="text-blue-500" /> ملاحظات الذكاء الاصطناعي
                       </h4>
                       <p className="text-[11px] font-bold text-slate-600 leading-relaxed italic whitespace-pre-line">
                          {loading ? "جاري الفحص..." : aiReport || "اضغط على زر الدماغ للتحليل."}
                       </p>
                    </div>
                 </div>
                 <div className="flex-1 p-8 overflow-y-auto bento-scroll">
                    <h4 className="font-black mb-6">تفاصيل سجل الدوام</h4>
                    <div className="space-y-4">
                       {employee.shifts.map((s, i) => (
                         <div key={i} className={`p-5 rounded-[2rem] border ${s.status === 'مكتملة' ? 'bg-emerald-50/10 border-emerald-100' : 'bg-rose-50/10 border-rose-100'}`}>
                            <p className="text-xs font-black mb-4">{s.shift_date}</p>
                            <div className="grid grid-cols-5 gap-2">
                               {["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"].map(p => {
                                 const punch = s.punches_details.find(pd => pd.period === p && !pd.is_duplicate);
                                 return (
                                   <div key={p} className={`p-2 rounded-xl border text-center ${punch ? 'bg-white border-blue-100' : 'bg-slate-50 opacity-40'}`}>
                                      <p className="text-[7px] font-black opacity-40">{p}</p>
                                      <p className="text-[9px] font-black">{punch ? punch.time : '--:--'}</p>
                                   </div>
                                 );
                               })}
                            </div>
                         </div>
                       ))}
                    </div>
                 </div>
              </div>
           </div>
        </div>
      )}
    </>
  );
};

const BentoEmptyState = ({ handleFileUpload, isAnalyzing }: any) => (
  <div className="h-full flex flex-col items-center justify-center text-center p-12">
     <div className="w-20 h-20 bg-blue-600 text-white rounded-3xl flex items-center justify-center shadow-xl mb-6">
        {isAnalyzing ? <RefreshCcw size={32} className="animate-spin" /> : <Fingerprint size={32} />}
     </div>
     <h3 className="text-3xl font-black mb-3">بصمتي برو</h3>
     <p className="text-sm text-slate-400 font-bold max-w-xs mb-8">يرجى رفع ملف البصمة لبدء عملية التدقيق والتحليل الذكي.</p>
     <label className="px-8 py-4 bg-slate-900 text-white rounded-2xl font-black cursor-pointer shadow-lg hover:bg-blue-600 transition-all flex items-center gap-3 text-xs">
        <FileUp size={18} /> رفع ملف Excel
        <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
     </label>
  </div>
);

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Fingerprint, RefreshCcw, 
  X, AlertCircle, Sunrise, Sun, Sunset, Moon, 
  LogOut as LogOutIcon, ShieldCheck, UserCheck, Clock,
  Zap, Download, FileWarning, Cpu, Key, Info, Activity,
  AlertTriangle, ExternalLink
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary } from './types';

type ViewType = 'dashboard' | 'employees' | 'ai';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [showKeyError, setShowKeyError] = useState(false);

  // AI State
  const [aiStatus, setAiStatus] = useState<'idle' | 'busy' | 'error' | 'locked'>('idle');
  const [sessionTokens, setSessionTokens] = useState(0);
  const [hasApiKey, setHasApiKey] = useState<boolean | null>(null);

  // حساب الإحصائيات
  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
      deficientEmployees: employees.filter(e => !e.isEligible).length
    };
  }, [employees]);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      if (typeof window !== 'undefined' && window.aistudio) {
        // @ts-ignore
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(selected);
        if (!selected) setAiStatus('locked');
      } else {
        const keyExists = !!(typeof process !== 'undefined' && process.env?.API_KEY);
        setHasApiKey(keyExists);
        if (!keyExists) setAiStatus('locked');
      }
    };
    checkKey();
  }, []);

  const handleOpenKeySelector = async () => {
    // @ts-ignore
    if (typeof window !== 'undefined' && window.aistudio) {
      // @ts-ignore
      await window.aistudio.openSelectKey();
      setHasApiKey(true);
      setAiStatus('idle');
      setShowKeyError(false);
    } else {
      setShowKeyError(true);
    }
  };

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleAiAudit = async () => {
    if (employees.length === 0) return;

    setIsAnalyzing(true);
    setAiStatus('busy');
    setCurrentView('ai');
    setShowKeyError(false);

    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result.text);
      setSessionTokens(prev => prev + result.tokens);
      setAiStatus('idle');
    } catch (e: any) { 
      console.error(e);
      if (e.message?.includes("API_KEY_MISSING") || e.message?.includes("not found")) {
        setHasApiKey(false);
        setAiStatus('locked');
        setShowKeyError(true);
      } else {
        setAiStatus('error');
      }
    } finally { 
      setIsAnalyzing(false); 
    }
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
        const json = XLSX.utils.sheet_to_json(firstSheet);
        const processed = processExcelData(json);
        setEmployees(processed);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في قراءة ملف Excel.");
      } finally {
        setIsAnalyzing(false);
        event.target.value = '';
      }
    };
    reader.readAsArrayBuffer(file);
  };

  return (
    <div className="flex h-screen bg-[#f8fafc] text-[#1e293b] rtl overflow-hidden">
      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 right-0 z-[100] w-72 bg-white border-l border-slate-100 flex flex-col transition-all duration-300 transform ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'} shadow-2xl lg:shadow-none`}>
        <div className="p-8">
           <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-200">
                 <ShieldCheck size={24} />
              </div>
              <h1 className="text-xl font-black tracking-tight">بصمتي <span className="text-blue-600">برو</span></h1>
           </div>
        </div>

        <nav className="flex-1 px-4 space-y-2 mt-4">
          <NavItem icon={<LayoutDashboard size={18}/>} label="لوحة التحكم" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <NavItem icon={<Users size={18}/>} label="سجل الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
          <NavItem icon={<BrainCircuit size={18}/>} label="المدقق الذكي" active={currentView === 'ai'} onClick={() => { setCurrentView('ai'); setIsSidebarOpen(false); }} />
        </nav>

        {/* AI Monitor */}
        <div className="mx-4 mb-6 p-5 bg-slate-900 text-white rounded-[2rem] shadow-xl relative overflow-hidden group">
           <div className="flex items-center justify-between mb-4 relative z-10">
              <div className="flex items-center gap-2">
                 <Cpu size={16} className="text-blue-400" />
                 <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">حالة AI</span>
              </div>
              <div className={`px-2 py-0.5 rounded-full text-[8px] font-black flex items-center gap-1 ${aiStatus === 'locked' ? 'bg-rose-500/20 text-rose-400' : 'bg-emerald-500/20 text-emerald-400'}`}>
                 <div className={`w-1 h-1 rounded-full ${aiStatus === 'locked' ? 'bg-rose-400' : 'bg-emerald-400'}`}></div>
                 {aiStatus === 'locked' ? 'مفتاح مفقود' : 'جاهز'}
              </div>
           </div>

           <div className="space-y-3 relative z-10">
              <div className="flex justify-between text-[10px] font-bold">
                 <span className="text-slate-400">الاستهلاك</span>
                 <span className="text-blue-400">{sessionTokens} / 100K</span>
              </div>
              <div className="h-1.5 w-full bg-slate-800 rounded-full overflow-hidden">
                 <div className="h-full bg-blue-500 transition-all duration-700" style={{ width: `${Math.min((sessionTokens / 100000) * 100, 100)}%` }}></div>
              </div>
           </div>
        </div>

        <div className="p-6 pt-0 space-y-3">
           <label className="flex items-center justify-center gap-3 w-full py-4 bg-blue-600 text-white rounded-2xl cursor-pointer hover:bg-blue-700 transition-all font-black text-xs shadow-lg active:scale-95">
              <FileUp size={18} /> رفع ملف البصمة
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
           </label>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative bg-white lg:rounded-r-[3rem] lg:my-4 lg:ml-4 shadow-sm border border-slate-100">
        <header className="h-20 px-6 lg:px-10 flex items-center justify-between shrink-0 bg-white/80 backdrop-blur-md z-40 border-b border-slate-50">
          <div className="flex items-center gap-4 flex-1">
             <button className="lg:hidden p-2 bg-slate-100 rounded-xl" onClick={() => setIsSidebarOpen(true)}>
               <Menu size={20} />
             </button>
             <div className="relative max-w-lg w-full">
                <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  type="text" 
                  placeholder="بحث سريع عن موظف..." 
                  className="w-full bg-slate-50 border-none rounded-2xl pr-12 pl-4 py-3 text-xs font-black focus:ring-2 focus:ring-blue-500/10"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
             </div>
          </div>
          <button 
             onClick={handleAiAudit} 
             disabled={employees.length === 0 || aiStatus === 'busy'} 
             className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-[11px] font-black transition-all shadow-md active:scale-95 ${aiStatus === 'busy' ? 'bg-slate-100 text-slate-400' : 'bg-slate-900 text-white hover:bg-blue-600'}`}
          >
             {aiStatus === 'busy' ? <RefreshCcw size={14} className="animate-spin" /> : <BrainCircuit size={14} />}
             <span className="hidden sm:inline">تحليل شامل</span>
          </button>
        </header>

        <div className="flex-1 overflow-y-auto px-6 lg:px-10 pb-10 bento-scroll">
          {currentView === 'dashboard' && employees.length > 0 && stats && (
            <div className="pt-8 space-y-8 animate-in">
               {/* Stats Grid */}
               <div className="grid grid-cols-2 md:grid-cols-4 gap-5">
                  <BentoStat title="إجمالي الموظفين" value={stats.totalEmployees} icon={<Users size={20}/>} color="bg-blue-50 text-blue-600" />
                  <BentoStat title="نسبة الانضباط" value={`${stats.completionRate}%`} icon={<UserCheck size={20}/>} color="bg-emerald-50 text-emerald-600" />
                  <BentoStat title="إجمالي البصمات" value={stats.totalPunches} icon={<Fingerprint size={20}/>} color="bg-purple-50 text-purple-600" />
                  <BentoStat title="سجلات ناقصة" value={stats.deficientEmployees} icon={<AlertTriangle size={20}/>} color="bg-rose-50 text-rose-600" />
               </div>

               <div className="flex items-center justify-between px-2">
                 <h2 className="text-xl font-black">قائمة الموظفين</h2>
                 <div className="text-[10px] font-bold text-slate-400 bg-slate-50 px-3 py-1 rounded-lg border border-slate-100">
                    جاري عرض {filteredEmployees.length} نتيجة
                 </div>
               </div>

               <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-5">
                  {filteredEmployees.map((emp, idx) => (
                    <BentoEmployeeCard key={emp.id} employee={emp} index={idx} onAuditUpdate={(tokens) => setSessionTokens(prev => prev + tokens)} onKeyNeeded={handleOpenKeySelector} />
                  ))}
               </div>
            </div>
          )}

          {currentView === 'ai' && (
             <div className="max-w-4xl mx-auto py-10 animate-in">
                {showKeyError ? (
                  <AiKeyErrorBox onRetry={handleAiAudit} onHowTo={handleOpenKeySelector} />
                ) : (
                  <div className="bg-white border border-slate-100 p-10 shadow-2xl rounded-[3rem]">
                    <div className="flex items-center justify-between mb-8">
                       <h2 className="text-2xl font-black flex items-center gap-3">
                          <BrainCircuit size={28} className="text-blue-600" /> تقرير الفحص الذكي
                       </h2>
                       {isAnalyzing && <RefreshCcw size={20} className="animate-spin text-blue-600" />}
                    </div>
                    <div className="bg-slate-50 p-8 rounded-[2rem] whitespace-pre-line text-sm font-bold leading-relaxed border border-slate-100 shadow-inner max-h-[60vh] overflow-y-auto bento-scroll">
                       {isAnalyzing ? "جاري قراءة البيانات وتحليل النوبات عبر Gemini Cloud..." : bulkReport || "يرجى الضغط على زر التحليل لبدء المعالجة."}
                    </div>
                  </div>
                )}
             </div>
          )}

          {employees.length === 0 && <BentoEmptyState handleFileUpload={handleFileUpload} isAnalyzing={isAnalyzing} />}
        </div>
      </main>
    </div>
  );
};

/* --- Sub-Components --- */

const NavItem = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl text-[11px] font-black transition-all ${active ? 'bg-blue-50 text-blue-600 border border-blue-100 shadow-sm' : 'text-slate-400 hover:bg-slate-50'}`}>
    {icon} <span>{label}</span>
  </button>
);

const BentoStat = ({ title, value, icon, color }: any) => (
  <div className={`p-6 rounded-[2.2rem] ${color} flex flex-col justify-between min-h-[140px] shadow-sm border border-black/5 hover:scale-[1.02] transition-transform`}>
     <div className="flex justify-between items-center">
        <div className="p-2 bg-white/60 rounded-xl shadow-sm">{icon}</div>
        <span className="text-[9px] font-black uppercase opacity-60 tracking-wider">{title}</span>
     </div>
     <h4 className="text-3xl font-black mt-4">{value}</h4>
  </div>
);

const AiKeyErrorBox = ({ onRetry, onHowTo }: any) => (
  <div className="bg-white p-12 rounded-[3rem] border border-rose-100 shadow-2xl text-center space-y-6">
    <div className="w-20 h-20 bg-rose-50 text-rose-500 rounded-3xl flex items-center justify-center mx-auto shadow-sm">
       <Key size={40} />
    </div>
    <div>
      <h3 className="text-2xl font-black text-slate-900">مفتاح الذكاء الاصطناعي مفقود</h3>
      <p className="text-sm text-slate-500 font-bold max-w-sm mx-auto mt-2">
        يبدو أن النظام غير قادر على الوصول إلى Gemini API. يرجى التأكد من إضافة المفتاح في إعدادات Netlify.
      </p>
    </div>
    <div className="flex flex-col sm:flex-row items-center justify-center gap-4 pt-4">
      <button onClick={onRetry} className="px-8 py-3 bg-slate-900 text-white rounded-xl font-black text-xs hover:bg-blue-600 transition-all flex items-center gap-2">
        <RefreshCcw size={16} /> إعادة المحاولة
      </button>
      <button onClick={onHowTo} className="px-8 py-3 bg-rose-50 text-rose-600 rounded-xl font-black text-xs hover:bg-rose-100 transition-all flex items-center gap-2 border border-rose-100">
        <Info size={16} /> كيفية تفعيل النظام؟
      </button>
    </div>
    <div className="pt-4 text-[10px] font-bold text-slate-400 flex items-center justify-center gap-2">
      <ShieldCheck size={12} /> نظام بصمتي برو آمن ومشفر بالكامل
    </div>
  </div>
);

interface BentoEmployeeCardProps {
  employee: EmployeeSummary;
  index: number;
  onAuditUpdate: (tokens: number) => void;
  onKeyNeeded: () => void;
}

const BentoEmployeeCard: React.FC<BentoEmployeeCardProps> = ({ employee, index, onAuditUpdate, onKeyNeeded }) => {
  const [showModal, setShowModal] = useState(false);
  const [aiReport, setAiReport] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(false);
  const isComplete = employee.isEligible;

  const handleAiAudit = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (loading) return;
    setLoading(true);
    setError(false);
    try {
      const report = await generateDetailedAuditSummaryAI(employee);
      setAiReport(report.text);
      onAuditUpdate(report.tokens);
    } catch (err: any) {
      if (err.message === "API_KEY_MISSING") {
        onKeyNeeded();
        setError(true);
      } else {
        setAiReport("⚠️ تعذر الاتصال بالسحابة.");
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <div 
        onClick={() => setShowModal(true)} 
        className={`p-6 rounded-[2.5rem] cursor-pointer flex flex-col gap-4 min-h-[220px] transition-all hover:-translate-y-2 group border border-slate-50 ${isComplete ? 'bg-emerald-50/50 hover:bg-emerald-50' : 'bg-rose-50/50 hover:bg-rose-50'}`}
      >
        <div className="flex items-start justify-between">
           <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center font-black text-xl shadow-sm border border-slate-100">
             {employee.name.charAt(0)}
           </div>
           <div className={`px-3 py-1 rounded-lg text-[9px] font-black ${isComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
              {isComplete ? 'مكتمل' : 'ناقص'}
           </div>
        </div>
        <div>
           <h3 className="text-sm font-black truncate">{employee.name}</h3>
           <p className="text-[10px] font-bold text-slate-400 mt-1 uppercase tracking-tighter">ID: {employee.id}</p>
        </div>
        <div className="mt-auto flex items-center justify-between">
           <div className="flex items-center gap-1.5 text-xs font-black">
              <Fingerprint size={14} className="text-blue-500" />
              <span>{employee.totalPunches} بصمة</span>
           </div>
           <button onClick={handleAiAudit} className={`w-9 h-9 bg-white rounded-xl flex items-center justify-center transition-all shadow-sm border ${error ? 'border-rose-200 text-rose-500' : 'border-slate-100 text-slate-400 hover:bg-slate-900 hover:text-white'}`}>
              {loading ? <RefreshCcw size={14} className="animate-spin" /> : error ? <AlertCircle size={16} /> : <BrainCircuit size={16} />}
           </button>
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-slate-900/70 backdrop-blur-xl animate-in">
           <div className="bg-white w-full max-w-5xl h-[85vh] rounded-[3.5rem] overflow-hidden flex flex-col shadow-2xl relative">
              <div className="p-8 border-b border-slate-50 flex items-center justify-between bg-slate-50/30">
                 <div className="flex items-center gap-4">
                    <div className="w-14 h-14 bg-slate-900 text-white rounded-2xl flex items-center justify-center font-black text-2xl">
                       {employee.name.charAt(0)}
                    </div>
                    <div>
                       <h2 className="text-xl font-black">{employee.name}</h2>
                       <p className="text-[10px] font-bold text-slate-400">سجل تدقيق الموظف لعام 2024</p>
                    </div>
                 </div>
                 <button onClick={() => setShowModal(false)} className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center border border-slate-100 hover:bg-rose-50 hover:text-rose-500 transition-colors shadow-sm">
                    <X size={22} />
                 </button>
              </div>
              <div className="flex-1 flex overflow-hidden">
                 <div className="w-1/3 p-8 bg-slate-50/50 border-l border-slate-100 flex flex-col gap-6">
                    <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm text-center">
                       <p className="text-[10px] font-black uppercase opacity-40 mb-1 tracking-widest">نسبة الانضباط</p>
                       <p className="text-5xl font-black text-blue-600">{employee.completionRate}%</p>
                    </div>
                    <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm flex-1 overflow-y-auto bento-scroll flex flex-col">
                       <h4 className="text-[10px] font-black mb-4 flex items-center gap-2 uppercase text-slate-400 tracking-wider">
                         <BrainCircuit size={14} className="text-blue-500" /> تحليل المدقق الذكي
                       </h4>
                       <div className="text-[11px] font-bold text-slate-600 leading-relaxed italic whitespace-pre-line bg-slate-50 p-4 rounded-2xl border border-slate-100">
                          {loading ? "جاري استشارة الذكاء الاصطناعي..." : aiReport || (error ? "⚠️ المفتاح مفقود - يرجى تفعيل النظام من لوحة التحكم." : "اضغط على زر الدماغ في البطاقة للتحليل.")}
                       </div>
                       {!aiReport && !loading && (
                         <button onClick={handleAiAudit} className="mt-4 w-full py-3 bg-slate-900 text-white rounded-xl text-[10px] font-black hover:bg-blue-600 transition-all">توليد تقرير الآن</button>
                       )}
                    </div>
                 </div>
                 <div className="flex-1 p-10 overflow-y-auto bento-scroll">
                    <div className="flex items-center justify-between mb-8">
                       <h4 className="font-black text-lg">سجل تفاصيل النوبات</h4>
                       <div className="flex items-center gap-2">
                          <div className="w-3 h-3 rounded-full bg-emerald-500"></div>
                          <span className="text-[10px] font-bold text-slate-400">مكتملة</span>
                          <div className="w-3 h-3 rounded-full bg-rose-500 ml-2"></div>
                          <span className="text-[10px] font-bold text-slate-400">ناقصة</span>
                       </div>
                    </div>
                    <div className="space-y-5">
                       {employee.shifts.map((s, i) => (
                         <div key={i} className={`p-6 rounded-[2.5rem] border ${s.status === 'مكتملة' ? 'bg-emerald-50/10 border-emerald-100' : 'bg-rose-50/10 border-rose-100'}`}>
                            <div className="flex justify-between items-center mb-5">
                               <p className="text-sm font-black flex items-center gap-2">
                                  <Calendar size={16} className="text-slate-300" /> {s.shift_date}
                               </p>
                               <span className={`text-[8px] font-black px-3 py-1 rounded-lg ${s.status === 'مكتملة' ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>
                                  {s.status}
                               </span>
                            </div>
                            <div className="grid grid-cols-5 gap-3">
                               {["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"].map(p => {
                                 const punch = s.punches_details.find(pd => pd.period === p && !pd.is_duplicate);
                                 return (
                                   <div key={p} className={`p-3 rounded-2xl border text-center transition-all ${punch ? 'bg-white border-blue-100 shadow-sm' : 'bg-slate-50 border-transparent opacity-30 grayscale'}`}>
                                      <div className="mb-2 flex justify-center text-blue-500">{getMiniIcon(p)}</div>
                                      <p className="text-[7px] font-black opacity-40 uppercase tracking-tighter mb-1">{p}</p>
                                      <p className="text-[10px] font-black">{punch ? punch.time : '--:--'}</p>
                                   </div>
                                 );
                               })}
                            </div>
                         </div>
                       ))}
                    </div>
                 </div>
              </div>
           </div>
        </div>
      )}
    </>
  );
};

const getMiniIcon = (period: string) => {
  const s = 14;
  switch (period) {
    case 'دخول صباحي': return <Sunrise size={s} />;
    case 'بصمة وسطية': return <Sun size={s} />;
    case 'بصمة مسائية': return <Sunset size={s} />;
    case 'بصمة ليلية': return <Moon size={s} />;
    case 'بصمة خروج': return <LogOutIcon size={s} />;
    default: return <Clock size={s} />;
  }
};

