        {isAnalyzing ? <RefreshCcw size={48} className="animate-spin" /> : <Fingerprint size={48} />}
     </div>
     <h3 className="text-4xl font-black mb-4 tracking-tighter">بصمتي برو</h3>
     <p className="text-sm text-slate-400 font-bold max-w-sm mb-10 leading-relaxed px-4">أهلاً بك في نظام التدقيق المتقدم. يرجى رفع ملف البصمات (Excel) لبدء التحليل الفوري للموظفين.</p>
     <label className="px-12 py-5 bg-slate-900 text-white rounded-[2rem] font-black cursor-pointer shadow-2xl hover:bg-blue-600 transition-all flex items-center gap-4 active:scale-95">
        <FileUp size={24} /> <span>اختر ملف Excel</span>
        <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
     </label>
     <div className="mt-12 flex items-center gap-8 text-slate-300 opacity-50">
        <ShieldCheck size={32} />
        <Activity size={32} />
        <Cpu size={32} />
     </div>
  </div>
);

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Fingerprint, RefreshCcw, 
  X, AlertCircle, Sunrise, Sun, Sunset, Moon, 
  LogOut as LogOutIcon, ShieldCheck, UserCheck, Clock,
  Zap, Download, FileWarning, Cpu, Key, Info, Activity,
  AlertTriangle, CheckCircle2, FilterX
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary } from './types';

type ViewType = 'dashboard' | 'employees' | 'ai';
type FilterType = 'all' | 'eligible' | 'deficient';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState<FilterType>('all');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [showKeyError, setShowKeyError] = useState(false);

  // AI State
  const [aiStatus, setAiStatus] = useState<'idle' | 'busy' | 'error' | 'locked'>('idle');
  const [sessionTokens, setSessionTokens] = useState(0);
  const [hasApiKey, setHasApiKey] = useState<boolean | null>(null);

  // حساب الإحصائيات
  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalEmployees = employees.length;
    const eligibleCount = employees.filter(e => e.isEligible).length;
    const deficientCount = employees.filter(e => !e.isEligible).length;
    const totalPunches = employees.reduce((sum, e) => sum + e.totalPunches, 0);

    return {
      totalEmployees,
      eligibleCount,
      deficientCount,
      totalPunches,
      completionRate: Math.round((eligibleCount / (totalEmployees || 1)) * 100)
    };
  }, [employees]);

  useEffect(() => {
    const checkKey = async () => {
      // @ts-ignore
      if (typeof window !== 'undefined' && window.aistudio) {
        // @ts-ignore
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(selected);
        if (!selected) setAiStatus('locked');
      } else {
        const keyExists = !!(typeof process !== 'undefined' && process.env?.API_KEY);
        setHasApiKey(keyExists);
        if (!keyExists) setAiStatus('locked');
      }
    };
    checkKey();
  }, []);

  const handleOpenKeySelector = async () => {
    // @ts-ignore
    if (typeof window !== 'undefined' && window.aistudio) {
      // @ts-ignore
      await window.aistudio.openSelectKey();
      setHasApiKey(true);
      setAiStatus('idle');
      setShowKeyError(false);
    } else {
      setShowKeyError(true);
    }
  };

  const filteredEmployees = useMemo(() => {
    let result = employees;

    // الفلترة حسب الحالة (مكتمل/ناقص)
    if (filterType === 'eligible') {
      result = result.filter(e => e.isEligible);
    } else if (filterType === 'deficient') {
      result = result.filter(e => !e.isEligible);
    }

    // البحث النصي
    const term = searchTerm.toLowerCase();
    if (term) {
      result = result.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
    }

    return result;
  }, [employees, searchTerm, filterType]);

  const handleAiAudit = async () => {
    if (employees.length === 0) return;

    setIsAnalyzing(true);
    setAiStatus('busy');
    setCurrentView('ai');
    setShowKeyError(false);

    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result.text);
      setSessionTokens(prev => prev + result.tokens);
      setAiStatus('idle');
    } catch (e: any) { 
      console.error(e);
      if (e.message?.includes("API_KEY_MISSING") || e.message?.includes("not found")) {
        setHasApiKey(false);
        setAiStatus('locked');
        setShowKeyError(true);
      } else {
        setAiStatus('error');
      }
    } finally { 
      setIsAnalyzing(false); 
    }
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
        const json = XLSX.utils.sheet_to_json(firstSheet);
        const processed = processExcelData(json);
        setEmployees(processed);
        setCurrentView('dashboard');
        setFilterType('all');
      } catch (err) {
        alert("خطأ في قراءة ملف Excel.");
      } finally {
        setIsAnalyzing(false);
        event.target.value = '';
      }
    };
    reader.readAsArrayBuffer(file);
  };

  return (
    <div className="flex h-screen bg-[#f8fafc] text-[#1e293b] rtl overflow-hidden">
      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 right-0 z-[100] w-72 bg-white border-l border-slate-100 flex flex-col transition-all duration-300 transform ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'} shadow-2xl lg:shadow-none`}>
        <div className="p-8">
           <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg shadow-blue-200">
                 <ShieldCheck size={24} />
              </div>
              <h1 className="text-xl font-black tracking-tight">بصمتي <span className="text-blue-600">برو</span></h1>
           </div>
        </div>

        <nav className="flex-1 px-4 space-y-2 mt-4">
          <NavItem icon={<LayoutDashboard size={18}/>} label="لوحة التحكم" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <NavItem icon={<Users size={18}/>} label="سجل الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
          <NavItem icon={<BrainCircuit size={18}/>} label="المدقق الذكي" active={currentView === 'ai'} onClick={() => { setCurrentView('ai'); setIsSidebarOpen(false); }} />
        </nav>

        {/* AI Monitor */}
        <div className="mx-4 mb-6 p-5 bg-slate-900 text-white rounded-[2rem] shadow-xl relative overflow-hidden group">
           <div className="flex items-center justify-between mb-4 relative z-10">
              <div className="flex items-center gap-2">
                 <Cpu size={16} className="text-blue-400" />
                 <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">حالة AI</span>
              </div>
              <div className={`px-2 py-0.5 rounded-full text-[8px] font-black flex items-center gap-1 ${aiStatus === 'locked' ? 'bg-rose-500/20 text-rose-400' : 'bg-emerald-500/20 text-emerald-400'}`}>
                 <div className={`w-1 h-1 rounded-full ${aiStatus === 'locked' ? 'bg-rose-400' : 'bg-emerald-400'}`}></div>
                 {aiStatus === 'locked' ? 'مفتاح مفقود' : 'متصل'}
              </div>
           </div>

           <div className="space-y-3 relative z-10">
              <div className="flex justify-between text-[10px] font-bold">
                 <span className="text-slate-400">الاستهلاك</span>
                 <span className="text-blue-400">{sessionTokens} / 100K</span>
              </div>
              <div className="h-1.5 w-full bg-slate-800 rounded-full overflow-hidden">
                 <div className="h-full bg-blue-500 transition-all duration-700" style={{ width: `${Math.min((sessionTokens / 100000) * 100, 100)}%` }}></div>
              </div>
           </div>
        </div>

        <div className="p-6 pt-0 space-y-3">
           <label className="flex items-center justify-center gap-3 w-full py-4 bg-blue-600 text-white rounded-2xl cursor-pointer hover:bg-blue-700 transition-all font-black text-xs shadow-lg active:scale-95">
              <FileUp size={18} /> رفع ملف البصمة
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
           </label>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative bg-white lg:rounded-r-[3rem] lg:my-4 lg:ml-4 shadow-sm border border-slate-100">
        <header className="h-20 px-6 lg:px-10 flex items-center justify-between shrink-0 bg-white/80 backdrop-blur-md z-40 border-b border-slate-50">
          <div className="flex items-center gap-4 flex-1">
             <button className="lg:hidden p-2 bg-slate-100 rounded-xl" onClick={() => setIsSidebarOpen(true)}>
               <Menu size={20} />
             </button>
             <div className="relative max-w-lg w-full">
                <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input 
                  type="text" 
                  placeholder="بحث سريع عن اسم أو رقم..." 
                  className="w-full bg-slate-50 border-none rounded-2xl pr-12 pl-4 py-3 text-xs font-black focus:ring-2 focus:ring-blue-500/10"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
             </div>
          </div>
          <button 
             onClick={handleAiAudit} 
             disabled={employees.length === 0 || aiStatus === 'busy'} 
             className={`flex items-center gap-2 px-6 py-2.5 rounded-xl text-[11px] font-black transition-all shadow-md active:scale-95 ${aiStatus === 'busy' ? 'bg-slate-100 text-slate-400' : 'bg-slate-900 text-white hover:bg-blue-600'}`}
          >
             {aiStatus === 'busy' ? <RefreshCcw size={14} className="animate-spin" /> : <BrainCircuit size={14} />}
             <span className="hidden sm:inline">تحليل شامل</span>
          </button>
        </header>

        <div className="flex-1 overflow-y-auto px-6 lg:px-10 pb-10 bento-scroll">
          {currentView === 'dashboard' && employees.length > 0 && stats && (
            <div className="pt-8 space-y-8 animate-in">
               {/* Pastel Interactive Stats Grid */}
               <div className="grid grid-cols-2 md:grid-cols-4 gap-5">
                  <BentoStat 
                    title="إجمالي الموظفين" 
                    value={stats.totalEmployees} 
                    icon={<Users size={22}/>} 
                    color="bg-[#E0F2FE]" 
                    textColor="text-sky-700"
                    active={filterType === 'all'}
                    onClick={() => setFilterType('all')}
                  />
                  <BentoStat 
                    title="المكتملة بصماتهم" 
                    value={stats.eligibleCount} 
                    icon={<CheckCircle2 size={22}/>} 
                    color="bg-[#DCFCE7]" 
                    textColor="text-emerald-700"
                    active={filterType === 'eligible'}
                    onClick={() => setFilterType('eligible')}
                  />
                  <BentoStat 
                    title="نواقص البصمة" 
                    value={stats.deficientCount} 
                    icon={<AlertTriangle size={22}/>} 
                    color="bg-[#FCE7F3]" 
                    textColor="text-rose-700"
                    active={filterType === 'deficient'}
                    onClick={() => setFilterType('deficient')}
                  />
                  <BentoStat 
                    title="إجمالي البصمات" 
                    value={stats.totalPunches} 
                    icon={<Fingerprint size={22}/>} 
                    color="bg-[#F3E8FF]" 
                    textColor="text-purple-700"
                    active={false}
                    onClick={() => {}} // لا فلترة هنا
                  />
               </div>

               <div className="flex items-center justify-between px-2">
                 <div className="flex items-center gap-4">
                    <h2 className="text-xl font-black">
                      {filterType === 'all' && "كافة الموظفين"}
                      {filterType === 'eligible' && "الموظفون المنضبطون"}
                      {filterType === 'deficient' && "الموظفون ذوي النواقص"}
                    </h2>
                    {filterType !== 'all' && (
                      <button 
                        onClick={() => setFilterType('all')}
                        className="flex items-center gap-1 text-[10px] font-black text-blue-600 bg-blue-50 px-3 py-1 rounded-full border border-blue-100 hover:bg-blue-100 transition-colors"
                      >
                        <FilterX size={12} /> إلغاء الفلترة
                      </button>
                    )}
                 </div>
                 <div className="text-[10px] font-bold text-slate-400 bg-slate-50 px-3 py-1 rounded-lg border border-slate-100">
                    عرض {filteredEmployees.length} من أصل {employees.length}
                 </div>
               </div>

               {filteredEmployees.length > 0 ? (
                 <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-5">
                    {filteredEmployees.map((emp, idx) => (
                      <BentoEmployeeCard key={emp.id} employee={emp} index={idx} onAuditUpdate={(tokens) => setSessionTokens(prev => prev + tokens)} onKeyNeeded={handleOpenKeySelector} />
                    ))}
                 </div>
               ) : (
                 <div className="py-20 text-center bg-slate-50 rounded-[3rem] border border-dashed border-slate-200">
                    <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center mx-auto mb-4 text-slate-300 shadow-sm">
                       <Search size={32} />
                    </div>
                    <p className="text-sm font-black text-slate-400">لا توجد نتائج تطابق بحثك أو الفلتر المختار.</p>
                 </div>
               )}
            </div>
          )}

          {currentView === 'ai' && (
             <div className="max-w-4xl mx-auto py-10 animate-in">
                {showKeyError ? (
                  <AiKeyErrorBox onRetry={handleAiAudit} onHowTo={handleOpenKeySelector} />
                ) : (
                  <div className="bg-white border border-slate-100 p-10 shadow-2xl rounded-[3rem]">
                    <div className="flex items-center justify-between mb-8">
                       <h2 className="text-2xl font-black flex items-center gap-3">
                          <BrainCircuit size={28} className="text-blue-600" /> تقرير الفحص الذكي
                       </h2>
                       {isAnalyzing && <RefreshCcw size={20} className="animate-spin text-blue-600" />}
                    </div>
                    <div className="bg-slate-50 p-8 rounded-[2rem] whitespace-pre-line text-sm font-bold leading-relaxed border border-slate-100 shadow-inner max-h-[60vh] overflow-y-auto bento-scroll">
                       {isAnalyzing ? "جاري قراءة البيانات وتحليل النوبات عبر Gemini Cloud..." : bulkReport || "يرجى الضغط على زر التحليل لبدء المعالجة."}
                    </div>
                  </div>
                )}
             </div>
          )}

          {employees.length === 0 && <BentoEmptyState handleFileUpload={handleFileUpload} isAnalyzing={isAnalyzing} />}
        </div>
      </main>
    </div>
  );
};

