import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary } from "../types";

/**
 * دالة إنشاء العميل باستخدام المفتاح المدمج في النظام
 */
const getAiClient = () => {
  // استخدام المفتاح مباشرة من البيئة البرمجية
  const apiKey = process.env.API_KEY;
  if (!apiKey) throw new Error("API_KEY_MISSING");
  return new GoogleGenAI({ apiKey });
};

export const generateDetailedAuditSummaryAI = async (employee: EmployeeSummary): Promise<{ text: string; tokens: number }> => {
  try {
    const ai = getAiClient();

    const missingData = employee.shifts
      .filter(s => s.status === 'ناقصة')
      .map(s => {
        const missing = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
          .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate));
        return `${s.shift_date}: (${missing.join(', ')})`;
      });

    if (missingData.length === 0) return { text: "✅ السجل التقني مكتمل تماماً لهذا الموظف.", tokens: 0 };

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `بصفتك مدقق حضور وانصراف، حلل النواقص التالية للموظف (${employee.name}):\n${missingData.join('\n')}\nالرد بالعربية، موجز جداً وتقني.`,
      config: { temperature: 0.2 }
    });

    const text = response.text || "لا توجد ملاحظات تحليلية.";
    return { text, tokens: text.length };
  } catch (error) {
    console.error("Audit Error:", error);
    throw error;
  }
};

export const generateBulkAuditSummaryAI = async (employees: EmployeeSummary[]): Promise<{ text: string; tokens: number }> => {
  try {
    const ai = getAiClient();

    const problematic = employees
      .filter(e => !e.isEligible)
      .slice(0, 20)
      .map(e => `- ${e.name} (رقم:${e.id}): نقص في ${e.shifts.filter(s => s.status === 'ناقصة').length} أيام.`);

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `قدم ملخصاً إدارياً عن حالات عدم الانضباط التالية:\n${problematic.join('\n')}\nالرد بالعربية في نقاط مختصرة.`,
      config: { temperature: 0.2 }
    });

    const text = response.text || "فشل التحليل الإجمالي.";
    return { text, tokens: text.length };
  } catch (error) {
    console.error("Bulk Error:", error);
    throw error;
  }
};

