               <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-6">
                  {filteredEmployees.map((emp) => (
                    <EmployeeCard key={emp.id} employee={emp} />
                  ))}
               </div>
            </div>
          )}

          {currentView === 'ai' && (
            <div className="max-w-4xl mx-auto py-12 animate-in">
               <div className="bg-white rounded-[3.5rem] p-12 shadow-2xl shadow-blue-500/5 border border-slate-50 relative overflow-hidden">
                  <div className="flex items-center justify-between mb-10 relative z-10">
                     <h2 className="text-3xl font-black flex items-center gap-4">
                        <Sparkles size={32} className="text-blue-600" /> التحليل الإداري الذكي
                     </h2>
                     {isAnalyzing && <RefreshCcw size={24} className="animate-spin text-blue-600" />}
                  </div>
                  <div className="bg-[#F8FAFC] p-10 rounded-[2.5rem] border border-slate-100 shadow-inner min-h-[400px]">
                     <p className="text-sm font-bold text-slate-600 leading-[1.8] whitespace-pre-line">
                        {isAnalyzing ? "جاري استشارة الذكاء الاصطناعي وتحليل أنماط الحضور..." : bulkReport || "يرجى رفع ملف البصمة أولاً ثم طلب التقرير."}
                     </p>
                  </div>
                  <div className="absolute top-0 right-0 w-64 h-64 bg-blue-50 rounded-full blur-[100px] opacity-50 -mr-32 -mt-32"></div>
               </div>
            </div>
          )}

          {employees.length === 0 && <EmptyState handleFileUpload={handleFileUpload} isAnalyzing={isAnalyzing} />}
        </div>
      </main>
    </div>
  );
};

