                       {!report && !loading && (
                         <button onClick={handleAiAudit} className="mt-8 w-full py-4 bg-slate-900 text-white rounded-2xl text-[10px] font-black hover:bg-blue-600 transition-all shadow-lg flex items-center justify-center gap-2">
                            <BrainCircuit size={16} /> طلب تحليل فوري
                         </button>
                       )}
                    </div>
                 </div>
                 <div className="flex-1 p-12 overflow-y-auto bento-scroll bg-white">
                    <div className="grid gap-8">
                       {employee.shifts.map((s, i) => (
