                               <span className={`text-[9px] font-black px-4 py-1.5 rounded-xl shadow-sm ${s.status === 'مكتملة' ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
                                  {s.status}
                               </span>
                            </div>
                            <div className="grid grid-cols-5 gap-4">
                               {["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"].map(period => {
                                 const punch = s.punches_details.find(pd => pd.period === period && !pd.is_duplicate);
                                 return (
                                   <div key={period} className={`p-4 rounded-[1.8rem] border text-center transition-all ${punch ? 'bg-white border-blue-100 shadow-md scale-105' : 'bg-slate-50 border-transparent opacity-20 grayscale'}`}>
                                      <div className="mb-2 text-blue-500 flex justify-center">{getPeriodIcon(period)}</div>
                                      <p className="text-[8px] font-black opacity-40 uppercase tracking-tighter mb-1 truncate">{period}</p>
                                      <p className="text-xs font-black">{punch ? punch.time : '--:--'}</p>
                                   </div>
                                 );
                               })}
                            </div>
                         </div>
                       ))}
                    </div>
                 </div>
              </div>
           </div>
        </div>
      )}
    </>
  );
};

const getPeriodIcon = (period: string) => {
  const size = 18;
  switch (period) {
    case 'دخول صباحي': return <Sunrise size={size} />;
    case 'بصمة وسطية': return <Sun size={size} />;
    case 'بصمة مسائية': return <Sunset size={size} />;
    case 'بصمة ليلية': return <Moon size={size} />;
    case 'بصمة خروج': return <LogOutIcon size={size} />;
    default: return <Clock size={size} />;
  }
};

const EmptyState = ({ handleFileUpload, isAnalyzing }: any) => (
  <div className="h-full flex flex-col items-center justify-center text-center p-12">
     <div className="w-28 h-28 bg-blue-600 text-white rounded-[3rem] flex items-center justify-center shadow-2xl mb-10 relative">
        <div className="absolute inset-0 bg-blue-400 rounded-[3rem] animate-ping opacity-20"></div>
        {isAnalyzing ? <RefreshCcw size={54} className="animate-spin" /> : <Fingerprint size={54} />}
     </div>
     <h3 className="text-4xl font-black mb-4 tracking-tight">بصمتي برو: التدقيق الفني</h3>
     <p className="text-sm text-slate-400 font-bold max-w-sm mb-12 leading-relaxed">يرجى رفع ملف Excel المستخرج من أجهزة البصمة لبدء عملية المراجعة الذكية وتحديد الثغرات في النوبات.</p>
     <label className="px-14 py-6 bg-slate-900 text-white rounded-[2rem] font-black cursor-pointer shadow-2xl hover:bg-blue-600 transition-all flex items-center gap-4 active:scale-95 group">
        <FileUp size={28} className="group-hover:-translate-y-1 transition-transform" /> <span>اختر ملف الجداول</span>
        <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
     </label>
  </div>
);

export default App;

