  X, AlertCircle, ShieldCheck, CheckCircle2, 
  AlertTriangle, FilterX, Sparkles, Activity,
  Sunrise, Sun, Sunset, Moon, LogOut as LogOutIcon, Clock,
  FileSpreadsheet, FileDown
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary } from './types';

type ViewType = 'dashboard' | 'ai';
type FilterType = 'all' | 'eligible' | 'deficient';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState<FilterType>('all');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [bulkReport, setBulkReport] = useState<string | null>(null);

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const total = employees.length;
    const eligible = employees.filter(e => e.isEligible).length;
    const deficient = total - eligible;
    const punches = employees.reduce((sum, e) => sum + e.totalPunches, 0);
    return { total, eligible, deficient, punches };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    let result = employees;
    if (filterType === 'eligible') result = result.filter(e => e.isEligible);
    else if (filterType === 'deficient') result = result.filter(e => !e.isEligible);

    const term = searchTerm.toLowerCase();
    if (term) {
      result = result.filter(e => 
        e.name.toLowerCase().includes(term) || 
        String(e.id).includes(term)
      );
    }
    return result;
  }, [employees, searchTerm, filterType]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setCurrentView('dashboard');
        setFilterType('all');
      } catch (err) {
        alert("خطأ في قراءة ملف Excel");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleExportToExcel = () => {
    if (employees.length === 0) return;

    // تجهيز بيانات الملخص العام
    const summaryData = employees.map(emp => ({
      'الرقم الوظيفي': emp.id,
      'الاسم الكامل': emp.name,
      'إجمالي الأيام': emp.shifts.length,
      'أيام مكتملة': emp.shifts.filter(s => s.status === 'مكتملة').length,
      'أيام ناقصة': emp.shifts.filter(s => s.status === 'ناقصة').length,
      'نسبة الالتزام': `${emp.completionRate}%`,
      'الوضعية': emp.isEligible ? 'مكتمل الضوابط' : 'بانتظار استكمال النواقص'
    }));

    // تجهيز بيانات النواقص التفصيلية مع التواريخ والبصمات المفقودة
    const deficiencyData: any[] = [];
    employees.forEach(emp => {
      emp.shifts.filter(s => s.status === 'ناقصة').forEach(shift => {
        const found = shift.punches_details.filter(p => !p.is_duplicate).map(p => p.period);
        const allPossible = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
        const missing = allPossible.filter(p => !found.includes(p));

        deficiencyData.push({
          'الرقم الوظيفي': emp.id,
          'اسم الموظف': emp.name,
          'تاريخ النوبة': shift.shift_date,
          'اليوم': new Date(shift.shift_date).toLocaleDateString('ar-EG', { weekday: 'long' }),
          'البصمات الناقصة': missing.join(' | '),
          'البصمات المسجلة': found.join(' | '),
          'الحالة الفنية': 'نقص في السجل'
        });
      });
    });

    const workbook = XLSX.utils.book_new();
    const summarySheet = XLSX.utils.json_to_sheet(summaryData);
    const detailSheet = XLSX.utils.json_to_sheet(deficiencyData);

    XLSX.utils.book_append_sheet(workbook, summarySheet, "ملخص الموظفين");
    XLSX.utils.book_append_sheet(workbook, detailSheet, "سجل النواقص اليومي");

    const fileName = `تقرير_بصمتي_برو_${new Date().toLocaleDateString('en-GB').replace(/\//g, '-')}.xlsx`;
    XLSX.writeFile(workbook, fileName);
  };

  const runBulkAiAudit = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    setCurrentView('ai');
    try {
      const res = await generateBulkAuditSummaryAI(employees);
      setBulkReport(res.text);
    } catch (error) {
      setBulkReport("⚠️ تعذر الاتصال بمحرك الذكاء الاصطناعي.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="flex h-screen bg-[#FDFEFE] text-[#1E293B] rtl overflow-hidden font-['Cairo']">
      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 right-0 z-[100] w-72 bg-white border-l border-slate-50 flex flex-col transition-all duration-500 transform ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'}`}>
        <div className="p-8">
           <div className="flex items-center gap-3">
              <div className="w-11 h-11 bg-blue-600 rounded-2xl flex items-center justify-center text-white shadow-xl shadow-blue-100 ring-4 ring-blue-50">
                 <ShieldCheck size={26} />
              </div>
              <div>
                <h1 className="text-xl font-black leading-none">بصمتي <span className="text-blue-600">برو</span></h1>
                <p className="text-[9px] font-bold text-slate-400 mt-1 uppercase tracking-widest">محطة الخيرات الغازية</p>
              </div>
           </div>
        </div>

        <nav className="flex-1 px-4 space-y-2 mt-4">
          <NavItem icon={<LayoutDashboard size={18}/>} label="لوحة التحكم" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <NavItem icon={<BrainCircuit size={18}/>} label="المدقق الذكي" active={currentView === 'ai'} onClick={() => { setCurrentView('ai'); setIsSidebarOpen(false); }} />
        </nav>

        <div className="p-6 space-y-4">
           <div className="bg-slate-900 rounded-[2rem] p-5 text-white relative overflow-hidden group">
              <div className="relative z-10">
                 <div className="flex items-center gap-2 mb-2">
                    <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                    <span className="text-[10px] font-black text-slate-400 uppercase">نظام التحليل مفعل</span>
                 </div>
                 <p className="text-xs font-bold text-slate-300">يستخدم Gemini 3 Flash للتحليل.</p>
              </div>
              <Sparkles className="absolute -bottom-4 -left-4 text-blue-500/10 group-hover:scale-110 transition-transform duration-700" size={100} />
           </div>

           <label className="flex items-center justify-center gap-3 w-full py-4 bg-blue-600 text-white rounded-[1.8rem] cursor-pointer hover:bg-blue-700 transition-all font-black text-xs shadow-xl active:scale-95 group">
              <FileUp size={20} className="group-hover:-translate-y-1 transition-transform" /> 
              <span>استيراد ملف البصمة</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
           </label>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-[#F8FAFC] lg:rounded-r-[3.5rem] lg:my-3 lg:ml-3 border border-slate-100 shadow-sm overflow-hidden relative">
        <header className="h-20 px-8 flex items-center justify-between shrink-0 bg-white/60 backdrop-blur-xl z-40 border-b border-slate-100/50">
          <div className="flex items-center gap-4 flex-1">
             <button className="lg:hidden p-2 bg-white rounded-xl shadow-sm" onClick={() => setIsSidebarOpen(true)}>
               <Menu size={20} />
             </button>
             <div className="relative max-w-md w-full">
                <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                <input 
                  type="text" 
                  placeholder="ابحث بالاسم أو الرقم..." 
                  className="w-full bg-white border-none rounded-2xl pr-12 pl-4 py-3 text-xs font-bold focus:ring-4 focus:ring-blue-500/5 transition-all shadow-sm"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
             </div>
          </div>

          <div className="flex items-center gap-3">
            <button 
               onClick={handleExportToExcel}
               disabled={employees.length === 0}
               className="flex items-center gap-2.5 px-6 py-3 bg-emerald-600 text-white rounded-2xl text-[11px] font-black hover:bg-emerald-700 hover:shadow-emerald-200 transition-all shadow-lg shadow-emerald-100 active:scale-95 disabled:opacity-40 group"
               title="تصدير النتائج التفصيلية"
            >
               <FileSpreadsheet size={18} className="group-hover:rotate-6 transition-transform" />
               <span className="hidden sm:inline">تصدير التقارير (Excel)</span>
            </button>
            <button 
               onClick={runBulkAiAudit} 
               disabled={employees.length === 0 || isAnalyzing} 
               className="flex items-center gap-2 px-6 py-3 bg-slate-900 text-white rounded-2xl text-[11px] font-black hover:bg-blue-600 transition-all shadow-lg active:scale-95 disabled:opacity-50"
            >
               {isAnalyzing ? <RefreshCcw size={16} className="animate-spin" /> : <Activity size={16} />}
               <span className="hidden sm:inline">تحليل الكادر</span>
            </button>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto px-8 pb-10 bento-scroll">
          {employees.length > 0 && currentView === 'dashboard' && stats && (
            <div className="pt-8 space-y-10 animate-in">
               <div className="grid grid-cols-2 lg:grid-cols-4 gap-6">
                  <BentoStatCard 
                    title="إجمالي الموظفين" 
                    value={stats.total} 
                    icon={<Users size={24}/>} 
                    color="bg-[#E0F2FE]" 
                    textColor="text-sky-700"
                    active={filterType === 'all'}
                    onClick={() => setFilterType('all')}
                  />
                  <BentoStatCard 
                    title="سجلات مكتملة" 
                    value={stats.eligible} 
                    icon={<CheckCircle2 size={24}/>} 
                    color="bg-[#DCFCE7]" 
                    textColor="text-emerald-700"
                    active={filterType === 'eligible'}
                    onClick={() => setFilterType('eligible')}
                  />
                  <BentoStatCard 
                    title="سجلات ناقصة" 
                    value={stats.deficient} 
                    icon={<AlertTriangle size={24}/>} 
                    color="bg-[#FCE7F3]" 
                    textColor="text-rose-700"
                    active={filterType === 'deficient'}
                    onClick={() => setFilterType('deficient')}
                  />
                  <BentoStatCard 
                    title="نشاط البصمة" 
                    value={stats.punches} 
                    icon={<Fingerprint size={24}/>} 
                    color="bg-[#F3E8FF]" 
                    textColor="text-purple-700"
                    active={false}
                    onClick={() => {}}
                  />
               </div>

               <div className="flex items-center justify-between">
                 <div className="flex items-center gap-3">
                    <h2 className="text-2xl font-black tracking-tight text-slate-800">
                       {filterType === 'all' ? 'قاعدة البيانات المجمعة' : filterType === 'eligible' ? 'الموظفين المنضبطين' : 'الموظفين ذوي النواقص'}
                    </h2>
                    {filterType !== 'all' && (
                       <button onClick={() => setFilterType('all')} className="flex items-center gap-2 px-3 py-1 bg-blue-50 text-blue-600 rounded-xl hover:bg-blue-100 transition-colors font-black text-[10px]">
                          <FilterX size={14} /> إلغاء الفلترة
                       </button>
                    )}
                 </div>
                 <div className="text-[10px] font-black text-slate-400 bg-white px-4 py-2 rounded-2xl shadow-sm border border-slate-100">
                    تم تحليل {filteredEmployees.length} موظف
                 </div>
               </div>

               <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-6">
                  {filteredEmployees.map((emp) => (
                    <EmployeeCard key={emp.id} employee={emp} />
                  ))}
               </div>
            </div>
          )}

          {currentView === 'ai' && (
            <div className="max-w-4xl mx-auto py-12 animate-in">
               <div className="bg-white rounded-[3.5rem] p-12 shadow-2xl shadow-blue-500/5 border border-slate-100 relative overflow-hidden">
                  <div className="flex items-center justify-between mb-10 relative z-10">
                     <h2 className="text-3xl font-black flex items-center gap-4 text-slate-800">
                        <Sparkles size={32} className="text-blue-600" /> تقرير التحليل الإداري
                     </h2>
                  </div>
                  <div className="bg-[#F8FAFC] p-10 rounded-[2.5rem] border border-slate-100 shadow-inner min-h-[450px]">
                     {bulkReport ? (
                        <div className="text-sm font-bold text-slate-600 leading-[2.2] whitespace-pre-line animate-in">
                           {bulkReport}
                        </div>
                     ) : (
                        <div className="h-full flex flex-col items-center justify-center text-slate-300 gap-4">
                           <BrainCircuit size={60} strokeWidth={1} />
                           <p className="font-bold text-xs uppercase tracking-widest">انتظار طلب التحليل من القائمة العلوية</p>
                        </div>
                     )}
                  </div>
               </div>
            </div>
          )}

          {employees.length === 0 && <EmptyState handleFileUpload={handleFileUpload} isAnalyzing={isAnalyzing} />}
        </div>
      </main>
    </div>
  );
};

/* Components */

const NavItem = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl text-xs font-black transition-all duration-300 ${active ? 'bg-blue-50 text-blue-600 shadow-sm border border-blue-100' : 'text-slate-400 hover:bg-slate-50'}`}>
    {icon} <span>{label}</span>
  </button>
);

const BentoStatCard = ({ title, value, icon, color, textColor, active, onClick }: any) => (
  <div 
    onClick={onClick}
    className={`p-8 rounded-[2.8rem] ${color} ${textColor} flex flex-col justify-between min-h-[180px] cursor-pointer transition-all duration-500 relative overflow-hidden ${active ? 'ring-4 ring-offset-4 ring-blue-500 scale-[1.03] shadow-2xl z-10' : 'hover:scale-[1.01] shadow-sm'}`}
  >
     <div className="flex justify-between items-center relative z-10">
        <div className="w-12 h-12 bg-white/60 backdrop-blur-md rounded-2xl flex items-center justify-center shadow-sm border border-white/20">{icon}</div>
        <span className="text-[10px] font-black uppercase tracking-widest opacity-60">{title}</span>
     </div>
     <div className="relative z-10">
        <h4 className="text-5xl font-black mt-4 tracking-tighter">{value}</h4>
        {active && <div className="mt-2 text-[8px] font-black bg-white/50 px-3 py-1 rounded-full inline-block uppercase tracking-wider">عرض القائمة</div>}
     </div>
  </div>
);

const EmployeeCard = ({ employee }: { employee: EmployeeSummary }) => {
  const [showModal, setShowModal] = useState(false);
  const [report, setReport] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const isComplete = employee.isEligible;

  const handleAiAudit = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (loading) return;
    setLoading(true);
    try {
      const res = await generateDetailedAuditSummaryAI(employee);
      setReport(res.text);
    } catch (error) {
      setReport("⚠️ تعذر التحليل.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <div 
        onClick={() => setShowModal(true)} 
        className={`p-7 rounded-[2.8rem] cursor-pointer border border-slate-100 flex flex-col gap-6 hover:-translate-y-2 transition-all duration-500 group shadow-sm bg-white hover:shadow-xl ${!isComplete ? 'ring-1 ring-rose-100' : ''}`}
      >
        <div className="flex items-start justify-between">
           <div className={`w-14 h-14 rounded-[1.3rem] flex items-center justify-center font-black text-2xl shadow-sm border ${isComplete ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-rose-50 text-rose-600 border-rose-100'}`}>
             {employee.name.charAt(0)}
           </div>
           <div className={`px-4 py-1.5 rounded-xl text-[9px] font-black shadow-sm flex items-center gap-1.5 ${isComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
              {isComplete ? <CheckCircle2 size={12}/> : <AlertTriangle size={12}/>}
              {isComplete ? 'مكتمل' : 'نواقص'}
           </div>
        </div>
        <div>
           <h3 className="text-base font-black truncate text-slate-800">{employee.name}</h3>
           <p className="text-[10px] font-bold text-slate-400 mt-1 uppercase tracking-tight">المعرف: {employee.id}</p>
        </div>
        <div className="mt-auto flex items-center justify-between pt-5 border-t border-slate-50">
           <div className="flex items-center gap-2 text-xs font-black text-slate-600">
              <Fingerprint size={16} className="text-blue-500" />
              <span>{employee.totalPunches} بصمة</span>
           </div>
           <button 
             onClick={handleAiAudit}
             className="w-10 h-10 bg-slate-50 rounded-2xl flex items-center justify-center border border-slate-100 text-slate-400 hover:bg-slate-900 hover:text-white transition-all shadow-sm"
           >
              {loading ? <RefreshCcw size={16} className="animate-spin" /> : <BrainCircuit size={18} />}
           </button>
        </div>
      </div>

      {showModal && (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-slate-900/60 backdrop-blur-xl animate-in">
           <div className="bg-white w-full max-w-6xl h-[90vh] rounded-[3.5rem] overflow-hidden flex flex-col shadow-2xl">
              <div className="p-8 border-b border-slate-50 flex items-center justify-between bg-white/50">
                 <div className="flex items-center gap-5">
                    <div className="w-16 h-16 bg-slate-900 text-white rounded-[1.5rem] flex items-center justify-center font-black text-3xl">
                       {employee.name.charAt(0)}
                    </div>
                    <div>
                       <h2 className="text-2xl font-black">{employee.name}</h2>
                       <p className="text-[11px] font-bold text-slate-400">تدقيق سجلات الحضور اليومية</p>
                    </div>
                 </div>
                 <button onClick={() => setShowModal(false)} className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center border border-slate-100 hover:bg-rose-50 hover:text-rose-500 transition-all">
                    <X size={24} />
                 </button>
              </div>
              <div className="flex-1 flex overflow-hidden">
                 <div className="w-1/3 p-10 bg-[#F8FAFC] border-l border-slate-100 overflow-y-auto bento-scroll space-y-8">
                    <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm text-center">
                       <p className="text-[10px] font-black uppercase opacity-40 mb-2">معدل الانضباط</p>
                       <p className="text-6xl font-black text-blue-600">{employee.completionRate}%</p>
                    </div>
                    <div className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm relative overflow-hidden group">
                       <h4 className="text-[10px] font-black mb-6 flex items-center gap-2 uppercase text-slate-400">
                         <Sparkles size={16} className="text-blue-500" /> تحليل السلوك
                       </h4>
                       <div className="text-[12px] font-bold text-slate-600 leading-relaxed italic whitespace-pre-line">
                          {loading ? "جاري الاستقصاء..." : report || "لم يتم إجراء تحليل ذكي لهذا السجل حتى الآن."}
                       </div>
                    </div>
                 </div>
                 <div className="flex-1 p-12 overflow-y-auto bento-scroll bg-white">
                    <div className="grid gap-8">
                       {employee.shifts.map((s, i) => (
                         <div key={i} className={`p-8 rounded-[3rem] border transition-all ${s.status === 'مكتملة' ? 'bg-[#DCFCE7]/10 border-emerald-100' : 'bg-[#FCE7F3]/10 border-rose-100'}`}>
                            <div className="flex justify-between items-center mb-8">
                               <p className="text-base font-black flex items-center gap-3 text-slate-700">
                                  <Calendar size={20} className="text-slate-300" /> {s.shift_date}
                               </p>
                               <span className={`text-[9px] font-black px-4 py-1.5 rounded-xl ${s.status === 'مكتملة' ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
                                  {s.status}
                               </span>
                            </div>
                            <div className="grid grid-cols-5 gap-4">
                               {["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"].map(period => {
                                 const punch = s.punches_details.find(pd => pd.period === period && !pd.is_duplicate);
                                 return (
                                   <div key={period} className={`p-4 rounded-[1.8rem] border text-center ${punch ? 'bg-white border-blue-100 shadow-sm' : 'bg-slate-50 border-transparent opacity-20'}`}>
                                      <div className="mb-2 text-blue-500 flex justify-center">{getPeriodIcon(period)}</div>
                                      <p className="text-[8px] font-black opacity-40 uppercase truncate mb-1">{period}</p>
                                      <p className="text-xs font-black">{punch ? punch.time : '--:--'}</p>
                                   </div>
                                 );
                               })}
                            </div>
                         </div>
                       ))}
                    </div>
                 </div>
              </div>
           </div>
        </div>
      )}
    </>
  );
};

const getPeriodIcon = (period: string) => {
  const size = 18;
  switch (period) {
    case 'دخول صباحي': return <Sunrise size={size} />;
    case 'بصمة وسطية': return <Sun size={size} />;
    case 'بصمة مسائية': return <Sunset size={size} />;
    case 'بصمة ليلية': return <Moon size={size} />;
    case 'بصمة خروج': return <LogOutIcon size={size} />;
    default: return <Clock size={size} />;
  }
};

const EmptyState = ({ handleFileUpload, isAnalyzing }: any) => (
  <div className="h-full flex flex-col items-center justify-center text-center p-12">
     <div className="w-28 h-28 bg-blue-600 text-white rounded-[3rem] flex items-center justify-center shadow-2xl mb-10 relative">
        <div className="absolute inset-0 bg-blue-400 rounded-[3rem] animate-ping opacity-20"></div>
        {isAnalyzing ? <RefreshCcw size={54} className="animate-spin" /> : <Fingerprint size={54} />}
     </div>
     <h3 className="text-4xl font-black mb-4 tracking-tight">نظام بصمتي برو المتطور</h3>
     <p className="text-sm text-slate-400 font-bold max-w-sm mb-12 leading-relaxed">يرجى رفع ملف Excel المستخرج من أجهزة البصمة لبدء الفحص والتدقيق الآلي.</p>
