import React, { useState, useMemo, useEffect } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Fingerprint, RefreshCcw, 
  X, AlertCircle, ShieldCheck, CheckCircle2, 
  AlertTriangle, FilterX, Sparkles, Activity,
  Sunrise, Sun, Sunset, Moon, LogOut as LogOutIcon, Clock,
  FileSpreadsheet, ShieldAlert, Zap, Info
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary } from './types';

type ViewType = 'dashboard' | 'ai';
type FilterType = 'all' | 'eligible' | 'deficient';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState<FilterType>('all');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [aiStatus, setAiStatus] = useState<'ready' | 'checking' | 'error'>('ready');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const total = employees.length;
    const eligible = employees.filter(e => e.isEligible).length;
    const deficient = total - eligible;
    const punches = employees.reduce((sum, e) => sum + e.totalPunches, 0);
    return { total, eligible, deficient, punches };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    let result = employees;
    if (filterType === 'eligible') result = result.filter(e => e.isEligible);
    else if (filterType === 'deficient') result = result.filter(e => !e.isEligible);

    const term = searchTerm.toLowerCase();
    if (term) {
      result = result.filter(e => 
        e.name.toLowerCase().includes(term) || 
        String(e.id).includes(term)
      );
    }
    return result;
  }, [employees, searchTerm, filterType]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setCurrentView('dashboard');
        setFilterType('all');
      } catch (err) {
        alert("خطأ في قراءة ملف Excel");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleExportToExcel = () => {
    if (employees.length === 0) return;

    // 1. ورقة الملخص (Summary Sheet)
    const summaryData = employees.map(emp => ({
      'المعرف': emp.id,
      'الاسم': emp.name,
      'إجمالي الأيام': emp.shifts.length,
      'نوبات مكتملة': emp.shifts.filter(s => s.status === 'مكتملة').length,
      'نوبات ناقصة': emp.shifts.filter(s => s.status === 'ناقصة').length,
      'معدل الانضباط': `${emp.completionRate}%`,
      'الحالة': emp.isEligible ? '✅ مكتمل' : '❌ يوجد نواقص'
    }));

    // 2. ورقة سجل النواقص (Deficiency Log)
    const deficiencyData: any[] = [];
    employees.filter(e => !e.isEligible).forEach(emp => {
      emp.shifts.filter(s => s.status === 'ناقصة').forEach(shift => {
        const found = shift.punches_details.filter(p => !p.is_duplicate).map(p => p.period);
        const allPossible = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
        const missing = allPossible.filter(p => !found.includes(p));

        deficiencyData.push({
          'التاريخ': shift.shift_date,
          'اليوم': new Date(shift.shift_date).toLocaleDateString('ar-EG', { weekday: 'long' }),
          'المعرف': emp.id,
          'الموظف': emp.name,
          'البصمات المفقودة': missing.join(' | '),
          'التفصيل': `يفتقد لعدد (${missing.length}) بصمات أساسية`
        });
      });
    });

    const workbook = XLSX.utils.book_new();
    const ws1 = XLSX.utils.json_to_sheet(summaryData);
    const ws2 = XLSX.utils.json_to_sheet(deficiencyData);

    XLSX.utils.book_append_sheet(workbook, ws1, "الملخص العام");
    XLSX.utils.book_append_sheet(workbook, ws2, "سجل النواقص التفصيلي");

    XLSX.writeFile(workbook, `تقرير_الانضباط_${new Date().toISOString().slice(0,10)}.xlsx`);
  };

  const runBulkAiAudit = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    setAiStatus('checking');
    try {
      const res = await generateBulkAuditSummaryAI(employees);
      setBulkReport(res.text);
      setAiStatus('ready');
    } catch (error) {
      setAiStatus('error');
      setBulkReport("⚠️ فشل الاتصال بالذكاء الاصطناعي. تأكد من إعداد API_KEY في إعدادات النشر.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="flex h-screen bg-[#F8FAFC] text-[#1E293B] rtl overflow-hidden font-['Cairo']">
      {/* Sidebar */}
      <aside className={`fixed lg:static inset-y-0 right-0 z-[100] w-80 bg-white border-l border-slate-100 flex flex-col transition-all duration-500 transform ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'}`}>
        <div className="p-10">
           <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-blue-600 rounded-[1.2rem] flex items-center justify-center text-white shadow-xl shadow-blue-200 ring-4 ring-blue-50">
                 <ShieldCheck size={28} />
              </div>
              <div>
                <h1 className="text-2xl font-black leading-none tracking-tight">بصمتي <span className="text-blue-600">برو</span></h1>
                <p className="text-[10px] font-bold text-slate-400 mt-1 uppercase tracking-widest">إدارة محطة الخيرات</p>
              </div>
           </div>
        </div>

        <nav className="flex-1 px-6 space-y-3">
          <NavItem icon={<LayoutDashboard size={20}/>} label="لوحة التحكم" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <NavItem icon={<BrainCircuit size={20}/>} label="المدقق الذكي" active={currentView === 'ai'} onClick={() => { setCurrentView('ai'); setIsSidebarOpen(false); }} />
        </nav>

        <div className="p-8 space-y-5">
           <div className={`rounded-[2.2rem] p-6 text-white relative overflow-hidden transition-colors duration-500 ${aiStatus === 'error' ? 'bg-rose-600' : 'bg-slate-900'}`}>
              <div className="relative z-10">
                 <div className="flex items-center gap-2 mb-3">
                    <div className={`w-2 h-2 rounded-full animate-pulse ${aiStatus === 'ready' ? 'bg-emerald-400' : 'bg-rose-400'}`}></div>
                    <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">
                       {aiStatus === 'error' ? 'خطأ في الربط' : 'نظام Gemini نشط'}
                    </span>
                 </div>
                 <p className="text-xs font-bold text-slate-300 leading-relaxed">
                   {aiStatus === 'error' ? 'يرجى مراجعة مفتاح API في إعدادات Netlify.' : 'الذكاء الاصطناعي جاهز لتحليل أنماط الدوام.'}
                 </p>
              </div>
              <Sparkles className="absolute -bottom-6 -left-6 text-white/5" size={120} />
           </div>

