import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary } from "../types";

const getAiInstance = () => {
  // استخدام مفتاح البيئة المعتمد في Netlify أو البيئة المحلية
  return new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
};

export const generateDetailedAuditSummaryAI = async (employee: EmployeeSummary): Promise<{ text: string }> => {
  try {
    const ai = getAiInstance();

    const missingDays = employee.shifts
      .filter(s => s.status === 'ناقصة')
      .map(s => {
        const found = s.punches_details.filter(p => !p.is_duplicate).map(p => p.period);
        const allPossible = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
        const missing = allPossible.filter(p => !found.includes(p));
        return `- يوم ${s.shift_date} (${new Date(s.shift_date).toLocaleDateString('ar-EG', {weekday: 'long'})}): نقص في (${missing.join('، ')})`;
      });

    if (missingDays.length === 0) return { text: "✅ السجل نظيف تماماً ولا توجد ملاحظات تقنية." };

    const prompt = `أنت مدقق موارد بشرية محترف. حلل سجل البصمات الناقصة للموظف (${employee.name}) واكتب تقريراً فنياً مختصراً جداً يوضح الخلل وتأثيره:\n${missingDays.join('\n')}`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return { text: response.text || "لا يمكن تحليل البيانات حالياً." };
  } catch (error) {
    console.error("AI Audit Error:", error);
    return { text: "⚠️ عذراً، لم يتمكن الذكاء الاصطناعي من معالجة الطلب. يرجى التأكد من إعداد API_KEY." };
  }
};

export const generateBulkAuditSummaryAI = async (employees: EmployeeSummary[]): Promise<{ text: string }> => {
  try {
    const ai = getAiInstance();
    const deficientEmployees = employees.filter(e => !e.isEligible);

    let deficiencyContext = deficientEmployees.map(e => {
       const missingInfo = e.shifts.filter(s => s.status === 'ناقصة').map(s => {
          const found = s.punches_details.filter(p => !p.is_duplicate).map(p => p.period);
          const allPossible = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
          return s.shift_date + ": " + allPossible.filter(p => !found.includes(p)).join(', ');
       }).join(' | ');
       return `- ${e.name} (معرف ${e.id}): ${missingInfo}`;
    }).join('\n');

    const prompt = `بصفتك مستشار إداري، قم بتحليل تقرير النواقص الجماعي التالي لكادر العمل:\n${deficiencyContext}\n\nالمطلوب: تقديم رؤية إدارية حول أكثر البصمات التي يتم نسيانها وتوصية عملية لتقليل هذه النواقص.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return { text: response.text || "فشل توليد التقرير الجماعي." };
  } catch (error) {
    return { text: "⚠️ خطأ في الاتصال بالمدقق الذكي." };
  }
};

