type ViewType = 'dashboard' | 'audit';
type FilterType = 'all' | 'eligible' | 'deficient';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState<FilterType>('all');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [bulkAiReport, setBulkAiReport] = useState<string | null>(null);

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const total = employees.length;
    const eligible = employees.filter(e => e.isEligible).length;
    const deficient = total - eligible;
    const totalPunches = employees.reduce((sum, e) => sum + e.totalPunches, 0);
    return { total, eligible, deficient, totalPunches };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    let result = employees;
    if (filterType === 'eligible') result = result.filter(e => e.isEligible);
    else if (filterType === 'deficient') result = result.filter(e => !e.isEligible);

    const term = searchTerm.toLowerCase();
    if (term) {
      result = result.filter(e => 
        e.name.toLowerCase().includes(term) || 
        String(e.id).includes(term)
      );
    }
    return result;
  }, [employees, searchTerm, filterType]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setCurrentView('dashboard');
        setFilterType('all');
      } catch (err) {
        alert("خطأ في قراءة ملف Excel");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleExportToExcel = () => {
    if (employees.length === 0) return;

    // 1. ورقة الملخص
    const summaryData = employees.map(emp => ({
      'المعرف': emp.id,
      'الاسم': emp.name,
      'إجمالي النوبات': emp.shifts.length,
      'النوبات المكتملة': emp.shifts.filter(s => s.status === 'مكتملة').length,
      'النوبات الناقصة': emp.shifts.filter(s => s.status === 'ناقصة').length,
      'نسبة الالتزام': `${emp.completionRate}%`,
      'الحالة النهائية': emp.isEligible ? 'منضبط' : 'يوجد نواقص'
    }));

    // 2. سجل النواقص التفصيلي مع التواريخ
    const deficiencyLogs: any[] = [];
    employees.forEach(emp => {
      emp.shifts.filter(s => s.status === 'ناقصة').forEach(shift => {
        const found = shift.punches_details.filter(p => !p.is_duplicate).map(p => p.period);
        const allPossible = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
        const missing = allPossible.filter(p => !found.includes(p));

        deficiencyLogs.push({
          'التاريخ': shift.shift_date,
          'اليوم': new Date(shift.shift_date).toLocaleDateString('ar-EG', { weekday: 'long' }),
          'رقم الموظف': emp.id,
          'اسم الموظف': emp.name,
          'البصمات الناقصة': missing.join(' - '),
          'البصمات الموجودة': found.join(' - ')
        });
      });
    });

    const workbook = XLSX.utils.book_new();
    const ws1 = XLSX.utils.json_to_sheet(summaryData);
    const ws2 = XLSX.utils.json_to_sheet(deficiencyLogs);

    XLSX.utils.book_append_sheet(workbook, ws1, "الملخص العام");
    XLSX.utils.book_append_sheet(workbook, ws2, "سجل النواقص الفني");

    XLSX.writeFile(workbook, `تقرير_بصمتي_التفصيلي_${new Date().toISOString().slice(0,10)}.xlsx`);
  };

  const runBulkAuditAnalysis = async () => {
    if (employees.length === 0) return;
    setCurrentView('audit');
    setIsAnalyzing(true);
    try {
      const res = await generateBulkAuditSummaryAI(employees);
      setBulkAiReport(res.text);
    } catch (e) {
      setBulkAiReport("⚠️ حدث خطأ أثناء الاتصال بالمدقق الذكي.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="flex h-screen bg-[#F8FAFC] text-[#1E293B] rtl overflow-hidden font-['Cairo']">
      {/* Sidebar - Bento Drawer */}
      <aside className={`fixed lg:static inset-y-0 right-0 z-[100] w-72 bg-white border-l border-slate-100 flex flex-col transition-all duration-500 transform ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'}`}>
        <div className="p-10">
           <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-blue-600 rounded-[1.4rem] flex items-center justify-center text-white shadow-xl shadow-blue-100">
                 <ShieldCheck size={28} />
              </div>
              <div>
                <h1 className="text-2xl font-black leading-none tracking-tight">بصمتي <span className="text-blue-600">برو</span></h1>
                <p className="text-[10px] font-bold text-slate-400 mt-1 uppercase tracking-widest">إدارة محطة الخيرات</p>
              </div>
           </div>
        </div>

        <nav className="flex-1 px-6 space-y-3">
          <NavItem icon={<LayoutDashboard size={20}/>} label="لوحة التحكم" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <NavItem icon={<ListChecks size={20}/>} label="تدقيق الكادر" active={currentView === 'audit'} onClick={() => { runBulkAuditAnalysis(); setIsSidebarOpen(false); }} />
        </nav>

        <div className="p-8 space-y-4">
           <div className="bg-slate-900 rounded-[2.5rem] p-6 text-white relative overflow-hidden group">
              <div className="relative z-10">
                 <div className="flex items-center gap-2 mb-2">
                    <div className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse"></div>
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">ذكاء اصطناعي نشط</span>
                 </div>
                 <p className="text-[11px] font-bold text-slate-300 leading-relaxed">نظام التدقيق جاهز لتحليل بصمات الكادر بالكامل.</p>
              </div>
              <Zap className="absolute -bottom-4 -left-4 text-blue-500/10 group-hover:scale-125 transition-transform duration-700" size={100} />
           </div>

           <label className="flex items-center justify-center gap-3 w-full py-5 bg-blue-600 text-white rounded-[1.8rem] cursor-pointer hover:bg-blue-700 transition-all font-black text-xs shadow-xl active:scale-95 group">
              <FileUp size={22} className="group-hover:-translate-y-1 transition-transform" /> 
              <span>استيراد بيانات جديدة</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
           </label>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-[#F8FAFC] lg:rounded-r-[3.5rem] lg:my-3 lg:ml-3 border border-slate-200/50 shadow-inner overflow-hidden relative">
        <header className="h-24 px-10 flex items-center justify-between shrink-0 bg-white/40 backdrop-blur-2xl z-40 border-b border-slate-100">
          <div className="flex items-center gap-6 flex-1">
             <button className="lg:hidden p-3 bg-white rounded-2xl shadow-sm border border-slate-100" onClick={() => setIsSidebarOpen(true)}>
               <Menu size={24} />
             </button>
             <div className="relative max-w-md w-full">
                <Search className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300" size={20} />
                <input 
                  type="text" 
                  placeholder="بحث سريع عن اسم أو رقم..." 
                  className="w-full bg-white border-none rounded-[1.4rem] pr-14 pl-6 py-4 text-xs font-bold focus:ring-4 focus:ring-blue-500/5 transition-all shadow-sm"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
             </div>
          </div>

          <div className="flex items-center gap-4">
            <button 
               onClick={handleExportToExcel}
               disabled={employees.length === 0}
               className="flex items-center gap-3 px-8 py-4 bg-emerald-600 text-white rounded-[1.4rem] text-[12px] font-black hover:bg-emerald-700 transition-all shadow-xl active:scale-95 disabled:opacity-40 group"
            >
               <FileSpreadsheet size={20} className="group-hover:rotate-12 transition-transform" />
               <span className="hidden md:inline">تصدير Excel الذكي</span>
            </button>
            <button 
               onClick={runBulkAuditAnalysis} 
               disabled={employees.length === 0 || isAnalyzing} 
               className="flex items-center gap-3 px-8 py-4 bg-slate-900 text-white rounded-[1.4rem] text-[12px] font-black hover:bg-blue-600 transition-all shadow-xl active:scale-95 disabled:opacity-50"
            >
               {isAnalyzing ? <RefreshCcw size={20} className="animate-spin" /> : <BrainCircuit size={20} />}
               <span className="hidden md:inline">تحليل الكادر</span>
            </button>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto px-10 pb-12 bento-scroll">
          {employees.length > 0 && currentView === 'dashboard' && stats && (
            <div className="pt-10 space-y-12 animate-in">
               <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
                  <BentoStatCard title="إجمالي الموظفين" value={stats.total} icon={<Users size={28}/>} color="bg-blue-50" textColor="text-blue-700" active={filterType === 'all'} onClick={() => setFilterType('all')} />
                  <BentoStatCard title="سجلات مكتملة" value={stats.eligible} icon={<CheckCircle2 size={28}/>} color="bg-emerald-50" textColor="text-emerald-700" active={filterType === 'eligible'} onClick={() => setFilterType('eligible')} />
                  <BentoStatCard title="سجلات ناقصة" value={stats.deficient} icon={<ShieldAlert size={28}/>} color="bg-rose-50" textColor="text-rose-700" active={filterType === 'deficient'} onClick={() => setFilterType('deficient')} />
                  <BentoStatCard title="إجمالي البصمات" value={stats.totalPunches} icon={<Fingerprint size={28}/>} color="bg-purple-50" textColor="text-purple-700" active={false} onClick={() => {}} />
               </div>

               <div className="flex items-center justify-between border-b border-slate-100 pb-6">
                 <h2 className="text-3xl font-black text-slate-800">قائمة الموظفين</h2>
                 <div className="flex gap-2">
                    <FilterButton label="الكل" active={filterType === 'all'} onClick={() => setFilterType('all')} />
                    <FilterButton label="مكتمل" active={filterType === 'eligible'} onClick={() => setFilterType('eligible')} />
                    <FilterButton label="ناقص" active={filterType === 'deficient'} onClick={() => setFilterType('deficient')} />
                 </div>
               </div>

               <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-8">
                  {filteredEmployees.map((emp) => (
                    <EmployeeCard key={emp.id} employee={emp} />
                  ))}
               </div>
            </div>
          )}

          {currentView === 'audit' && (
            <div className="pt-10 space-y-12 animate-in">
                <div className="flex items-center gap-4 mb-4">
                    <button onClick={() => setCurrentView('dashboard')} className="p-3 bg-white rounded-2xl shadow-sm border border-slate-100 hover:bg-slate-50 transition-all">
                        <ChevronLeft size={24} />
                    </button>
                    <h2 className="text-3xl font-black text-slate-800">منصة تدقيق الكادر</h2>
                </div>

                {/* AI Executive Insight */}
                <div className="bg-white rounded-[3rem] p-10 shadow-2xl border border-slate-100 relative overflow-hidden">
                   <div className="flex items-center gap-4 mb-8">
                      <div className="w-12 h-12 bg-blue-600 rounded-2xl flex items-center justify-center text-white">
                         <Sparkles size={24} />
                      </div>
                      <h3 className="text-xl font-black">رؤية المدقق الذكي (Gemini AI)</h3>
                   </div>
                   <div className="bg-[#F8FAFC] p-8 rounded-[2rem] text-sm font-bold text-slate-600 leading-loose whitespace-pre-line border border-slate-100">
                      {isAnalyzing ? "جاري تحليل البيانات الجماعية..." : bulkAiReport || "لا توجد بيانات للتحليل."}
                   </div>
                   <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 to-purple-500"></div>
                </div>

                {/* Detailed Deficiency Grid */}
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
                   {employees.filter(e => !e.isEligible).map(emp => (
                      <div key={emp.id} className="bg-white rounded-[2.5rem] p-8 border border-slate-100 shadow-sm hover:shadow-xl transition-all group">
                         <div className="flex justify-between items-center mb-6">
                            <div className="flex items-center gap-4">
                               <div className="w-12 h-12 bg-rose-50 text-rose-600 rounded-2xl flex items-center justify-center font-black text-xl border border-rose-100">
                                  {emp.name.charAt(0)}
                               </div>
                               <div>
                                  <h4 className="font-black text-slate-800">{emp.name}</h4>
                                  <p className="text-[10px] font-bold text-slate-400">معرف: {emp.id}</p>
                               </div>
                            </div>
                            <div className="bg-rose-500 text-white px-4 py-1.5 rounded-xl text-[9px] font-black">
                               {emp.shifts.filter(s => s.status === 'ناقصة').length} نوبات ناقصة
                            </div>
                         </div>
                         <div className="space-y-3">
                            {emp.shifts.filter(s => s.status === 'ناقصة').map((shift, idx) => {
                               const found = shift.punches_details.filter(p => !p.is_duplicate).map(p => p.period);
                               const allPossible = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
                               const missing = allPossible.filter(p => !found.includes(p));
                               return (
                                  <div key={idx} className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl border border-slate-100">
                                     <div className="flex items-center gap-3">
                                        <Calendar size={14} className="text-slate-400" />
                                        <span className="text-[11px] font-black">{shift.shift_date}</span>
                                     </div>
                                     <div className="flex flex-wrap gap-1 justify-end max-w-[200px]">
                                        {missing.map(m => (
                                           <span key={m} className="bg-rose-100 text-rose-700 px-2 py-0.5 rounded-lg text-[8px] font-black">نقص {m}</span>
                                        ))}
                                     </div>
                                  </div>
                               );
                            })}
                         </div>
                      </div>
                   ))}
                </div>
            </div>
          )}

          {employees.length === 0 && <EmptyState handleFileUpload={handleFileUpload} isAnalyzing={isAnalyzing} />}
        </div>
      </main>
    </div>
  );
};

/* Sub-components */

const NavItem = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-5 px-8 py-5 rounded-[1.4rem] text-[13px] font-black transition-all duration-400 ${active ? 'bg-blue-50 text-blue-600 shadow-sm border border-blue-100' : 'text-slate-400 hover:bg-slate-50'}`}>
    {icon} <span>{label}</span>
  </button>
);

const FilterButton = ({ label, active, onClick }: any) => (
  <button onClick={onClick} className={`px-5 py-2 rounded-xl text-[11px] font-black transition-all ${active ? 'bg-blue-600 text-white shadow-lg' : 'bg-white text-slate-400 border border-slate-100 hover:bg-slate-50'}`}>
    {label}
  </button>
);

const BentoStatCard = ({ title, value, icon, color, textColor, active, onClick }: any) => (
  <div 
    onClick={onClick}
    className={`p-10 rounded-[3rem] ${color} ${textColor} flex flex-col justify-between min-h-[220px] cursor-pointer transition-all duration-500 relative overflow-hidden ${active ? 'ring-4 ring-offset-4 ring-blue-500 scale-[1.03] shadow-2xl z-10' : 'hover:scale-[1.02] shadow-sm border border-transparent'}`}
  >
     <div className="flex justify-between items-center relative z-10">
        <div className="w-14 h-14 bg-white/80 backdrop-blur-md rounded-2xl flex items-center justify-center shadow-sm border border-white">{icon}</div>
        <span className="text-[11px] font-black uppercase tracking-widest opacity-60">{title}</span>
     </div>
     <div className="relative z-10">
        <h4 className="text-6xl font-black mt-6 tracking-tighter">{value}</h4>
        {active && <div className="mt-3 text-[10px] font-black bg-white/60 px-4 py-1.5 rounded-full inline-block uppercase tracking-widest">تصفية نشطة</div>}
     </div>
  </div>
);

