  return (
    <>
      <div 
        onClick={() => setShowModal(true)} 
        className={`p-8 rounded-[3.2rem] cursor-pointer border border-slate-100 flex flex-col gap-8 hover:-translate-y-2 transition-all duration-500 group shadow-sm bg-white hover:shadow-2xl hover:shadow-blue-500/10 ${!isComplete ? 'ring-2 ring-rose-50' : ''}`}
      >
        <div className="flex items-start justify-between">
           <div className={`w-16 h-16 rounded-[1.5rem] flex items-center justify-center font-black text-3xl shadow-sm border ${isComplete ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-rose-50 text-rose-600 border-rose-100'}`}>
             {employee.name.charAt(0)}
           </div>
           <div className={`px-5 py-2 rounded-2xl text-[10px] font-black shadow-sm flex items-center gap-2 ${isComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
              {isComplete ? <CheckCircle2 size={14}/> : <AlertTriangle size={14}/>}
              {isComplete ? 'مكتمل' : 'نواقص'}
           </div>
        </div>
        <div>
           <h3 className="text-lg font-black truncate text-slate-800">{employee.name}</h3>
           <p className="text-[11px] font-bold text-slate-400 mt-1 uppercase tracking-widest">رقم القيد: {employee.id}</p>
        </div>
        <div className="mt-auto flex items-center justify-between pt-6 border-t border-slate-50">
           <div className="flex items-center gap-3 text-xs font-black text-slate-600">
              <Fingerprint size={18} className="text-blue-500" />
              <span>{employee.totalPunches} بصمة</span>
           </div>
           <div className="w-10 h-10 bg-slate-50 rounded-2xl flex items-center justify-center border border-slate-100 text-slate-300 group-hover:bg-blue-600 group-hover:text-white transition-all">
              <ChevronLeft size={20} />
           </div>
        </div>
      </div>

      {showModal && (
        <EmployeeDetailModal employee={employee} onClose={() => setShowModal(false)} />
      )}
    </>
  );
};

const EmployeeDetailModal = ({ employee, onClose }: any) => {
    const [report, setReport] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);

    const handleAiAudit = async () => {
        if (loading) return;
        setLoading(true);
        try {
          const res = await generateDetailedAuditSummaryAI(employee);
          setReport(res.text);
        } catch (error) {
          setReport("⚠️ خطأ في التحليل.");
        } finally {
          setLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 z-[200] flex items-center justify-center p-8 bg-slate-900/70 backdrop-blur-3xl animate-in">
           <div className="bg-white w-full max-w-7xl h-[90vh] rounded-[4rem] overflow-hidden flex flex-col shadow-2xl">
              <div className="p-10 border-b border-slate-100 flex items-center justify-between">
                 <div className="flex items-center gap-6">
                    <div className="w-20 h-20 bg-slate-900 text-white rounded-[2rem] flex items-center justify-center font-black text-4xl shadow-xl">
                       {employee.name.charAt(0)}
                    </div>
                    <div>
                       <h2 className="text-3xl font-black text-slate-800">{employee.name}</h2>
