                    </div>
                 </div>
                 <button onClick={onClose} className="w-14 h-14 bg-white rounded-2xl flex items-center justify-center border border-slate-100 hover:bg-rose-50 hover:text-rose-500 transition-all shadow-sm">
                    <X size={28} />
                 </button>
              </div>
              <div className="flex-1 flex overflow-hidden">
                 <div className="w-[380px] p-12 bg-[#F8FAFC] border-l border-slate-100 overflow-y-auto bento-scroll space-y-10">
                    <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm text-center">
                       <p className="text-[11px] font-black uppercase opacity-40 mb-3 tracking-widest">معدل الالتزام</p>
                       <p className="text-7xl font-black text-blue-600">{employee.completionRate}%</p>
                    </div>
                    <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm">
                       <h4 className="text-[11px] font-black mb-8 flex items-center gap-3 uppercase text-slate-400 tracking-widest">
                         <Sparkles size={18} className="text-blue-500" /> تقرير Gemini AI
                       </h4>
                       <div className="text-[13px] font-bold text-slate-600 leading-relaxed italic whitespace-pre-line">
                          {loading ? "جاري التدقيق..." : report || "اضغط على الزر أدناه لبدء تحليل السلوك التقني لهذا الموظف."}
