                               <div className="flex items-center gap-4">
                                  <div className={`p-4 rounded-2xl ${s.status === 'مكتملة' ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
                                     <Calendar size={24} />
                                  </div>
                                  <div>
                                     <p className="text-xl font-black text-slate-800">{s.shift_date}</p>
                                  </div>
                               </div>
                               <div className={`px-6 py-2.5 rounded-2xl text-[10px] font-black shadow-sm ${s.status === 'مكتملة' ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
                                  {s.status}
                               </div>
                            </div>
                            <div className="grid grid-cols-5 gap-6">
                               {["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"].map(period => {
                                 const punch = s.punches_details.find((pd: any) => pd.period === period && !pd.is_duplicate);
                                 return (
                                   <div key={period} className={`p-6 rounded-[2.5rem] border text-center transition-all ${punch ? 'bg-white border-blue-100 shadow-md scale-105' : 'bg-slate-50 border-transparent opacity-30 grayscale'}`}>
                                      <div className="mb-3 text-blue-500 flex justify-center">{getPeriodIcon(period)}</div>
                                      <p className="text-[9px] font-black opacity-50 uppercase mb-2 truncate">{period}</p>
                                      <p className="text-sm font-black text-slate-800">{punch ? punch.time : '--:--'}</p>
                                   </div>
                                 );
                               })}
                            </div>
                         </div>
                       ))}
                    </div>
                 </div>
              </div>
           </div>
        </div>
    );
};

const getPeriodIcon = (period: string) => {
  const size = 22;
  switch (period) {
    case 'دخول صباحي': return <Sunrise size={size} />;
    case 'بصمة وسطية': return <Sun size={size} />;
    case 'بصمة مسائية': return <Sunset size={size} />;
    case 'بصمة ليلية': return <Moon size={size} />;
    case 'بصمة خروج': return <LogOutIcon size={size} />;
    default: return <Clock size={size} />;
  }
};

