import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary } from "../types";

const getAiInstance = () => {
  return new GoogleGenAI({ apiKey: process.env.API_KEY || "" });
};

export const generateDetailedAuditSummaryAI = async (employee: EmployeeSummary): Promise<{ text: string }> => {
  try {
    const ai = getAiInstance();

    const missingDays = employee.shifts
      .filter(s => s.status === 'ناقصة')
      .map(s => {
        const found = s.punches_details.filter(p => !p.is_duplicate).map(p => p.period);
        const allPossible = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
        const missing = allPossible.filter(p => !found.includes(p));
        return `📅 ${s.shift_date}: نقص في (${missing.join('، ')})`;
      });

    if (missingDays.length === 0) return { text: `👤 الموظف: ${employee.name}\n✅ الحالة: البصمات مكتملة تماماً.` };

    const prompt = `أنت مدقق تقني. قدم البيانات التالية للموظف (${employee.name}) باختصار شديد جداً:
1. الاسم
2. الحالة (ناقص/مكتمل)
3. قائمة التواريخ والبصمات المفقودة فقط.

ممنوع تماماً كتابة أي نصائح إدارية أو مقدمات. التزم بالصيغة التالية:
الاسم: [الاسم]
الحالة: [ناقص]
النواقص:
[التاريخ]: [نوع البصمة]

البيانات:
${missingDays.join('\n')}`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return { text: response.text || "لا توجد بيانات." };
  } catch (error) {
    return { text: "⚠️ خطأ في معالجة البيانات." };
  }
};

export const generateBulkAuditSummaryAI = async (employees: EmployeeSummary[]): Promise<{ text: string }> => {
  try {
    const ai = getAiInstance();
    const deficientEmployees = employees.filter(e => !e.isEligible);

    if (deficientEmployees.length === 0) return { text: "✅ جميع موظفي الكادر بصماتهم مكتملة." };

    let context = deficientEmployees.map(e => {
       const missingInfo = e.shifts.filter(s => s.status === 'ناقصة').map(s => {
          const found = s.punches_details.filter(p => !p.is_duplicate).map(p => p.period);
          const allPossible = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
          const missing = allPossible.filter(p => !found.includes(p));
          return `   - ${s.shift_date}: (${missing.join(', ')})`;
       }).join('\n');
       return `👤 ${e.name}:\n${missingInfo}`;
    }).join('\n\n');

    const prompt = `أنت مدقق نظام بصمة. قم بتلخيص النواقص للكادر المذكور أدناه.
المطلوب: اسم الموظف وتواريخ النواقص ونوع البصمة المفقودة فقط.
ممنوع: كتابة أي نصائح، مقدمات، أو تحليلات إدارية.

البيانات المراد تلخيصها:
${context}`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return { text: response.text || "فشل توليد التقرير." };
  } catch (error) {
    return { text: "⚠️ خطأ في الاتصال بالمدقق." };
  }
};

import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Fingerprint, RefreshCcw, 
  X, AlertCircle, ShieldCheck, CheckCircle2, 
  AlertTriangle, FilterX, Sparkles, Activity,
  Sunrise, Sun, Sunset, Moon, LogOut as LogOutIcon, Clock,
  FileSpreadsheet, ShieldAlert, Zap, ListChecks, ChevronLeft,
  UserX, Check
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary } from './types';

type ViewType = 'dashboard' | 'audit';
type FilterType = 'all' | 'eligible' | 'deficient';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState<FilterType>('all');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [bulkAiReport, setBulkAiReport] = useState<string | null>(null);

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const total = employees.length;
    const eligible = employees.filter(e => e.isEligible).length;
    const deficient = total - eligible;
    const totalPunches = employees.reduce((sum, e) => sum + e.totalPunches, 0);
    return { total, eligible, deficient, totalPunches };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    let result = employees;
    if (filterType === 'eligible') result = result.filter(e => e.isEligible);
    else if (filterType === 'deficient') result = result.filter(e => !e.isEligible);

    const term = searchTerm.toLowerCase();
    if (term) {
      result = result.filter(e => 
        e.name.toLowerCase().includes(term) || 
        String(e.id).includes(term)
      );
    }
    return result;
  }, [employees, searchTerm, filterType]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setCurrentView('dashboard');
        setFilterType('all');
      } catch (err) {
        alert("خطأ في قراءة ملف Excel");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleExportToExcel = () => {
    if (employees.length === 0) return;

    const summaryData = employees.map(emp => ({
      'المعرف': emp.id,
      'الاسم': emp.name,
      'إجمالي النوبات': emp.shifts.length,
      'النوبات المكتملة': emp.shifts.filter(s => s.status === 'مكتملة').length,
      'النوبات الناقصة': emp.shifts.filter(s => s.status === 'ناقصة').length,
      'نسبة الالتزام': `${emp.completionRate}%`,
      'الحالة النهائية': emp.isEligible ? 'منضبط' : 'يوجد نواقص'
    }));

    const deficiencyLogs: any[] = [];
    employees.forEach(emp => {
      emp.shifts.filter(s => s.status === 'ناقصة').forEach(shift => {
        const found = shift.punches_details.filter(p => !p.is_duplicate).map(p => p.period);
        const allPossible = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
        const missing = allPossible.filter(p => !found.includes(p));

        deficiencyLogs.push({
          'التاريخ': shift.shift_date,
          'رقم الموظف': emp.id,
          'اسم الموظف': emp.name,
          'البصمات الناقصة': missing.join(' - '),
          'البصمات الموجودة': found.join(' - ')
        });
      });
    });

    const workbook = XLSX.utils.book_new();
    const ws1 = XLSX.utils.json_to_sheet(summaryData);
    const ws2 = XLSX.utils.json_to_sheet(deficiencyLogs);
    XLSX.utils.book_append_sheet(workbook, ws1, "الملخص العام");
    XLSX.utils.book_append_sheet(workbook, ws2, "سجل النواقص الفني");
    XLSX.writeFile(workbook, `تقرير_بصمتي_التفصيلي_${new Date().toISOString().slice(0,10)}.xlsx`);
  };

  const runBulkAuditAnalysis = async () => {
    if (employees.length === 0) return;
    setCurrentView('audit');
    setIsAnalyzing(true);
    try {
      const res = await generateBulkAuditSummaryAI(employees);
      setBulkAiReport(res.text);
    } catch (e) {
      setBulkAiReport("⚠️ حدث خطأ أثناء الاتصال بالمدقق الذكي.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="flex h-screen bg-[#F8FAFC] text-[#1E293B] rtl overflow-hidden font-['Cairo']">
      <aside className={`fixed lg:static inset-y-0 right-0 z-[100] w-72 bg-white border-l border-slate-100 flex flex-col transition-all duration-500 transform ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'}`}>
        <div className="p-10">
           <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-blue-600 rounded-[1.4rem] flex items-center justify-center text-white shadow-xl shadow-blue-100">
                 <ShieldCheck size={28} />
              </div>
              <div>
                <h1 className="text-2xl font-black leading-none tracking-tight">بصمتي <span className="text-blue-600">برو</span></h1>
                <p className="text-[10px] font-bold text-slate-400 mt-1 uppercase tracking-widest">إدارة محطة الخيرات</p>
              </div>
           </div>
        </div>

        <nav className="flex-1 px-6 space-y-3">
          <NavItem icon={<LayoutDashboard size={20}/>} label="لوحة التحكم" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <NavItem icon={<ListChecks size={20}/>} label="تدقيق شامل" active={currentView === 'audit'} onClick={() => { runBulkAuditAnalysis(); setIsSidebarOpen(false); }} />
        </nav>

        <div className="p-8 space-y-4">
           <div className="bg-slate-900 rounded-[2.5rem] p-6 text-white relative overflow-hidden group">
              <div className="relative z-10">
                 <div className="flex items-center gap-2 mb-2">
                    <div className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse"></div>
                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">نظام التدقيق مفعل</span>
                 </div>
                 <p className="text-[11px] font-bold text-slate-300">يتم رصد النواقص وتوثيقها بشكل آلي وفوري.</p>
              </div>
           </div>

           <label className="flex items-center justify-center gap-3 w-full py-5 bg-blue-600 text-white rounded-[1.8rem] cursor-pointer hover:bg-blue-700 transition-all font-black text-xs shadow-xl active:scale-95 group">
              <FileUp size={22} className="group-hover:-translate-y-1 transition-transform" /> 
              <span>تحديث البيانات</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
           </label>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-[#F8FAFC] lg:rounded-r-[3.5rem] lg:my-3 lg:ml-3 border border-slate-200/50 shadow-inner overflow-hidden relative">
        <header className="h-24 px-10 flex items-center justify-between shrink-0 bg-white/40 backdrop-blur-2xl z-40 border-b border-slate-100">
          <div className="flex items-center gap-6 flex-1">
             <button className="lg:hidden p-3 bg-white rounded-2xl shadow-sm border border-slate-100" onClick={() => setIsSidebarOpen(true)}>
               <Menu size={24} />
             </button>
             <div className="relative max-w-md w-full">
                <Search className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300" size={20} />
                <input 
                  type="text" 
                  placeholder="بحث سريع..." 
                  className="w-full bg-white border-none rounded-[1.4rem] pr-14 pl-6 py-4 text-xs font-bold focus:ring-4 focus:ring-blue-500/5 transition-all shadow-sm"
