             </div>
          </div>

          <div className="flex items-center gap-4">
            <button onClick={handleExportToExcel} disabled={employees.length === 0} className="flex items-center gap-3 px-8 py-4 bg-emerald-600 text-white rounded-[1.4rem] text-[12px] font-black hover:bg-emerald-700 transition-all shadow-xl active:scale-95 disabled:opacity-40 group">
