            <button onClick={runBulkAuditAnalysis} disabled={employees.length === 0 || isAnalyzing} className="flex items-center gap-3 px-8 py-4 bg-slate-900 text-white rounded-[1.4rem] text-[12px] font-black hover:bg-blue-600 transition-all shadow-xl active:scale-95 disabled:opacity-50">
