               <span className="hidden md:inline">تدقيق الكادر</span>
            </button>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto px-10 pb-12 bento-scroll">
          {employees.length > 0 && currentView === 'dashboard' && stats && (
            <div className="pt-10 space-y-12 animate-in">
               <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
                  <BentoStatCard title="إجمالي الكادر" value={stats.total} icon={<Users size={28}/>} color="bg-blue-50" textColor="text-blue-700" active={filterType === 'all'} onClick={() => setFilterType('all')} />
                  <BentoStatCard title="بصمات مكتملة" value={stats.eligible} icon={<CheckCircle2 size={28}/>} color="bg-emerald-50" textColor="text-emerald-700" active={filterType === 'eligible'} onClick={() => setFilterType('eligible')} />
                  <BentoStatCard title="بصمات ناقصة" value={stats.deficient} icon={<ShieldAlert size={28}/>} color="bg-rose-50" textColor="text-rose-700" active={filterType === 'deficient'} onClick={() => setFilterType('deficient')} />
                  <BentoStatCard title="عمليات البصمة" value={stats.totalPunches} icon={<Fingerprint size={28}/>} color="bg-purple-50" textColor="text-purple-700" active={false} onClick={() => {}} />
