                <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pb-20">
                    {employees.map(emp => (
                        <div key={emp.id} className={`bg-white rounded-[2.5rem] p-8 border ${emp.isEligible ? 'border-emerald-100 opacity-60' : 'border-rose-100 shadow-xl shadow-rose-500/5'}`}>
                            <div className="flex justify-between items-center mb-6">
                                <div className="flex items-center gap-4">
                                    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center font-black text-xl ${emp.isEligible ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                                        {emp.name.charAt(0)}
                                    </div>
                                    <div>
                                        <h4 className="font-black text-slate-800">{emp.name}</h4>
                                        <p className="text-[10px] font-bold text-slate-400">ID: {emp.id}</p>
                                    </div>
                                </div>
                                <div className={`px-4 py-1.5 rounded-xl text-[10px] font-black flex items-center gap-2 ${emp.isEligible ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
                                    {emp.isEligible ? <Check size={14}/> : <UserX size={14}/>}
                                    {emp.isEligible ? 'مكتمل' : 'يوجد نواقص'}
                                </div>
                            </div>

                            {!emp.isEligible && (
                                <div className="space-y-3">
                                    {emp.shifts.filter(s => s.status === 'ناقصة').map((shift, idx) => {
                                        const found = shift.punches_details.filter(p => !p.is_duplicate).map(p => p.period);
                                        const allPossible = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
                                        const missing = allPossible.filter(p => !found.includes(p));
                                        return (
                                            <div key={idx} className="bg-slate-50 p-4 rounded-2xl border border-slate-100 flex items-center justify-between">
                                                <div className="flex items-center gap-3">
                                                    <Calendar size={14} className="text-slate-400" />
                                                    <span className="text-[11px] font-black">{shift.shift_date}</span>
                                                </div>
                                                <div className="flex flex-wrap gap-1 justify-end">
                                                    {missing.map(m => (
                                                        <span key={m} className="bg-rose-100 text-rose-700 px-2 py-0.5 rounded-lg text-[8px] font-black">نقص {m}</span>
                                                    ))}
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            )}
                            {emp.isEligible && <p className="text-center text-[10px] font-bold text-emerald-600">هذا الموظف ملتزم بكافة البصمات المقررة.</p>}
                        </div>
                    ))}
                </div>
            </div>
          )}

          {employees.length === 0 && <EmptyState handleFileUpload={handleFileUpload} isAnalyzing={isAnalyzing} />}
        </div>
      </main>
    </div>
  );
};

