        {isAnalyzing ? <RefreshCcw size={74} className="animate-spin" /> : <Fingerprint size={74} />}
     </div>
     <h3 className="text-5xl font-black mb-6 tracking-tight text-slate-800">نظام بصمتي برو</h3>
     <p className="text-base text-slate-400 font-bold max-w-lg mb-14 leading-loose">يرجى رفع ملف البصمة Excel للبدء في تدقيق بيانات الكادر ورصد النواقص بشكل آلي.</p>
     <label className="px-16 py-7 bg-slate-900 text-white rounded-[2.2rem] font-black cursor-pointer shadow-2xl hover:bg-blue-600 transition-all flex items-center gap-5 group">
        <FileUp size={32} /> <span className="text-lg">استيراد الملف الآن</span>
        <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
     </label>
  </div>
);

export default App;

import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Fingerprint, RefreshCcw, 
  X, AlertCircle, ShieldCheck, CheckCircle2, 
  AlertTriangle, FilterX, Sparkles, Activity,
  Sunrise, Sun, Sunset, Moon, LogOut as LogOutIcon, Clock,
  FileSpreadsheet, ShieldAlert, Zap, ListChecks, ChevronLeft,
  UserX, Check
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary } from './types';

type ViewType = 'dashboard' | 'audit';
type FilterType = 'all' | 'eligible' | 'deficient';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState<FilterType>('all');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [bulkAiReport, setBulkAiReport] = useState<string | null>(null);

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const total = employees.length;
    const eligible = employees.filter(e => e.isEligible).length;
    const deficient = total - eligible;
    const totalPunches = employees.reduce((sum, e) => sum + e.totalPunches, 0);
    return { total, eligible, deficient, totalPunches };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    let result = employees;
    if (filterType === 'eligible') result = result.filter(e => e.isEligible);
    else if (filterType === 'deficient') result = result.filter(e => !e.isEligible);

    const term = searchTerm.toLowerCase();
    if (term) {
      result = result.filter(e => 
        e.name.toLowerCase().includes(term) || 
        String(e.id).includes(term)
      );
    }
    return result;
  }, [employees, searchTerm, filterType]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setCurrentView('dashboard');
        setFilterType('all');
      } catch (err) {
        alert("خطأ في قراءة ملف Excel");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleExportToExcel = () => {
    if (employees.length === 0) return;
    const summaryData = employees.map(emp => ({
      'المعرف': emp.id,
      'الاسم': emp.name,
      'النوبات': emp.shifts.length,
      'مكتملة': emp.shifts.filter(s => s.status === 'مكتملة').length,
      'ناقصة': emp.shifts.filter(s => s.status === 'ناقصة').length,
      'الالتزام': `${emp.completionRate}%`,
      'الحالة': emp.isEligible ? 'منضبط' : 'نواقص'
    }));

    const deficiencyLogs: any[] = [];
    employees.forEach(emp => {
      emp.shifts.filter(s => s.status === 'ناقصة').forEach(shift => {
        const found = shift.punches_details.filter(p => !p.is_duplicate).map(p => p.period);
        const allPossible = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
        const missing = allPossible.filter(p => !found.includes(p));
        deficiencyLogs.push({
          'التاريخ': shift.shift_date,
          'رقم الموظف': emp.id,
          'اسم الموظف': emp.name,
          'البصمات الناقصة': missing.join(' - ')
        });
      });
    });

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(summaryData), "الملخص");
    XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(deficiencyLogs), "النواقص");
    XLSX.writeFile(workbook, `Basmati_Pro_Report_${new Date().toISOString().slice(0,10)}.xlsx`);
  };

  const runBulkAuditAnalysis = async () => {
    if (employees.length === 0) return;
    setCurrentView('audit');
    setIsAnalyzing(true);
    try {
      const res = await generateBulkAuditSummaryAI(employees);
      setBulkAiReport(res.text);
    } catch (e) {
      setBulkAiReport("⚠️ خطأ في الاتصال بالمدقق.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="flex h-screen bg-[#F8FAFC] text-[#1E293B] rtl overflow-hidden font-['Cairo'] text-sm">
      {/* Sidebar - Smaller Width */}
      <aside className={`fixed lg:static inset-y-0 right-0 z-[100] w-64 bg-white border-l border-slate-100 flex flex-col transition-all duration-500 transform ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0 shadow-xl lg:shadow-none'}`}>
        <div className="p-6">
           <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg">
                 <ShieldCheck size={22} />
              </div>
              <div>
                <h1 className="text-xl font-black leading-none">بصمتي <span className="text-blue-600">برو</span></h1>
                <p className="text-[9px] font-bold text-slate-400 mt-1 uppercase tracking-widest">محطة الخيرات</p>
              </div>
           </div>
        </div>

        <nav className="flex-1 px-4 space-y-2">
          <NavItem icon={<LayoutDashboard size={18}/>} label="الرئيسية" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <NavItem icon={<ListChecks size={18}/>} label="تدقيق شامل" active={currentView === 'audit'} onClick={() => { runBulkAuditAnalysis(); setIsSidebarOpen(false); }} />
        </nav>

        <div className="p-6 space-y-3">
           <div className="bg-slate-900 rounded-2xl p-4 text-white relative overflow-hidden group">
              <div className="relative z-10">
                 <div className="flex items-center gap-1.5 mb-1">
                    <div className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse"></div>
                    <span className="text-[8px] font-black text-slate-400 uppercase tracking-widest">AI Audit Active</span>
                 </div>
                 <p className="text-[10px] font-bold text-slate-300">المدقق الذكي يرصد النواقص بدقة.</p>
              </div>
           </div>

           <label className="flex items-center justify-center gap-2 w-full py-3 bg-blue-600 text-white rounded-xl cursor-pointer hover:bg-blue-700 transition-all font-black text-[11px] shadow-md active:scale-95 group">
              <FileUp size={16} /> 
              <span>استيراد ملف</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
           </label>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-[#F8FAFC] lg:rounded-r-[2.5rem] lg:my-2 lg:ml-2 border border-slate-200/50 shadow-inner overflow-hidden relative">
        <header className="h-16 px-6 flex items-center justify-between shrink-0 bg-white/60 backdrop-blur-xl z-40 border-b border-slate-100">
          <div className="flex items-center gap-4 flex-1">
             <button className="lg:hidden p-2 bg-white rounded-xl shadow-sm border border-slate-100" onClick={() => setIsSidebarOpen(true)}>
               <Menu size={20} />
             </button>
             <div className="relative max-w-sm w-full">
                <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
                <input 
                  type="text" 
                  placeholder="بحث سريع..." 
                  className="w-full bg-white border-none rounded-xl pr-10 pl-4 py-2.5 text-[11px] font-bold focus:ring-2 focus:ring-blue-500/20 transition-all shadow-sm"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
             </div>
          </div>

          <div className="flex items-center gap-3">
            <button onClick={handleExportToExcel} disabled={employees.length === 0} className="flex items-center gap-2 px-5 py-2.5 bg-emerald-600 text-white rounded-xl text-[11px] font-black hover:bg-emerald-700 transition-all shadow-md active:scale-95 disabled:opacity-40 group">
               <FileSpreadsheet size={16} /> <span className="hidden sm:inline">تقرير Excel</span>
            </button>
            <button onClick={runBulkAuditAnalysis} disabled={employees.length === 0 || isAnalyzing} className="flex items-center gap-2 px-5 py-2.5 bg-slate-900 text-white rounded-xl text-[11px] font-black hover:bg-blue-600 transition-all shadow-md active:scale-95 disabled:opacity-50">
               {isAnalyzing ? <RefreshCcw size={16} className="animate-spin" /> : <BrainCircuit size={16} />}
               <span className="hidden sm:inline">تدقيق شامل</span>
            </button>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto px-6 pb-8 bento-scroll">
          {employees.length > 0 && currentView === 'dashboard' && stats && (
            <div className="pt-6 space-y-8 animate-in">
               <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                  <BentoStatCard title="إجمالي الكادر" value={stats.total} icon={<Users size={20}/>} color="bg-blue-50" textColor="text-blue-700" active={filterType === 'all'} onClick={() => setFilterType('all')} />
                  <BentoStatCard title="بصمات مكتملة" value={stats.eligible} icon={<CheckCircle2 size={20}/>} color="bg-emerald-50" textColor="text-emerald-700" active={filterType === 'eligible'} onClick={() => setFilterType('eligible')} />
                  <BentoStatCard title="بصمات ناقصة" value={stats.deficient} icon={<ShieldAlert size={20}/>} color="bg-rose-50" textColor="text-rose-700" active={filterType === 'deficient'} onClick={() => setFilterType('deficient')} />
                  <BentoStatCard title="عمليات البصمة" value={stats.totalPunches} icon={<Fingerprint size={20}/>} color="bg-purple-50" textColor="text-purple-700" active={false} onClick={() => {}} />
               </div>

               <div className="flex items-center justify-between border-b border-slate-100 pb-3">
                 <h2 className="text-xl font-black text-slate-800">قائمة الكادر الوظيفي</h2>
                 <div className="flex gap-1.5">
                    <FilterButton label="الكل" active={filterType === 'all'} onClick={() => setFilterType('all')} />
                    <FilterButton label="مكتمل" active={filterType === 'eligible'} onClick={() => setFilterType('eligible')} />
                    <FilterButton label="ناقص" active={filterType === 'deficient'} onClick={() => setFilterType('deficient')} />
                 </div>
               </div>

               <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4 gap-6">
                  {filteredEmployees.map((emp) => (
                    <EmployeeCard key={emp.id} employee={emp} />
                  ))}
               </div>
            </div>
          )}

          {currentView === 'audit' && (
            <div className="pt-6 space-y-6 animate-in max-w-5xl mx-auto">
                <div className="flex items-center gap-3">
                    <button onClick={() => setCurrentView('dashboard')} className="p-2 bg-white rounded-xl shadow-sm border border-slate-100 hover:bg-slate-50 transition-all">
                        <ChevronLeft size={18} />
                    </button>
                    <h2 className="text-xl font-black text-slate-800">منصة التدقيق الجماعي</h2>
                </div>

                <div className="bg-white rounded-3xl p-6 shadow-xl border border-slate-100">
                   <div className="flex items-center gap-3 mb-4">
                      <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
                         <BrainCircuit size={18} />
                      </div>
                      <h3 className="text-md font-black">تقرير النواقص الذكي (Gemini)</h3>
                   </div>
                   <div className="bg-[#F8FAFC] p-6 rounded-2xl text-[11px] font-bold text-slate-700 leading-relaxed whitespace-pre-line border border-slate-100">
                      {isAnalyzing ? "جاري التدقيق..." : bulkAiReport || "لا توجد سجلات."}
                   </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pb-12">
                    {employees.map(emp => (
                        <div key={emp.id} className={`bg-white rounded-2xl p-5 border ${emp.isEligible ? 'border-emerald-100 opacity-60' : 'border-rose-100 shadow-md'}`}>
                            <div className="flex justify-between items-center mb-4">
                                <div className="flex items-center gap-3">
                                    <div className={`w-10 h-10 rounded-xl flex items-center justify-center font-black text-md ${emp.isEligible ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                                        {emp.name.charAt(0)}
                                    </div>
                                    <div>
                                        <h4 className="font-black text-slate-800 text-[12px]">{emp.name}</h4>
                                        <p className="text-[9px] font-bold text-slate-400">ID: {emp.id}</p>
                                    </div>
                                </div>
                                <div className={`px-3 py-1 rounded-lg text-[8px] font-black flex items-center gap-1.5 ${emp.isEligible ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
                                    {emp.isEligible ? <Check size={12}/> : <UserX size={12}/>}
                                    {emp.isEligible ? 'مكتمل' : 'ناقص'}
                                </div>
                            </div>
                            {!emp.isEligible && (
                                <div className="space-y-2">
                                    {emp.shifts.filter(s => s.status === 'ناقصة').map((shift, idx) => {
                                        const found = shift.punches_details.filter(p => !p.is_duplicate).map(p => p.period);
                                        const allPossible = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
                                        const missing = allPossible.filter(p => !found.includes(p));
                                        return (
                                            <div key={idx} className="bg-slate-50 p-2.5 rounded-xl border border-slate-100 flex items-center justify-between text-[10px]">
                                                <span className="font-black">{shift.shift_date}</span>
                                                <div className="flex flex-wrap gap-1 justify-end">
                                                    {missing.map(m => (
                                                        <span key={m} className="bg-rose-100 text-rose-700 px-1.5 py-0.5 rounded-md text-[7px] font-black">نقص {m}</span>
                                                    ))}
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            )}
                        </div>
                    ))}
                </div>
            </div>
          )}

          {employees.length === 0 && <EmptyState handleFileUpload={handleFileUpload} isAnalyzing={isAnalyzing} />}
        </div>
      </main>
    </div>
  );
};

