     </div>
     <h3 className="text-3xl font-black mb-4 text-slate-800 tracking-tight">بصمتي برو</h3>
     <p className="text-[12px] text-slate-400 font-bold max-w-sm mb-10 leading-loose">يرجى رفع ملف البصمة Excel للبدء في تدقيق بيانات الكادر بشكل آلي وفوري.</p>
     <label className="px-10 py-5 bg-slate-900 text-white rounded-2xl font-black cursor-pointer shadow-xl hover:bg-blue-600 transition-all flex items-center gap-3 active:scale-95 group">
        <FileUp size={24} /> <span className="text-md">استيراد ملف البصمة</span>
        <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
     </label>
  </div>
);

export default App;

import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Fingerprint, RefreshCcw, 
  X, AlertCircle, ShieldCheck, CheckCircle2, 
  AlertTriangle, FilterX, Sparkles, Activity,
  Sunrise, Sun, Sunset, Moon, LogOut as LogOutIcon, Clock,
  FileSpreadsheet, ShieldAlert, Zap, ListChecks, ChevronLeft,
  UserX, Check
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary } from './types';

type ViewType = 'dashboard' | 'audit';
type FilterType = 'all' | 'eligible' | 'deficient';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterType, setFilterType] = useState<FilterType>('all');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');
  const [bulkAiReport, setBulkAiReport] = useState<string | null>(null);

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const total = employees.length;
    const eligible = employees.filter(e => e.isEligible).length;
    const deficient = total - eligible;
    const totalPunches = employees.reduce((sum, e) => sum + e.totalPunches, 0);
    return { total, eligible, deficient, totalPunches };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    let result = employees;
    if (filterType === 'eligible') result = result.filter(e => e.isEligible);
    else if (filterType === 'deficient') result = result.filter(e => !e.isEligible);

    const term = searchTerm.toLowerCase();
    if (term) {
      result = result.filter(e => 
        e.name.toLowerCase().includes(term) || 
        String(e.id).includes(term)
      );
    }
    return result;
  }, [employees, searchTerm, filterType]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setCurrentView('dashboard');
        setFilterType('all');
      } catch (err) {
        alert("خطأ في قراءة ملف Excel");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleExportToExcel = () => {
    if (employees.length === 0) return;
    const summaryData = employees.map(emp => ({
      'المعرف': emp.id,
      'الاسم': emp.name,
      'النوبات': emp.shifts.length,
      'مكتملة': emp.shifts.filter(s => s.status === 'مكتملة').length,
      'ناقصة': emp.shifts.filter(s => s.status === 'ناقصة').length,
      'الالتزام': `${emp.completionRate}%`,
      'الحالة': emp.isEligible ? 'منضبط' : 'نواقص'
    }));

    const deficiencyLogs: any[] = [];
    employees.forEach(emp => {
      emp.shifts.filter(s => s.status === 'ناقصة').forEach(shift => {
        const found = shift.punches_details.filter(p => !p.is_duplicate).map(p => p.period);
        const allPossible = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
        const missing = allPossible.filter(p => !found.includes(p));
        deficiencyLogs.push({
          'التاريخ': shift.shift_date,
          'رقم الموظف': emp.id,
          'اسم الموظف': emp.name,
          'البصمات الناقصة': missing.join(' - ')
        });
      });
    });

    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(summaryData), "الملخص");
    XLSX.utils.book_append_sheet(workbook, XLSX.utils.json_to_sheet(deficiencyLogs), "النواقص");
    XLSX.writeFile(workbook, `Basmati_Pro_Report_${new Date().toISOString().slice(0,10)}.xlsx`);
  };

  const runBulkAuditAnalysis = async () => {
    if (employees.length === 0) return;
    setCurrentView('audit');
    setIsAnalyzing(true);
    try {
      const res = await generateBulkAuditSummaryAI(employees);
      setBulkAiReport(res.text);
    } catch (e) {
      setBulkAiReport("⚠️ خطأ في الاتصال بالمدقق.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="flex h-screen bg-[#F8FAFC] text-[#1E293B] rtl overflow-hidden font-['Cairo'] text-sm">
      <aside className={`fixed lg:static inset-y-0 right-0 z-[100] w-64 bg-white border-l border-slate-100 flex flex-col transition-all duration-500 transform ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0 shadow-xl lg:shadow-none'}`}>
        <div className="p-6">
           <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg">
                 <ShieldCheck size={22} />
              </div>
              <div>
                <h1 className="text-xl font-black leading-none">بصمتي <span className="text-blue-600">برو</span></h1>
                <p className="text-[9px] font-bold text-slate-400 mt-1 uppercase tracking-widest">محطة الخيرات</p>
              </div>
           </div>
        </div>

        <nav className="flex-1 px-4 space-y-2">
          <NavItem icon={<LayoutDashboard size={18}/>} label="الرئيسية" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <NavItem icon={<ListChecks size={18}/>} label="تدقيق شامل" active={currentView === 'audit'} onClick={() => { runBulkAuditAnalysis(); setIsSidebarOpen(false); }} />
        </nav>

        <div className="p-6 mt-auto border-t border-slate-50 space-y-3">
           <label className="flex items-center justify-center gap-2 w-full py-3 bg-blue-600 text-white rounded-xl cursor-pointer hover:bg-blue-700 transition-all font-black text-[11px] shadow-md active:scale-95 group">
              <FileUp size={16} /> 
              <span>استيراد ملف</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
           </label>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 bg-[#F8FAFC] lg:rounded-r-[2.5rem] lg:my-2 lg:ml-2 border border-slate-200/50 shadow-inner overflow-hidden relative">
        <header className="h-16 px-6 flex items-center justify-between shrink-0 bg-white/60 backdrop-blur-xl z-[50] border-b border-slate-100">
          <div className="flex items-center gap-4 flex-1">
             <button className="lg:hidden p-2 bg-white rounded-xl shadow-sm border border-slate-100" onClick={() => setIsSidebarOpen(true)}>
               <Menu size={20} />
             </button>
             <div className="relative max-w-sm w-full">
                <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
                <input 
                  type="text" 
                  placeholder="بحث سريع..." 
                  className="w-full bg-white border-none rounded-xl pr-10 pl-4 py-2.5 text-[11px] font-bold focus:ring-2 focus:ring-blue-500/20 transition-all shadow-sm"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
             </div>
          </div>

          <div className="flex items-center gap-3">
            <button onClick={handleExportToExcel} disabled={employees.length === 0} className="flex items-center gap-2 px-5 py-2.5 bg-emerald-600 text-white rounded-xl text-[11px] font-black hover:bg-emerald-700 transition-all shadow-md active:scale-95 disabled:opacity-40">
               <FileSpreadsheet size={16} /> <span className="hidden sm:inline">تصدير Excel</span>
            </button>
            <button onClick={runBulkAuditAnalysis} disabled={employees.length === 0 || isAnalyzing} className="flex items-center gap-2 px-5 py-2.5 bg-slate-900 text-white rounded-xl text-[11px] font-black hover:bg-blue-600 transition-all shadow-md active:scale-95 disabled:opacity-50">
               {isAnalyzing ? <RefreshCcw size={16} className="animate-spin" /> : <BrainCircuit size={16} />}
               <span className="hidden sm:inline">تدقيق شامل</span>
            </button>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto px-6 pb-8 bento-scroll">
          {employees.length > 0 && currentView === 'dashboard' && stats && (
            <div className="pt-6 space-y-8 animate-in">
               <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                  <BentoStatCard title="إجمالي الكادر" value={stats.total} icon={<Users size={20}/>} color="bg-blue-50" textColor="text-blue-700" active={filterType === 'all'} onClick={() => setFilterType('all')} />
                  <BentoStatCard title="بصمات مكتملة" value={stats.eligible} icon={<CheckCircle2 size={20}/>} color="bg-emerald-50" textColor="text-emerald-700" active={filterType === 'eligible'} onClick={() => setFilterType('eligible')} />
                  <BentoStatCard title="بصمات ناقصة" value={stats.deficient} icon={<ShieldAlert size={20}/>} color="bg-rose-50" textColor="text-rose-700" active={filterType === 'deficient'} onClick={() => setFilterType('deficient')} />
                  <BentoStatCard title="عمليات البصمة" value={stats.totalPunches} icon={<Fingerprint size={20}/>} color="bg-purple-50" textColor="text-purple-700" active={false} onClick={() => {}} />
               </div>

               <div className="flex items-center justify-between border-b border-slate-100 pb-3">
                 <h2 className="text-xl font-black text-slate-800">سجل الموظفين</h2>
                 <div className="flex gap-1.5">
                    <FilterButton label="الكل" active={filterType === 'all'} onClick={() => setFilterType('all')} />
                    <FilterButton label="مكتمل" active={filterType === 'eligible'} onClick={() => setFilterType('eligible')} />
                    <FilterButton label="ناقص" active={filterType === 'deficient'} onClick={() => setFilterType('deficient')} />
                 </div>
               </div>

               <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 2xl:grid-cols-4 gap-6">
                  {filteredEmployees.map((emp) => (
                    <EmployeeCard key={emp.id} employee={emp} />
                  ))}
               </div>
            </div>
          )}

          {currentView === 'audit' && (
            <div className="pt-6 space-y-6 animate-in max-w-5xl mx-auto">
                <div className="flex items-center gap-3">
                    <button onClick={() => setCurrentView('dashboard')} className="p-2 bg-white rounded-xl shadow-sm border border-slate-100 hover:bg-slate-50 transition-all">
                        <ChevronLeft size={18} />
                    </button>
                    <h2 className="text-xl font-black text-slate-800">نتائج التدقيق</h2>
                </div>

                <div className="bg-white rounded-3xl p-6 shadow-xl border border-slate-100">
                   <div className="flex items-center gap-3 mb-4">
                      <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center text-white">
                         <BrainCircuit size={18} />
                      </div>
                      <h3 className="text-md font-black">رصد النواقص الذكي</h3>
                   </div>
                   <div className="bg-[#F8FAFC] p-6 rounded-2xl text-[11px] font-bold text-slate-700 leading-relaxed whitespace-pre-line border border-slate-100">
                      {isAnalyzing ? "جاري التدقيق..." : bulkAiReport || "لا توجد سجلات ناقصة."}
                   </div>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pb-12">
                    {employees.filter(e => !e.isEligible).map(emp => (
                        <div key={emp.id} className="bg-white rounded-2xl p-5 border border-rose-100 shadow-md">
                            <div className="flex justify-between items-center mb-4">
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 rounded-xl bg-rose-50 text-rose-600 flex items-center justify-center font-black text-md">
                                        {emp.name.charAt(0)}
                                    </div>
                                    <div>
                                        <h4 className="font-black text-slate-800 text-[12px]">{emp.name}</h4>
                                        <p className="text-[9px] font-bold text-slate-400">ID: {emp.id}</p>
                                    </div>
                                </div>
                                <div className="px-3 py-1 rounded-lg text-[8px] font-black bg-rose-500 text-white flex items-center gap-1.5">
                                    <UserX size={12}/> ناقص
                                </div>
                            </div>
                            <div className="space-y-2">
                                {emp.shifts.filter(s => s.status === 'ناقصة').map((shift, idx) => {
                                    const found = shift.punches_details.filter(p => !p.is_duplicate).map(p => p.period);
                                    const allPossible = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
                                    const missing = allPossible.filter(p => !found.includes(p));
                                    return (
                                        <div key={idx} className="bg-slate-50 p-2.5 rounded-xl border border-slate-100 flex items-center justify-between text-[10px]">
                                            <span className="font-black">{shift.shift_date}</span>
                                            <div className="flex flex-wrap gap-1 justify-end">
                                                {missing.map(m => (
                                                    <span key={m} className="bg-rose-100 text-rose-700 px-1.5 py-0.5 rounded-md text-[7px] font-black">{m}</span>
                                                ))}
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>
                        </div>
                    ))}
                </div>
            </div>
          )}

          {employees.length === 0 && <EmptyState handleFileUpload={handleFileUpload} isAnalyzing={isAnalyzing} />}
        </div>
      </main>
    </div>
  );
};

/* Components */

const NavItem = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-3 px-6 py-3.5 rounded-xl text-[11px] font-black transition-all ${active ? 'bg-blue-50 text-blue-600 border border-blue-100 shadow-sm' : 'text-slate-400 hover:bg-slate-50'}`}>
    {icon} <span>{label}</span>
  </button>
);

const FilterButton = ({ label, active, onClick }: any) => (
  <button onClick={onClick} className={`px-4 py-1.5 rounded-lg text-[10px] font-black transition-all ${active ? 'bg-blue-600 text-white shadow-md' : 'bg-white text-slate-400 border border-slate-100'}`}>
    {label}
  </button>
);

const BentoStatCard = ({ title, value, icon, color, textColor, active, onClick }: any) => (
  <div onClick={onClick} className={`p-6 rounded-[2rem] ${color} ${textColor} flex flex-col justify-between min-h-[140px] cursor-pointer transition-all duration-300 relative overflow-hidden ${active ? 'ring-2 ring-blue-500 scale-[1.02] shadow-lg z-10' : 'hover:scale-[1.01] shadow-sm'}`}>
     <div className="flex justify-between items-start relative z-10">
        <div className="w-10 h-10 bg-white/80 backdrop-blur-md rounded-xl flex items-center justify-center shadow-sm border border-white">{icon}</div>
        <span className="text-[9px] font-black uppercase tracking-widest opacity-60 text-left">{title}</span>
     </div>
     <div className="relative z-10">
        <h4 className="text-4xl font-black mt-2 tracking-tighter">{value}</h4>
     </div>
  </div>
);

const EmployeeCard = ({ employee }: { employee: EmployeeSummary }) => {
  const [showModal, setShowModal] = useState(false);
  const isComplete = employee.isEligible;

  return (
    <>
      <div onClick={() => setShowModal(true)} className={`p-6 rounded-3xl cursor-pointer border border-slate-100 flex flex-col gap-4 hover:-translate-y-1 transition-all group shadow-sm bg-white hover:shadow-xl ${!isComplete ? 'ring-1 ring-rose-100' : ''}`}>
        <div className="flex items-start justify-between">
           <div className={`w-12 h-12 rounded-xl flex items-center justify-center font-black text-xl shadow-sm border ${isComplete ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-rose-50 text-rose-600 border-rose-100'}`}>
             {employee.name.charAt(0)}
           </div>
           <div className={`px-3 py-1 rounded-lg text-[9px] font-black shadow-sm ${isComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
              {isComplete ? 'مكتمل' : 'ناقص'}
           </div>
        </div>
        <div>
           <h3 className="text-[13px] font-black truncate text-slate-800">{employee.name}</h3>
           <p className="text-[9px] font-bold text-slate-400 mt-0.5 uppercase">ID: {employee.id}</p>
        </div>
        <div className="mt-auto flex items-center justify-between pt-4 border-t border-slate-50">
           <div className="flex items-center gap-2 text-[10px] font-black text-slate-600">
              <Fingerprint size={14} className="text-blue-500" />
              <span>{employee.totalPunches} بصمة</span>
           </div>
           <ChevronLeft size={16} className="text-slate-300 group-hover:text-blue-600 transition-colors" />
        </div>
      </div>
      {showModal && <EmployeeDetailModal employee={employee} onClose={() => setShowModal(false)} />}
    </>
  );
};

const EmployeeDetailModal = ({ employee, onClose }: any) => {
    const [report, setReport] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);

    const handleAiAudit = async () => {
        setLoading(true);
        try {
          const res = await generateDetailedAuditSummaryAI(employee);
          setReport(res.text);
        } catch (error) {
          setReport("⚠️ خطأ.");
        } finally {
          setLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-xl animate-in">
           <div className="bg-white w-full max-w-6xl h-[90vh] rounded-[2.5rem] overflow-hidden flex flex-col shadow-2xl relative">
              {/* Floating Close Button to ensure visibility */}
              <button 
                onClick={onClose} 
                className="absolute top-6 left-6 z-[10000] w-12 h-12 bg-white rounded-2xl flex items-center justify-center border border-slate-200 hover:bg-rose-50 hover:text-rose-500 hover:rotate-90 transition-all shadow-xl active:scale-90"
                title="إغلاق"
              >
                <X size={24} strokeWidth={3} />
              </button>

              <div className="p-8 border-b border-slate-100 flex items-center justify-between bg-white">
                 <div className="flex items-center gap-5">
                    <div className="w-16 h-16 bg-slate-900 text-white rounded-2xl flex items-center justify-center font-black text-3xl shadow-lg">
                       {employee.name.charAt(0)}
                    </div>
                    <div>
                       <h2 className="text-2xl font-black text-slate-800">{employee.name}</h2>
                       <p className="text-[11px] font-bold text-slate-400 uppercase tracking-widest">سجل البصمات اليومي</p>
                    </div>
                 </div>
                 {/* Empty space for the floating close button on the left */}
                 <div className="w-12"></div>
              </div>

              <div className="flex-1 flex overflow-hidden">
                 {/* Sidebar AI Info */}
                 <div className="w-80 p-8 bg-[#F8FAFC] border-l border-slate-100 overflow-y-auto bento-scroll space-y-8">
                    <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm text-center">
                       <p className="text-[10px] font-black uppercase opacity-40 mb-2 tracking-widest">نسبة الانضباط</p>
                       <p className="text-6xl font-black text-blue-600">{employee.completionRate}%</p>
                    </div>
                    <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm relative overflow-hidden group">
                       <h4 className="text-[11px] font-black mb-4 flex items-center gap-2 uppercase text-slate-400 tracking-widest">
                         <Sparkles size={16} className="text-blue-500" /> تقرير النواقص
                       </h4>
                       <div className="text-[12px] font-bold text-slate-700 leading-relaxed whitespace-pre-line bg-slate-50 p-4 rounded-xl border border-slate-100 min-h-[60px]">
                          {loading ? (
                             <div className="flex items-center gap-2 text-blue-500 animate-pulse">
                               <RefreshCcw size={14} className="animate-spin" /> جاري التدقيق...
                             </div>
                          ) : report || "اضغط على الزر أدناه لبدء فحص السجل."}
                       </div>
                       {!report && !loading && (
                          <button onClick={handleAiAudit} className="mt-6 w-full py-4 bg-slate-900 text-white rounded-xl font-black text-[11px] hover:bg-blue-600 transition-all flex items-center justify-center gap-2 shadow-lg">
                             <BrainCircuit size={16} /> فحص السجل ذكياً
                          </button>
                       )}
                       <Zap className="absolute -bottom-6 -right-6 text-blue-500/5 group-hover:scale-125 transition-transform duration-700" size={80} />
                    </div>
                 </div>

                 {/* Main Table Content */}
                 <div className="flex-1 p-10 overflow-y-auto bento-scroll bg-white">
                    <div className="grid gap-8">
                       {employee.shifts.map((s: any, i: number) => (
                         <div key={i} className={`p-8 rounded-[2rem] border transition-all duration-300 ${s.status === 'مكتملة' ? 'bg-[#DCFCE7]/20 border-emerald-100' : 'bg-[#FCE7F3]/20 border-rose-100'}`}>
                            <div className="flex justify-between items-center mb-8">
                               <div className="flex items-center gap-4">
                                  <div className={`p-4 rounded-xl ${s.status === 'مكتملة' ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
                                     <Calendar size={20} />
                                  </div>
                                  <div>
                                     <p className="text-lg font-black text-slate-800">{s.shift_date}</p>
                                     <p className="text-[10px] font-bold text-slate-400">{new Date(s.shift_date).toLocaleDateString('ar-EG', { weekday: 'long' })}</p>
                                  </div>
                               </div>
                               <div className={`px-5 py-2 rounded-xl text-[10px] font-black shadow-sm ${s.status === 'مكتملة' ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
                                  سجل {s.status}
                               </div>
                            </div>
                            <div className="grid grid-cols-5 gap-4">
                               {["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"].map(period => {
                                 const punch = s.punches_details.find((pd: any) => pd.period === period && !pd.is_duplicate);
                                 return (
                                   <div key={period} className={`p-5 rounded-2xl border text-center transition-all ${punch ? 'bg-white border-blue-100 shadow-md scale-105' : 'bg-slate-50 border-transparent opacity-30 grayscale'}`}>
                                      <div className="mb-2 text-blue-500 flex justify-center">{getPeriodIcon(period)}</div>
                                      <p className="text-[9px] font-black opacity-50 uppercase mb-1 truncate">{period}</p>
                                      <p className="text-[12px] font-black text-slate-800">{punch ? punch.time : '--:--'}</p>
                                   </div>
                                 );
                               })}
                            </div>
                         </div>
                       ))}
                    </div>
                 </div>
              </div>
           </div>
        </div>
    );
};

const getPeriodIcon = (period: string) => {
  const size = 20;
  switch (period) {
    case 'دخول صباحي': return <Sunrise size={size} />;
    case 'بصمة وسطية': return <Sun size={size} />;
    case 'بصمة مسائية': return <Sunset size={size} />;
    case 'بصمة ليلية': return <Moon size={size} />;
    case 'بصمة خروج': return <LogOutIcon size={size} />;
    default: return <Clock size={size} />;
  }
};

const EmptyState = ({ handleFileUpload, isAnalyzing }: any) => (
  <div className="h-full flex flex-col items-center justify-center text-center p-12">
     <div className="w-24 h-24 bg-blue-600 text-white rounded-3xl flex items-center justify-center shadow-2xl mb-8 relative group">
        <div className="absolute inset-0 bg-blue-400 rounded-3xl animate-ping opacity-20"></div>
        {isAnalyzing ? <RefreshCcw size={44} className="animate-spin" /> : <Fingerprint size={44} />}
     </div>
     <h3 className="text-4xl font-black mb-4 text-slate-800 tracking-tight">بصمتي برو</h3>
     <p className="text-[13px] text-slate-400 font-bold max-w-sm mb-12 leading-loose">يرجى رفع ملف البصمة Excel للبدء في تدقيق بيانات الكادر بشكل آلي وفوري.</p>
     <label className="px-12 py-5 bg-slate-900 text-white rounded-2xl font-black cursor-pointer shadow-xl hover:bg-blue-600 transition-all flex items-center gap-4 active:scale-95 group">
        <FileUp size={28} /> <span className="text-md">استيراد ملف البصمة</span>
        <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
     </label>
  </div>
);

export default App;
